window.QUIZ_INDEX = [{"id": "mock1", "file": "mock1.json", "title": "Mô phỏng KIIP cấp 5 - Đề 1", "count": 36}, {"id": "round4", "file": "round4.json", "title": "Mô phỏng KIIP cấp 5 - 5단계 4회", "count": 36}, {"id": "round2", "file": "round2.json", "title": "Mô phỏng KIIP cấp 5 - 5단계 2회", "count": 36}, {"id": "round1", "file": "round1.json", "title": "Mô phỏng KIIP cấp 5 - 5단계 1회", "count": 36}, {"id": "geo8", "file": "geo8.json", "title": "Ôn tập Địa lý - 5단계 bài 8", "count": 20}, {"id": "hist7", "file": "hist7.json", "title": "Ôn tập Lịch sử - 5단계 bài 7", "count": 20}, {"id": "law6", "file": "law6.json", "title": "Ôn tập Pháp luật - 5단계 bài 6", "count": 20}, {"id": "econ5", "file": "econ5.json", "title": "Ôn tập Kinh tế - 5단계 bài 5", "count": 20}, {"id": "pol4", "file": "pol4.json", "title": "Ôn tập Chính trị - 5단계 bài 4", "count": 20}, {"id": "edu2", "file": "edu2.json", "title": "Ôn tập Giáo dục - 5단계 bài 2", "count": 19}, {"id": "soc1", "file": "soc1.json", "title": "Ôn tập Xã hội - 5단계 bài 1", "count": 11}, {"id": "kinat", "file": "kinat.json", "title": "KIIP 영주용 종합평가 (KINAT)", "count": 36}];
window.QUIZ_DATA = {"mock1": {"title": "Mô phỏng KIIP cấp 5 - Đề 1", "source": "한국어_모의고사_(출처_예듀).docx", "questions": [{"num": 1, "correct": "D", "stem": "이 영화는 유명한 배우들이 출연하면서 개봉 전부터 ( )이/가 되었다. ( )", "options": [{"label": "A", "text": "인기"}, {"label": "B", "text": "작품"}, {"label": "C", "text": "주연"}, {"label": "D", "text": "화제"}], "correct_source": "docx", "explanation": "\"화제가 되다\" = trở thành đề tài bàn tán / chủ đề hot. Phim có diễn viên nổi tiếng nên \"trở thành chủ đề hot\" ngay trước khi công chiếu.\n① 인기 thường đi với \"인기를 얻다/끌다\", không dùng \"인기가 되다\".\n② 작품(tác phẩm) không hợp nghĩa \"trở thành tác phẩm\".\n③ 주연(vai chính) là vai diễn/người, bản thân bộ phim không thể \"trở thành vai chính\"."}, {"num": 2, "correct": "B", "stem": "회사에 가려고 집에서 나왔는데 ( ) 버스가 와서 기다리지 않고 탔다. ( )", "options": [{"label": "A", "text": "거의"}, {"label": "B", "text": "마침"}, {"label": "C", "text": "아마"}, {"label": "D", "text": "역시"}], "correct_source": "docx", "explanation": "\"마침 버스가 오다\" = đúng lúc/vừa lúc xe buýt đến, diễn tả sự trùng hợp về thời điểm — vừa ra khỏi nhà thì xe đến ngay.\n① 거의(hầu như) thường đi với động từ phủ định hoặc số lượng, không hợp.\n③ 아마(có lẽ) diễn tả phỏng đoán, không hợp vì câu đang kể một việc đã chắc chắn xảy ra.\n④ 역시(quả nhiên/cũng vậy) không hợp ngữ cảnh."}, {"num": 3, "correct": "D", "stem": "평일에 놀이동산에 가면 주말보다는 ( ), ( )", "options": [{"label": "A", "text": "쌀쌀하다"}, {"label": "B", "text": "친절하다"}, {"label": "C", "text": "유명하다"}, {"label": "D", "text": "한산하다"}], "correct_source": "docx", "explanation": "\"평일에 가면 주말보다는 한산하다\" = đi vào ngày thường thì vắng vẻ hơn cuối tuần — đúng logic thông thường về công viên giải trí.\n① 쌀쌀하다(se lạnh) nói về thời tiết, không liên quan.\n② 친절하다(thân thiện) không liên quan đến mức độ đông/vắng.\n③ 유명하다(nổi tiếng) không liên quan đến việc ngày thường hay cuối tuần."}, {"num": 4, "correct": "B", "stem": "인근 병원으로 이송돼 치료를 받던 사람이 결국 ( ) 것으로 알려졌다. ( )", "options": [{"label": "A", "text": "발생한"}, {"label": "B", "text": "사망한"}, {"label": "C", "text": "입원한"}, {"label": "D", "text": "체포한"}], "correct_source": "docx", "explanation": "\"결국\" (cuối cùng, rốt cuộc) thường báo hiệu một kết quả xấu/không mong muốn sau một quá trình — ở đây là người được đưa đi cấp cứu nhưng cuối cùng đã \"사망하다\" (qua đời).\n① 발생하다(xảy ra/phát sinh) không hợp vì chủ ngữ đã là người đang được điều trị, không phải sự việc mới phát sinh.\n③ 입원하다(nhập viện) là việc xảy ra trước khi điều trị, không phải kết quả cuối cùng hợp lý sau khi đã \"được đưa đi cấp cứu, điều trị\".\n④ 체포하다(bị bắt) không liên quan đến việc điều trị ở bệnh viện."}, {"num": 5, "correct": "D", "stem": "가: 여기 앉아서 기다리세요.\n나: 아니에요. 괜찮아요. 여기 ( ). ( )", "options": [{"label": "A", "text": "서 볼게요"}, {"label": "B", "text": "서 갈게요"}, {"label": "C", "text": "서 놀게요"}, {"label": "D", "text": "서 있을게요"}], "correct_source": "docx", "explanation": "\"-을게요\" diễn tả ý định/lời hứa của người nói. \"서 있다\" (đang đứng) + \"-을게요\" → \"서 있을게요\" = \"Tôi sẽ đứng ở đây (không cần ngồi)\", đúng ngữ cảnh từ chối lời mời ngồi.\n① 서 볼게요 = \"tôi sẽ thử đứng xem\", không hợp ngữ cảnh.\n② 서 갈게요 không phải cấu trúc tự nhiên trong tiếng Hàn.\n③ 서 놀게요 = \"đứng chơi\", vô nghĩa trong ngữ cảnh này."}, {"num": 6, "correct": "A", "stem": "가: 김 과장님은 어떤 사람이에요?\n나: 책임감이 강해서 ( ) 사람이에요. ( )", "options": [{"label": "A", "text": "믿을 만한"}, {"label": "B", "text": "믿기로 하는"}, {"label": "C", "text": "믿을 것 같은"}, {"label": "D", "text": "믿을 수 없는"}], "correct_source": "docx", "explanation": "\"-을 만하다\" = đáng để làm gì đó. \"믿을 만한 사람\" = người đáng tin cậy, khớp với lý do \"책임감이 강해서\" (vì có tinh thần trách nhiệm cao).\n② 믿기로 하는 không phải cấu trúc ngữ pháp chuẩn ở vị trí này.\n③ 믿을 것 같은(có vẻ sẽ tin) không diễn tả đúng nghĩa \"đáng tin cậy\".\n④ 믿을 수 없는(không thể tin được) ngược nghĩa hoàn toàn với ngữ cảnh."}, {"num": 7, "correct": "B", "stem": "가: 친구 어머님 장례식장에 잘 갔다 왔어요?\n나: 네. 제 친구는 너무 ( ) 말도 못 하고 계속 울기만 했어요. ( )", "options": [{"label": "A", "text": "슬픈 데다가"}, {"label": "B", "text": "슬픈 나머지"}, {"label": "C", "text": "슬픈 척하고"}, {"label": "D", "text": "슬픈 줄 알고"}], "correct_source": "docx", "explanation": "\"-는 나머지\" = vì quá... đến nỗi..., diễn tả kết quả cực đoan xuất phát từ mức độ cao của tính từ/động từ phía trước. \"슬픈 나머지 말도 못 하고 울기만 했다\" = vì quá đau buồn đến mức không nói được lời nào, chỉ khóc.\n① 슬픈 데다가(không chỉ buồn mà còn...) cần có một vế bổ sung khác đi kèm, không hợp câu này.\n③ 슬픈 척하고(giả vờ buồn) sai hoàn toàn về nghĩa — bạn ấy buồn thật.\n④ 슬픈 줄 알고(tưởng là buồn/cứ nghĩ là buồn) không hợp ngữ cảnh."}, {"num": 8, "correct": "C", "stem": "가: 오랜만이에요. 어떻게 지냈어요?\n나: 회사 면접시험을 준비하느라고 친구 ( ) 못 만날 정도로 바빴어요. ( )", "options": [{"label": "A", "text": "만큼"}, {"label": "B", "text": "든지"}, {"label": "C", "text": "커녕"}, {"label": "D", "text": "에게"}], "correct_source": "docx", "explanation": "\"커녕\" nhấn mạnh phủ định mạnh: dùng khi điều nhỏ hơn/dễ hơn còn không làm được, huống chi việc lớn hơn. \"친구 커녕 못 만날 정도로 바빴다\" = bận đến mức đừng nói chuyện gì khác, ngay cả gặp bạn cũng không được.\n① 만큼(bằng, như là) không tạo được nghĩa nhấn mạnh phủ định này.\n② 든지(dù là...) không hợp nghĩa câu.\n④ 에게(cho, đến — trợ từ chỉ đối tượng) không phù hợp cấu trúc nhấn mạnh phủ định."}, {"num": 9, "correct": "B", "stem": "누구나 몸이 아프면 고향 생각이 ( ).", "options": [{"label": "A", "text": "많이 날 수 없다"}, {"label": "B", "text": "많이 나는 법이다"}, {"label": "C", "text": "많이 날 줄 몰랐다"}, {"label": "D", "text": "많이 나려면 참이다"}], "correct_source": "docx", "explanation": "① 많이 날 수 없다(không thể nhớ nhiều) ngược nghĩa.\n④ 많이 나려면 참이다 không phải cấu trúc ngữ pháp đúng trong tiếng Hàn."}, {"num": 10, "correct": "D", "stem": "담배를 끊으려고 했지만 결국 다시 담배를 ( ).", "options": [{"label": "A", "text": "피워 간다"}, {"label": "B", "text": "피운 척했다"}, {"label": "C", "text": "피우면 좋겠다"}, {"label": "D", "text": "피우고 말았다"}], "correct_source": "docx", "explanation": "\"-고 말다\" = cuối cùng lại... (một kết quả ngoài ý muốn dù đã cố gắng tránh). \"끊으려고 했지만 결국 다시 피우고 말았다\" = định bỏ thuốc nhưng cuối cùng lại hút lại — khớp hoàn hảo với mở đầu \"-으려고 했지만 결국\" (định làm... nhưng cuối cùng).\n① 피워 간다(tiếp tục hút dần) không hợp với từ \"결국\" chỉ kết quả bất đắc dĩ.\n② 피운 척했다(giả vờ đã hút) sai nghĩa.\n③ 피우면 좋겠다(mong là được hút) không hợp vì câu đang kể một việc đã xảy ra, không phải ước muốn."}, {"num": 11, "correct": "B", "stem": "요리를 하다 / 조금 다치다", "options": [{"label": "A", "text": "요리를 해서 조금 다쳐요."}, {"label": "B", "text": "요리를 하다가 조금 다쳤어요."}, {"label": "C", "text": "요리를 하는데 조금 다칠 거에요."}, {"label": "D", "text": "요리를 하도록 조금 다지게 됐어요."}], "correct_source": "docx", "explanation": "\"-다가\" diễn tả một hành động đang diễn ra thì bị gián đoạn hoặc có sự việc khác xen vào. \"요리를 하다가 조금 다쳤어요\" = đang nấu ăn thì bị thương nhẹ — đúng ngữ pháp và hợp lý về nghĩa.\n① \"-아서\" (요리를 해서) diễn tả nguyên nhân trực tiếp và cần khớp thì hiện tại/tương lai, không hợp câu chuyện đã xảy ra kiểu \"đang làm thì...\".\n③ \"-는데... -ㄹ 거예요\" (thì tương lai \"sẽ bị thương\") không hợp vì đây là việc đã xảy ra rồi.\n④ \"-도록\" không tạo được nghĩa hợp lý ở vị trí này."}, {"num": 12, "correct": "B", "stem": "내일 비가 오다/눈이 오다/등산을 꼭 하다", "options": [{"label": "A", "text": "내일 비가 오고 눈이 와도 등산을 꼭 할 뻔했다."}, {"label": "B", "text": "내일 비가 오든지 눈이 와도 등산을 꼭 하기로 했다."}, {"label": "C", "text": "내일 비가 올 겸 눈이 올 겸 등산을 꼭 하기로 했다."}, {"label": "D", "text": "내일 비가 오면서 눈이 오는 한 등산을 꼭 할 것이다."}], "correct_source": "verified", "explanation": "Ý câu cần diễn đạt là \"dù mai mưa hay tuyết thì cũng quyết tâm đi leo núi\" — mẫu ngữ pháp chuẩn cho ý này là \"-든지 -든지\" (dù... hay...). Đáp án B gần với mẫu này nhất (dù cách viết \"오든지... 와도\" chưa hoàn toàn chuẩn \"-든지 -든지\"), và là đáp án duy nhất giữ đúng nghĩa \"quyết tâm/đã quyết định làm\" (-기로 했다).\n① \"-고 -아도 ~ㄹ 뻔했다\" nghĩa là \"suýt nữa thì...\", sai hoàn toàn ý nghĩa cần diễn đạt.\n③ \"-을 겸 -을 겸\" nghĩa là \"vừa để... vừa để...\" (mục đích kép), không hợp nghĩa \"dù mưa hay tuyết\".\n④ \"-면서 -는 한\" (vừa... vừa..., trong chừng mực/miễn là) không hợp nghĩa câu."}, {"num": 13, "correct": "D", "stem": "다음 ( )에 알맞은 것을 고르시오.\n저는 그림을 잘 그리지는 못해도 보는 것을 좋아해서 그림 전시회에 자주 갑니다. 전시회에 갈 때 '문화가 있는 날'을 이용하면 좋습니다. 이날은 평소보다 ( ) 저는 그림을 잘 그리지는 못해도 보는 것을 좋아해서 그림 전시회를 자주 갑니다. 이것을 이용해서 50% 할인을 받아 전시회를 관람했습니다. 다음 달에는 친구들과 재즈 콘서트에 가 보기로 문화생활을 즐길 수 있습니다. 지난달에는 '문화가 있는 날'을 이용해서 50% 할인을 받아 전시회를 관람했습니다. 다음 달에는 친구들과 재즈 콘서트에 가 보기로 했습니다. 이렇게 문화생활을 하면 돈도 절약할 수 있고 좋은 경험도 할 수 있어서 참 좋습니다.", "options": [{"label": "A", "text": "가족들과 함께"}, {"label": "B", "text": "한국인들과 함께"}, {"label": "C", "text": "돈을 더 많이 내고"}, {"label": "D", "text": "싼 가격이나 무료로"}], "correct_source": "docx", "explanation": "Đoạn văn nói về việc dùng \"문화가 있는 날\" (Ngày có Văn hóa) để đi xem triển lãm và được giảm giá 50% (\"50% 할인을 받아\"). Vậy chỗ trống cần điền ý \"giá rẻ hơn hoặc miễn phí\" so với ngày thường.\n① 가족들과 함께(cùng gia đình) không liên quan đến giá cả.\n② 한국인들과 함께(cùng người Hàn Quốc) không liên quan.\n③ 돈을 더 많이 내고(trả nhiều tiền hơn) ngược hoàn toàn với nội dung được giảm giá."}, {"num": 14, "correct": "C", "stem": "다음 부동산 매물 정보의 내용으로 옳지 않은 것은?\n매물정보 | 서울시 문래동 행복빌라\n주소 | 3층/4층\n층/건물 총 층수\n상세설명 | -근처에 버스 정류장, 지하철역, 고속도로가 있음 / -전망이 좋고 햇빛이 잘 들어옴 / -냉장고, 세탁기, 냉방 시설 있음\n문의 | 친절 공인중개사(010.123.4567)\n원룸 - 보증금 1,000/월세 40", "options": [{"label": "A", "text": "이 집에 살면 대중교통을 이용하기 편리하다."}, {"label": "B", "text": "이 집은 내부가 밝고 창문 밖의 경치가 좋다."}, {"label": "C", "text": "이 집으로 이사 올 사람은 에어컨을 사야 한다."}, {"label": "D", "text": "이 빌라는 4층 건물인데 매물로 나온 원룸은 3층에 있다."}], "correct_source": "corrected", "explanation": "Bảng rao vặt ghi rõ trong phần mô tả chi tiết: \"냉장고, 세탁기, 냉방 시설 있음\" — nghĩa là nhà đã có sẵn tủ lạnh, máy giặt VÀ thiết bị làm mát (máy lạnh). Vì vậy câu C \"이 집으로 이사 올 사람은 에어컨을 사야 한다\" (người chuyển đến phải mua máy lạnh) mâu thuẫn trực tiếp với thông tin đã có máy lạnh sẵn → đây là câu SAI, và câu hỏi đang tìm câu \"không đúng\", nên đáp án đúng là C.\nA, B khớp với mô tả (gần bến xe buýt/ga tàu điện ngầm/đường cao tốc; view đẹp, nhiều ánh sáng)."}, {"num": 15, "correct": "A", "stem": "집을 구할 때는 집안과 집 주변 환경을 꼼꼼하게 확인해야 한다. 집 안으로 해가 잘 들어오는지, 물이나 전기, 난방 시설은 잘되어 있는지, 고장 난 곳은 없는지 잘 살펴봐야 한다. 또한 집 주변에 버스 정류장이나 지하철역 등이 있어서 교통이 편리한지, 마트나 은행, 병원 등의 편의 시설이 있는지도 확인해 봐야 한다.\n집이 마음에 든다면 집주인과 직접 계약을 해야 한다. 부동산 중개업자가 대신 계약을 하면 사고가 날 수도 있기 때문이다. 그리고 계약서를 꼼꼼하게 확인하고 집 주인의 이름으로 된 계좌로 입금을 해야 한다. 집수리 등 특약 사항이 있다면 계약서에 자세하게 쓴다. 말로만 약속을 하면 집 주인이 약속을 안 지키는 경우도 있다. 특히 (ㄱ). 왜냐하면 집을 계약하는 사람이 집주인인 척하면서 사기를 칠 수도 있기 때문이다. 그러므로 계약하는 사람이 집주인인지 꼭 확인해야 안전하다.\n윗글의 제목으로 가장 알맞은 것을 고르시오. ( )", "options": [{"label": "A", "text": "집을 구할 때 주의 사항"}, {"label": "B", "text": "집 주변 환경이 중요한 이유"}, {"label": "C", "text": "부동산 중개업자가 해야 할 일"}, {"label": "D", "text": "계약서를 쓸 때 조심해야 할 것들"}], "correct_source": "verified", "explanation": "Bài đọc đề cập nhiều điểm cần chú ý khi tìm nhà: kiểm tra tình trạng nhà, kiểm tra môi trường xung quanh, ký hợp đồng trực tiếp với chủ nhà, kiểm tra kỹ hợp đồng, xác minh đúng là chủ nhà trước khi giao dịch. Đây đều là các \"lưu ý khi tìm nhà\" nói chung → tiêu đề bao quát nhất là A \"집을 구할 때 주의 사항\" (Những điều cần lưu ý khi tìm nhà).\nB, C, D chỉ là một phần nhỏ trong nội dung bài (môi trường xung quanh / việc của môi giới / hợp đồng), không bao quát được toàn bộ bài."}, {"num": 16, "correct": "D", "stem": "집을 구할 때는 집안과 집 주변 환경을 꼼꼼하게 확인해야 한다. 집 안으로 해가 잘 들어오는지, 물이나 전기, 난방 시설은 잘되어 있는지, 고장 난 곳은 없는지 잘 살펴봐야 한다. 또한 집 주변에 버스 정류장이나 지하철역 등이 있어서 교통이 편리한지, 마트나 은행, 병원 등의 편의 시설이 있는지도 확인해 봐야 한다.\n집이 마음에 든다면 집주인과 직접 계약을 해야 한다. 부동산 중개업자가 대신 계약을 하면 사고가 날 수도 있기 때문이다. 그리고 계약서를 꼼꼼하게 확인하고 집 주인의 이름으로 된 계좌로 입금을 해야 한다. 집수리 등 특약 사항이 있다면 계약서에 자세하게 쓴다. 말로만 약속을 하면 집 주인이 약속을 안 지키는 경우도 있다. 특히 (ㄱ). 왜냐하면 집을 계약하는 사람이 집주인인 척하면서 사기를 칠 수도 있기 때문이다. 그러므로 계약하는 사람이 집주인인지 꼭 확인해야 안전하다.\n윗글의 (ㄱ)에 들어갈 내용으로 알맞은 것을 고르시오. ( )", "options": [{"label": "A", "text": "보증금을 바로 입금해야 한다."}, {"label": "B", "text": "이상집젠터도 잘 선대해야 한다."}, {"label": "C", "text": "부동산 중개업자와 계약해야 한다."}, {"label": "D", "text": "등기부 등본을 반드시 확인해야 한다."}], "correct_source": "docx", "explanation": "A, C nói về việc chuyển tiền đặt cọc và làm việc qua môi giới — không liên quan trực tiếp đến việc xác minh \"đúng là chủ nhà hay không\"."}, {"num": 17, "correct": "D", "stem": "다음 중 국경일과 국가기념일의 이름과 의미를 알맞게 연결한 것은?", "options": [{"label": "A", "text": "삼일절: 세종대왕이 한글을 만든 것을 기념하는 날"}, {"label": "B", "text": "한글날: 대한민국 최초로 헌법이 제정된 것을 기념하는 날"}, {"label": "C", "text": "제헌절: 일본의 지배에 저항하여 일어난 독립운동을 기념하는 날"}, {"label": "D", "text": "광복절: 1945년 일본의 지배에서 벗어나 독립을 맞이한 것을 기념하는 날"}], "correct_source": "verified", "explanation": "광복절 (Ngày Quang phục) kỷ niệm việc Hàn Quốc thoát khỏi ách đô hộ Nhật Bản và giành lại độc lập năm 1945 — khớp chính xác với nội dung D.\nA sai: 삼일절 (mùng 1 tháng 3) kỷ niệm phong trào độc lập 1919, không phải việc vua Sejong tạo ra chữ Hangeul.\nB sai: 한글날 (Ngày Hangeul) kỷ niệm việc ban hành chữ Hangeul, không phải hiến pháp.\nC sai: 제헌절 (Ngày Lập hiến) kỷ niệm việc ban hành Hiến pháp đầu tiên, không phải phong trào độc lập."}, {"num": 18, "correct": "D", "stem": "한국에서의 안전한 생활에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "안전신문고를 통해서 미리 사고를 예방할 수 있다."}, {"label": "B", "text": "행정안전부를 중심으로 다양한 재난에 대비하고 있다."}, {"label": "C", "text": "긴급신고전화를 통해 사고 위치와 사고 상황을 신고할 수 있다."}, {"label": "D", "text": "지방자치단체에서 매달 1회 이상 재난 대비 훈련을 해야 한다."}], "correct_source": "docx", "explanation": "Luật quy định chính quyền địa phương (지방자치단체) không bắt buộc phải tổ chức diễn tập phòng chống thiên tai mỗi tháng 1 lần — mức độ/tần suất thực tế không nghiêm ngặt như D mô tả, nên D là câu SAI.\nA, B, C đều là các mô tả đúng về hệ thống an toàn của Hàn Quốc: 안전신문고 dùng để báo cáo/phòng ngừa sự cố, 행정안전부 (Bộ Hành chính và An toàn) chủ trì công tác phòng chống thiên tai, và có đường dây nóng khẩn cấp để báo vị trí/tình huống tai nạn."}, {"num": 19, "correct": "D", "stem": "공공부조 혜택을 받을 수 있는 사람을 <보기>에서 모두 고른 것은?\n- 보기 -ㄱ. 저소득층 외국인 부부\nㄴ. 학업에 어려움이 있는 한국 학생\nㄷ. 법에 따라 난민으로 인정받은 사람\nㄹ. 초등학생 한국인 자녀를 양육하고 있는 외국인", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄴ, ㄷ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "explanation": "공공부조 (trợ cấp công) dành cho người có hoàn cảnh khó khăn về kinh tế, không phân biệt quốc tịch nếu đáp ứng điều kiện pháp luật — người tị nạn được công nhận theo pháp luật (ㄷ) và người nước ngoài đang nuôi con nhỏ là công dân Hàn Quốc (ㄹ) đều có thể được xét trợ cấp.\nㄱ (cặp vợ chồng nước ngoài thu nhập thấp) không tự động đủ điều kiện chỉ vì thu nhập thấp và là người nước ngoài nếu chưa đáp ứng các điều kiện cư trú/pháp lý cụ thể; ㄴ (học sinh Hàn Quốc gặp khó khăn học tập) là vấn đề học tập, không phải đối tượng của công공부조 (trợ cấp phúc lợi kinh tế)."}, {"num": 20, "correct": "C", "stem": "한국의 거주 형태에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "자가는 자기가 소유한 집에서 생활하는 것이다."}, {"label": "B", "text": "자가와 전세를 혼합한 반전세라는 방식도 늘고 있다."}, {"label": "C", "text": "전세는 보증금을 집주인에게 맡기고 매달 내는 돈이 있다."}, {"label": "D", "text": "월세는 매달 돈을 내고 방이나 집을 빌려 생활하는 방식이다."}], "correct_source": "verified", "explanation": "전세 (jeonse) đúng nghĩa là đặt cọc một khoản tiền lớn cho chủ nhà và KHÔNG phải trả thêm tiền hàng tháng — nếu có thêm khoản trả hàng tháng thì đó là 반전세 hoặc 월세, không còn là 전세 thuần túy. Vì vậy C mô tả sai bản chất của 전세, đây là đáp án đúng cho câu hỏi \"điều KHÔNG đúng\".\nA, B, D đều là mô tả chính xác về 자가 (nhà tự sở hữu), 반전세 (hình thức lai giữa tự sở hữu và jeonse), và 월세 (thuê trả tiền hàng tháng)."}, {"num": 21, "correct": "D", "stem": "어린이집과 유치원의 공통점을 <보기>에서 모두 고른 것은?\n<보기>ㄱ. 만 3세부터 교육을 받을 수 있다.\nㄴ. 국·공립 교육기관의 보호료가 더 비싸다.\nㄷ. 초등학교 취학 전의 어린이를 위한 기관이다.\nㄹ. 어린이집과 유치원 모두 정부의 보육료 지원을 받을 수 있다.", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄱ, ㄷ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "explanation": "어린이집 và 유치원 đều là cơ sở giáo dục/chăm sóc dành cho trẻ trước tuổi vào tiểu học (ㄷ đúng), và cả hai loại hình đều có thể nhận được hỗ trợ chi phí nuôi dạy từ chính phủ (ㄹ đúng) — nên đáp án đúng là D (ㄷ, ㄹ).\nㄱ sai: 어린이집 có thể nhận trẻ từ 0 tuổi (không phải chỉ từ 3 tuổi trở lên như 유치원).\nㄴ sai: đây không phải là điểm chung, và không phải lúc nào cơ sở công lập cũng có phí bảo hộ cao hơn."}, {"num": 22, "correct": "B", "stem": "한국의 대학 진학률이 높은 이유를 <보기>에서 모두 고른 것은?\n- 보기 -ㄱ. 대학을 졸업하면 취업에 유리하다.\nㄴ. 입시 스트레스가 높고 사교육비가 많이 든다.\nㄷ. 고등학교와 대학교까지 무상 교육이 이루어진다. 부부\nㄹ. 사회적 지위를 상승시킬 수 있는 중요한 방법이다.", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄱ, ㄹ"}, {"label": "C", "text": "ㄴ, ㄷ"}, {"label": "D", "text": "ㄴ, ㄹ"}], "correct_source": "docx", "explanation": "Tỷ lệ vào đại học ở Hàn Quốc cao chủ yếu vì tốt nghiệp đại học giúp dễ xin việc hơn (ㄱ) và vì đại học được xem là con đường quan trọng để nâng cao địa vị xã hội (ㄹ) — đáp án đúng là B (ㄱ, ㄹ).\nㄴ (áp lực thi cử cao, chi phí giáo dục tư nhiều) là HỆ QUẢ/mặt trái của việc học đại học phổ biến, không phải LÝ DO khiến tỷ lệ vào đại học cao.\nㄷ sai vì giáo dục miễn phí ở Hàn Quốc chỉ áp dụng đến hết cấp 3 (trung học phổ thông), đại học vẫn phải đóng học phí."}, {"num": 23, "correct": "B", "stem": "<보기>의 (가), (나)에 해당하는 용어로 옳은 것은?\n<보기>\n한옥에는 (가)와/과 (나)이 있는데 (가)은/는 방과 방 사이에 나무로 긴 넷벤치를 깔아서 만든 공간으로 바람이 잘 통해서 여름을 시원하게 보낼 수 있었다. 반면에 (나)은 겨울에 추위를 피하기 위해 아궁이에 불을 때어 방을 따뜻하게 해 주는 난방 장치이다.", "options": [{"label": "A", "text": "(가) 초가집, (나) 온돌"}, {"label": "B", "text": "(가) 대청마루, (나) 온돌"}, {"label": "C", "text": "(가) 초가집, (나) 기와집"}, {"label": "D", "text": "(가) 대청마루, (나) 기와집"}], "correct_source": "docx", "explanation": "대청마루 là khoảng sàn gỗ thoáng khí giữa các phòng trong nhà truyền thống Hàn Quốc (한옥), giúp mát vào mùa hè; 온돌 là hệ thống sưởi bằng cách đốt lửa ở 아궁이 để làm ấm sàn nhà vào mùa đông — khớp chính xác với mô tả trong bài, nên đáp án đúng là B.\nA, C, D dùng sai thuật ngữ 초가집 (nhà mái tranh, chỉ kiểu mái không phải một không gian trong nhà) hoặc 기와집 (nhà mái ngói, cũng chỉ kiểu mái) thay vì tên đúng của không gian/thiết bị được mô tả."}, {"num": 24, "correct": "D", "stem": "<보기>의 내용에 공통적으로 해당하는 설명은?\n- 보기 -\n· 평균 기대 수명의 증가 　· 주 52시간 근무제 시행 　· 1인당 국민소득 3만 달러 시대 도래", "options": [{"label": "A", "text": "의료 기술이 향상되었다."}, {"label": "B", "text": "경제적 약자를 보호하고 있다."}, {"label": "C", "text": "누구나 원하면 교육을 받을 수 있다."}, {"label": "D", "text": "여가의 중요성이 점점 높아지고 있다."}], "correct_source": "docx", "explanation": "Tuổi thọ trung bình tăng, chế độ làm việc 52 giờ/tuần, và thu nhập bình quân đầu người đạt 30.000 USD đều là những yếu tố khiến người dân có nhiều thời gian và điều kiện hơn để tận hưởng thời gian rảnh (여가) — nên đáp án đúng là D \"여가의 중요성이 점점 높아지고 있다\"."}, {"num": 25, "correct": "C", "stem": "대한민국 국회의 구성에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "지역구 국회의원은 각 지역구의 대표를 뽑는 것이다."}, {"label": "B", "text": "2023년을 기준으로 300명의 국회의원이 활동하고 있다."}, {"label": "C", "text": "국회는 상원과 하원으로 구분되는 양원제 방식을 취한다."}, {"label": "D", "text": "비례대표 국회의원은 정당별 득표율에 따라 당선자가 정해진다."}], "correct_source": "docx", "explanation": "Quốc hội Hàn Quốc theo chế độ MỘT viện (단원제), không phải chế độ lưỡng viện thượng viện/hạ viện (양원제) như Mỹ hay Anh — nên C là mô tả SAI, đây là đáp án đúng cho câu hỏi tìm điều \"không đúng\".\nA, B, D đều là mô tả đúng: nghị sĩ khu vực đại diện cho từng địa phương, tổng số khoảng 300 nghị sĩ, và nghị sĩ theo tỷ lệ đại diện (비례대표) được xác định theo tỷ lệ phiếu bầu của từng đảng."}, {"num": 26, "correct": "C", "stem": "지방자치제에 대한 설명으로 옳은 것을 <보기>에서 모두 고른 것은?\n< 보기 >ㄱ. 지방자치단체는 지역에 맞는 정책을 결정한다.\nㄴ. 지방자치단체는 광역자치단체와 기초자치단체로 나뉜다.\nㄷ. 4년마다 지방 선거를 치러 각 지역의 대표를 선출한다.\nㄹ. 지방의회는 지방자치단체가 결정을 내린 정책을 집행한다.", "options": [{"label": "A", "text": "ㄱ, ㄷ"}, {"label": "B", "text": "ㄱ, ㄹ"}, {"label": "C", "text": "ㄴ, ㄷ"}, {"label": "D", "text": "ㄴ, ㄹ"}], "correct_source": "docx", "explanation": "ㄴ đúng: chính quyền địa phương chia làm 2 cấp — 광역자치단체 (cấp rộng: tỉnh/thành phố trực thuộc trung ương) và 기초자치단체 (cấp cơ sở: quận/huyện/thành phố nhỏ).\nㄷ đúng: cứ 4 năm một lần tổ chức bầu cử địa phương để chọn đại diện các cấp.\nㄱ sai: việc QUYẾT ĐỊNH chính sách địa phương là vai trò của 지방의회 (Hội đồng địa phương — cơ quan lập pháp), không phải của 지방자치단체(장) (cơ quan hành chính, chịu trách nhiệm THỰC THI).\nㄹ sai vì đảo ngược vai trò tương tự ㄱ nhưng theo chiều ngược lại: 지방의회 mới là bên QUYẾT ĐỊNH chính sách, còn 지방자치단체 mới là bên THỰC THI — không phải như ㄹ mô tả."}, {"num": 27, "correct": "D", "stem": "<보기>의 (가), (나)에 들어갈 용어로 적절한 것은?\n<보기>\n외국인이 취업할 때는 그 업체가 하는 일은 무엇인지, 정식으로 등록되어 있는지 확인해야 한다. 또한 취업을 하게 되면 (가)를 반드시 작성하고, 취업 이후에도 근로자의 기본적인 권리가 잘 지켜지는지 확인할 필요가 있다. 그리고 일자리와 관련된 문제가 생겼을 때는 (나)나 한국산업인력공단 등에 문의하여 도움을 받아야 한다.", "options": [{"label": "A", "text": "(가) 이력서, (나) 법무부"}, {"label": "B", "text": "(가) 이력서, (나) 고용노동부"}, {"label": "C", "text": "(가) 근로계약서, (나) 법무부"}, {"label": "D", "text": "(가) 근로계약서, (나) 고용노동부"}], "correct_source": "docx", "explanation": "Khi đi làm, người lao động nước ngoài bắt buộc phải ký \"근로계약서\" (hợp đồng lao động, không phải chỉ sơ yếu lý lịch 이력서), và khi có vấn đề về việc làm có thể liên hệ \"고용노동부\" (Bộ Việc làm và Lao động) hoặc 한국산업인력공단 để được hỗ trợ — khớp chính xác với đáp án D.\n이력서 (sơ yếu lý lịch) chỉ dùng khi ỨNG TUYỂN, không phải giấy tờ bắt buộc SAU KHI đã được nhận việc. 법무부 (Bộ Tư pháp) phụ trách vấn đề visa/cư trú, không phải nơi hỗ trợ tranh chấp lao động."}, {"num": 28, "correct": "B", "stem": "한국의 수출에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "1950~1960년대에는 자동차를 수출하기 시작했다."}, {"label": "B", "text": "1970년대에는 옷, 신발, 가방, 가발 등을 수출했다."}, {"label": "C", "text": "1980년대부터는 문화 콘텐츠, 의료 서비스도 수출했다."}, {"label": "D", "text": "1990~2010년대에는 농산물과 원료를 주로 수출했다."}], "correct_source": "corrected", "explanation": "Thập niên 1970 là giai đoạn Hàn Quốc phát triển mạnh công nghiệp nhẹ (경공업) và xuất khẩu quần áo, giày dép, túi xách, tóc giả — khớp chính xác với đáp án B.\nA sai: thập niên 1950~1960 Hàn Quốc chưa bắt đầu xuất khẩu ô tô với quy mô lớn; mặt hàng xuất khẩu chủ yếu là nguyên liệu thô và nông sản.\nC sai: xuất khẩu nội dung văn hóa và dịch vụ y tế chỉ nổi bật từ khoảng những năm 2000 trở đi, không phải từ thập niên 1980.\nD sai: giai đoạn 1990~2010, các mặt hàng xuất khẩu chủ lực là sản phẩm công nghiệp và công nghệ cao như bán dẫn, ô tô, tàu biển và điện thoại, không phải nông sản và nguyên liệu."}, {"num": 29, "correct": "D", "stem": "<보기>의 ( )안에 가장 알맞은 것은?\n<보기>\n시람들의 권리를 보호하고 사회질서를 유지하기 위해 좋은 법을 만드는 것도 중요하지만 ( )도 필요하다. 왜냐하면 아무리 좋은 법이 있어도 사람들이 법을 지키지 않으면 소용이 없기 때문이다.", "options": [{"label": "A", "text": "헌법"}, {"label": "B", "text": "정의"}, {"label": "C", "text": "국제법"}, {"label": "D", "text": "준법정신"}], "correct_source": "docx", "explanation": "Đoạn văn nói rằng có luật tốt thôi chưa đủ, người dân cần tự giác tuân thủ pháp luật thì luật mới thực sự có tác dụng — đây chính là khái niệm \"준법정신\" (tinh thần tuân thủ pháp luật), khớp với D.\nA 헌법(hiến pháp), B 정의(công lý/chính nghĩa) và C 국제법(luật quốc tế) đều là các khái niệm liên quan đến luật pháp nhưng không diễn tả đúng ý \"người dân tự giác tuân thủ\" mà đoạn văn nhấn mạnh."}, {"num": 30, "correct": "C", "stem": "<보기>의 (가), (나)에 대한 설명으로 옳은 것은?\n(가) 국가인권위원회 | (나) 국민권익위원회", "options": [{"label": "A", "text": "(가)는 부패 방지와 국민의 권익 보호, 권리 구제를 한다."}, {"label": "B", "text": "(나)는 모든 사람의 기본적인 인권을 보호하기 위한 기관이다."}, {"label": "C", "text": "(가)에 인권침해를 당한 사람들이 조사, 구제 등을 요청할 수 있다."}, {"label": "D", "text": "(나)는 이민자나 외국인의 한국 적응을 돕고, 상담과 소송 진행을 도와준다."}], "correct_source": "verified", "explanation": "(가) là 국가인권위원회 (Ủy ban Nhân quyền Quốc gia) — cơ quan độc lập chuyên tiếp nhận đơn khiếu nại và điều tra, cứu trợ cho những người bị xâm phạm nhân quyền, khớp với C.\n(나) là 국민권익위원회 (Ủy ban Quyền lợi và Chống tham nhũng Quốc dân) — chuyên về phòng chống tham nhũng và bảo vệ quyền lợi công dân trong quan hệ với cơ quan hành chính, KHÔNG phải là cơ quan nhân quyền chung cho mọi người (nên A, B mô tả sai vai trò của (가)/(나)); D cũng không đúng vì hỗ trợ pháp lý cho người nước ngoài không phải chức năng chính của 국민권익위원회."}, {"num": 31, "correct": "B", "stem": "<보기>의 내용을 읽고 설명할 수 있는 것으로 가장 적절한 것은?\n<보기>\n· 친구 사이의 믿음 　· 어른과 아이 사이의 순서 　· 부모와 자녀 사이의 친밀한 관계", "options": [{"label": "A", "text": "옛날 사람들은 신분에 따라 하는 일이 달랐다."}, {"label": "B", "text": "조선의 유교가 오늘날까지 한국에 영향을 주고 있다."}, {"label": "C", "text": "조선 시대에 양반 중심의 문화에서 서민 문화로 변화했다."}, {"label": "D", "text": "한글 소설, 판소리, 탈놀이, 민화 등이 지금까지 남아 있다."}], "correct_source": "verified", "explanation": "Ba giá trị nêu trong <보기> — sự tin tưởng giữa bạn bè (붕우유신), thứ tự trên dưới giữa người lớn và trẻ nhỏ (장유유서), quan hệ gắn bó giữa cha mẹ và con cái (부자유친) — chính là 3 trong 5 giá trị đạo đức của Nho giáo (오륜) thời Joseon, vẫn còn ảnh hưởng đến văn hóa/quan hệ xã hội Hàn Quốc ngày nay — khớp với B.\nA (phân công lao động theo giai cấp), C (chuyển từ văn hóa quý tộc sang văn hóa bình dân), D (văn học/nghệ thuật dân gian còn lưu truyền) đều là các nội dung khác về thời Joseon, không liên quan đến 3 giá trị đạo đức được liệt kê."}, {"num": 32, "correct": "B", "stem": "<보기>의 인물들과 가장 관계 깊은 것은?\n<보기>\n· 이황 　· 세종대왕 　· 이이 　· 신사임당", "options": [{"label": "A", "text": "전쟁을 승리로 이끈 인물들이다."}, {"label": "B", "text": "한국의 화폐에 등장하는 인물들이다."}, {"label": "C", "text": "제주도에 흉년이 들었을 때 쌀을 나누어 주었다."}, {"label": "D", "text": "시를 잘 지어서 중국과 일본에서 높은 평가를 받았다."}], "correct_source": "docx", "explanation": "이황, 세종대왕, 이이, 신사임당 đều là những nhân vật lịch sử xuất hiện trên các tờ tiền giấy Hàn Quốc hiện hành (세종대왕 trên tờ 10.000 won, 이황 trên tờ 1.000 won, 이이 trên tờ 5.000 won, 신사임당 trên tờ 50.000 won) — khớp chính xác với B.\nA, C, D là các mô tả về những nhân vật/sự kiện lịch sử khác, không áp dụng chung cho cả 4 người này."}, {"num": 33, "correct": "D", "stem": "한국의 독립운동에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "1919년 3·1 운동에서 많은 사람들이 독립을 요구했다."}, {"label": "B", "text": "김구 등이 중심이 되어 중국 상하이에 임시정부를 세웠다."}, {"label": "C", "text": "1920년부터는 중국 만주 지방을 중심으로 무장 투쟁을 했다."}, {"label": "D", "text": "유관순은 학생이었지만 중국에서 만세 운동을 벌여 성공했다."}], "correct_source": "docx", "explanation": "유관순 tham gia phong trào biểu tình đòi độc lập (만세운동) NGAY TẠI Hàn Quốc (cụ thể ở quê nhà Cheonan), không phải ở Trung Quốc, và cuối cùng bị bắt và qua đời trong tù chứ không phải \"thành công\" như D mô tả — nên D là câu SAI, đây là đáp án đúng cho câu hỏi tìm điều \"không đúng\".\nA, B, C đều là mô tả đúng: phong trào 3·1 năm 1919, chính phủ lâm thời tại Thượng Hải do 김구 và các nhà cách mạng khác lập nên, và đấu tranh vũ trang tại Mãn Châu (Trung Quốc) từ những năm 1920."}, {"num": 34, "correct": "B", "stem": "<보기>에 해당하는 지역은?\n<보기>· 자동차, 조선, 철강, 기계 등을 만드는 공업 단지가 많다.\n· 한국의 동남쪽에 위치하고 있으며 영남지역이라고도 한다.\n· 경주를 중심으로 신라의 불교 문화유산을 많이 찾아볼 수 있다.", "options": [{"label": "A", "text": "경기도"}, {"label": "B", "text": "경상도"}, {"label": "C", "text": "충청도"}, {"label": "D", "text": "전라도"}], "correct_source": "docx", "explanation": "Khu vực có nhiều khu công nghiệp sản xuất ô tô, đóng tàu, thép, máy móc; nằm ở phía đông nam Hàn Quốc (còn gọi là vùng 영남); có di sản Phật giáo thời Silla tập trung quanh Gyeongju — tất cả đặc điểm này khớp chính xác với 경상도, đáp án B.\n경기도, 충청도, 전라도 là các vùng khác của Hàn Quốc, không có đủ các đặc điểm nêu trên (đặc biệt là di sản Silla ở Gyeongju và vị trí đông nam)."}, {"num": 35, "correct": "D", "stem": "<보기>에 해당하는 지역에 대한 설명으로 옳지 않은 것은?\n<보기>\n· 새만금 간척 지구 　· 풍부한 식량 지원 　· 잘 보존된 전통문화", "options": [{"label": "A", "text": "양식장에서 다양한 해산물을 생산한다."}, {"label": "B", "text": "700여 채의 한옥이 있는 한옥마을이 있다."}, {"label": "C", "text": "2012년에 여수에서 세계 박람회가 개최됐다."}, {"label": "D", "text": "이 지역에 백제 문화제와 보령 머드 축제가 있다."}], "correct_source": "docx", "explanation": "Đặc điểm trong <보기> — khu đất khai hoang Saemangeum, nguồn lương thực dồi dào, văn hóa truyền thống được bảo tồn tốt — mô tả vùng 전라도. Lễ hội bùn Boryeong (보령 머드 축제) thực chất thuộc tỉnh 충청도 chứ không phải 전라도, nên D là thông tin SAI khi gán cho vùng này — đây là đáp án đúng cho câu hỏi tìm điều \"không đúng\".\nA (nuôi trồng hải sản), B (làng Hanok Jeonju với hơn 700 nhà cổ), C (Triển lãm Thế giới Yeosu 2012) đều là các đặc điểm đúng của vùng 전라도."}, {"num": 36, "correct": "C", "stem": "<보기>의 지역에 공통적으로 해당하는 것은?\n<보기>\n· 세종특별자치시 　· 대전광역시\n종류의 산업이 골고루 발달했다.", "options": [{"label": "A", "text": "여러 종류의 산업이 골고루 발달했다."}, {"label": "B", "text": "서쪽과 남쪽의 해안 지역에 넓은 갯벌이 있다."}, {"label": "C", "text": "수도권과 경상, 전라지역을 연결하는 교통의 중심지이다."}, {"label": "D", "text": "한국의 동남쪽에 위치하고 있으며 영남지역이라고도 한다."}], "correct_source": "corrected", "explanation": "대전 (Daejeon) và 세종 (Sejong) nằm ở vị trí trung tâm địa lý của Hàn Quốc — nơi các tuyến đường sắt cao tốc KTX (tuyến Gyeongbu và Honam) cùng các đường cao tốc lớn giao/rẽ nhánh, kết nối vùng thủ đô (수도권) với cả vùng Gyeongsang và Jeolla. Đây là đặc điểm nổi bật và được nhắc đến nhiều nhất về hai thành phố này, khớp với đáp án C.\nA (nhiều ngành công nghiệp phát triển đều) không phải đặc điểm nổi bật nhất — Daejeon thực ra nổi tiếng hơn về nghiên cứu khoa học công nghệ (Daedeok Innopolis, KAIST) chứ không phải đa dạng công nghiệp nói chung.\nB sai vì cả hai thành phố đều nằm sâu trong đất liền, không giáp biển nên không có bãi triều.\nD sai vì đó là đặc điểm của vùng Gyeongsang (영남지역, đông nam Hàn Quốc), không phải Daejeon/Sejong."}], "tables": [[["매물정보", "서울시 문래동 행복빌라"], ["주소", "3층/4층"], ["층/건물 총 층수", ""], ["상세설명", "-근처에 버스 정류장, 지하철역, 고속도로가 있음 / -전망이 좋고 햇빛이 잘 들어옴 / -냉장고, 세탁기, 냉방 시설 있음"], ["문의", "친절 공인중개사(010.123.4567)"]], [["(가) 국가인권위원회", "(나) 국민권익위원회"]]]}, "round4": {"title": "Mô phỏng KIIP cấp 5 - 5단계 4회", "source": "한국어_모의고사_(5단계_4회)_—_Giải_thích_chi_tiết.docx", "questions": [{"num": 1, "correct": "C", "stem": "머리가 아플 때는 ( )을/를 먹으면 돼요.", "options": [{"label": "A", "text": "감기약"}, {"label": "B", "text": "소화제"}, {"label": "C", "text": "두통약"}, {"label": "D", "text": "해열제"}], "correct_source": "docx", "options_source": "docx", "explanation": "\"머리가 아플 때\" (khi đau đầu) thì cần uống thuốc đau đầu — 두통약.\nA 감기약(thuốc cảm) dùng khi bị cảm cúm.\nB 소화제(thuốc tiêu hóa) dùng khi khó tiêu.\nD 해열제(thuốc hạ sốt) dùng khi sốt, không phải chỉ đau đầu đơn thuần."}, {"num": 2, "correct": "C", "stem": "저는 스트레스가 ( ) 조용한 음악을 들으면서 산책을 합니다. 그러면 머리가 맑아집니다.", "options": [{"label": "A", "text": "걸리면"}, {"label": "B", "text": "받으면"}, {"label": "C", "text": "쌓이면"}, {"label": "D", "text": "풀리면"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cụm từ cố định đi với \"스트레스가\" (trợ từ 가) là \"스트레스가 쌓이다\" (căng thẳng tích tụ) — khớp với C.\nA 걸리면(nếu mắc bệnh) không hợp nghĩa.\nB 받으면(nếu nhận) phải đi với trợ từ \"를\" (스트레스를 받다), không hợp với trợ từ \"가\" trong câu.\nD 풀리면(nếu được giải tỏa) sai logic — người này đang MÔ TẢ hành động để giải tỏa (nghe nhạc, đi dạo), nên trước đó phải là lúc căng thẳng TÍCH TỤ chứ chưa được giải tỏa."}, {"num": 3, "correct": "A", "stem": "우리 회사에서는 한국어와 중국어에 ( ) 직원을 구하고 있다.", "options": [{"label": "A", "text": "능통한"}, {"label": "B", "text": "대단한"}, {"label": "C", "text": "불편한"}, {"label": "D", "text": "지나친"}], "correct_source": "docx", "options_source": "docx", "explanation": "\"언어에 능통하다\" = thành thạo một ngôn ngữ nào đó — khớp với ngữ cảnh tuyển nhân viên giỏi tiếng Hàn/Trung.\nB 대단한(tuyệt vời), C 불편한(bất tiện), D 지나친(quá mức) đều không phải cụm từ đi kèm \"언어에\"."}, {"num": 4, "correct": "D", "stem": "휴대폰을 물에 빠뜨렸을 때 ( ) 전원을 켜면 안 됩니다.", "options": [{"label": "A", "text": "아마"}, {"label": "B", "text": "온통"}, {"label": "C", "text": "저절로"}, {"label": "D", "text": "절대로"}], "correct_source": "docx", "options_source": "docx", "explanation": "\"절대로 ... (으)면 안 되다\" là cấu trúc cố định mang nghĩa \"tuyệt đối không được làm gì\" — khớp với D.\nA 아마(có lẽ) diễn tả phỏng đoán, B 온통(toàn bộ) và C 저절로(tự động) không hợp nghĩa câu cảnh báo này."}, {"num": 5, "correct": "C", "stem": "가: 왜 이렇게 작은 가방을 샀어요?\n나: 인터넷에서 사진만 보고 큰 ( ).", "options": [{"label": "A", "text": "가방이 아니에요"}, {"label": "B", "text": "가방이면 좋겠어요"}, {"label": "C", "text": "가방인 줄 알았어요"}, {"label": "D", "text": "가방이기 때문이에요"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cấu trúc \"-(으)ㄴ 줄 알다\" thể hiện sự lầm tưởng về một việc gì đó — \"chỉ xem ảnh trên mạng nên đã tưởng là túi to\" — khớp với C.\nA, B, D đều không diễn tả đúng sắc thái \"lầm tưởng\" mà câu cần."}, {"num": 6, "correct": "B", "stem": "가: 이번 주말에 같이 등산을 할까요?\n나: 미안해요. 친구와 경복궁에 ( ).", "options": [{"label": "A", "text": "가라고 했어요"}, {"label": "B", "text": "가기로 했어요"}, {"label": "C", "text": "가는 편이에요"}, {"label": "D", "text": "가는 법이에요"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cấu trúc \"-기로 하다\" thể hiện một quyết định/kế hoạch/lời hẹn đã định trước — \"đã hẹn đi Gyeongbokgung với bạn\" — khớp với B.\nA 가라고 했어요(đã bảo đi đi — câu gián tiếp mệnh lệnh), C 가는 편이에요(thường hay đi), D 가는 법이에요(hiển nhiên là đi) đều không hợp ngữ cảnh từ chối lời rủ vì đã có hẹn khác."}, {"num": 7, "correct": "C", "stem": "가: 공항에 도착하면 바로 연락주세요.\n나: 네, ( ) 연락할게요.", "options": [{"label": "A", "text": "도착해야"}, {"label": "B", "text": "도착하면서"}, {"label": "C", "text": "도착하자마자"}, {"label": "D", "text": "도착하고 해서"}], "correct_source": "docx", "options_source": "docx", "explanation": "Người A dùng từ \"바로\" (ngay lập tức); người B đáp lại đồng tình bằng cấu trúc \"-자마자\" (ngay khi vừa...) — khớp với C.\nA 도착해야(phải đến thì mới...), B 도착하면서(vừa đến vừa...), D 도착하고 해서(vì đến và...) đều không diễn tả đúng ý \"ngay khi\"."}, {"num": 8, "correct": "D", "stem": "가: 취직 준비를 한다면서요? 월급은 얼마나 받고 싶어요?\n나: 당연히 많이 ( ) 좋지요.", "options": [{"label": "A", "text": "받도록"}, {"label": "B", "text": "받든지"}, {"label": "C", "text": "받으려면"}, {"label": "D", "text": "받을수록"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cấu trúc \"-(으)면 -(으)ㄹ수록\" (càng... càng...) được rút gọn thành \"-ㄹ수록\" — \"nhận càng nhiều lương càng tốt\" — khớp với D.\nA 받도록(để nhận được), B 받든지(nhận hay không), C 받으려면(nếu muốn nhận) đều không hợp cấu trúc \"càng...càng\" này."}, {"num": 9, "correct": "C", "stem": "밖이 시끄러워서 책을 ( ).", "options": [{"label": "A", "text": "읽을 정도이다"}, {"label": "B", "text": "읽으려고 한다"}, {"label": "C", "text": "읽을 수 없었다"}, {"label": "D", "text": "읽으려던 참이다"}], "correct_source": "docx", "options_source": "docx", "explanation": "Bên ngoài ồn ào (nguyên nhân) dẫn đến kết quả không thể đọc sách. \"-ㄹ 수 없다\" diễn tả sự không có khả năng — khớp với C.\nA 읽을 정도이다(đến mức đọc được), B 읽으려고 한다(định đọc), D 읽으려던 참이다(vừa định đọc) đều không hợp với nguyên nhân \"ồn ào\"."}, {"num": 10, "correct": "D", "stem": "버스가 끊겨서 택시를 ( ).", "options": [{"label": "A", "text": "탈 뻔했어요"}, {"label": "B", "text": "타 있었어요"}, {"label": "C", "text": "타지 마세요"}, {"label": "D", "text": "탈 수밖에 없었어요"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cấu trúc \"-(으)ㄹ 수밖에 없다\" diễn tả tình huống không còn lựa chọn nào khác — \"xe buýt hết chuyến nên chỉ còn cách bắt taxi\" — khớp với D.\nA 탈 뻔했어요(suýt đi — nghĩa là cuối cùng KHÔNG đi, sai logic), B 타 있었어요(sai ngữ pháp), C 타지 마세요(đừng đi — mệnh lệnh, sai ngữ cảnh)."}, {"num": 11, "correct": "B", "stem": "몸이 아프다 / 부모님 생각이 나다", "options": [{"label": "A", "text": "아파서 부모님 생각이 나는 척했다."}, {"label": "B", "text": "몸이 아프면 부모님 생각이 나기 마련이다."}, {"label": "C", "text": "아플수록 부모님 생각이 나면 좋겠다."}, {"label": "D", "text": "아프다시피 부모님 생각이 나려던 참이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Cấu trúc \"-기 마련이다\" diễn tả một quy luật tự nhiên, điều hiển nhiên sẽ xảy ra — \"hễ ốm đau thì đương nhiên sẽ nhớ bố mẹ\" — khớp với B.\nA(giả vờ nhớ), C(càng ốm càng ước gì nhớ), D(cấu trúc/nghĩa không hợp) đều sai."}, {"num": 12, "correct": "A", "stem": "버스를 타다 / 무단횡단을 하다 / 오토바이에 부딪히다", "options": [{"label": "A", "text": "버스를 타려고 무단횡단을 하다가 오토바이에 부딪힐 뻔했다."}, {"label": "B", "text": "버스를 타려면 무단횡단을 하곤 했다."}, {"label": "C", "text": "버스를 탈 텐데 무단횡단을 하다가 부딪힌 줄 알았다."}, {"label": "D", "text": "버스를 타면서 무단횡단을 하다가 부딪힐 정도이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Kết hợp \"-려고\"(mục đích: để bắt xe buýt), \"-다가\"(hành động đang làm thì bị ngắt quãng: đang băng qua đường trái phép), và \"-ㄹ 뻔하다\"(suýt nữa thì xảy ra: suýt bị xe máy tông) — khớp với A.\nB, C, D đều sai ngữ pháp hoặc sai nghĩa so với 3 vế cho trước."}, {"num": 13, "correct": "B", "stem": "누구나 가끔 기분이 우울할 때가 있다. 하지만 특별한 이유 없이 ( ), 단순한 기분 문제로 넘기지 말고 우울증을 의심해 전문가와 상담을 받는 것이 좋다.\n다음 ( )에 알맞은 것을 고르시오.", "options": [{"label": "A", "text": "기분이 좋아진다면"}, {"label": "B", "text": "우울한 기분이 지속된다면"}, {"label": "C", "text": "운동을 많이 한다면"}, {"label": "D", "text": "친구를 많이 만난다면"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Đoạn văn nói: nếu không có lý do đặc biệt mà ( ), thì không nên xem nhẹ mà nên nghi ngờ trầm cảm và đi khám — nên chỗ trống cần điền điều kiện \"nếu tâm trạng u uất cứ kéo dài\" — khớp với B.\nA(nếu tâm trạng tốt lên) ngược nghĩa. C(nếu tập thể dục nhiều) và D(nếu gặp bạn bè nhiều) đều là gợi ý cách cải thiện chứ không phải dấu hiệu cảnh báo cần đi khám."}, {"num": 14, "correct": "B", "stem": "[문화유산 아카데미 안내]\n대상: 성인 (선착순 20명)\n일시: 매주 토요일\n비용: 무료 (단, 입장료와 교통비는 개인 부담)\n※ 전 과정을 모두 참여한 분에게만 수료증을 발급합니다.\n다음 문화유산 아카데미에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "매주 평일 저녁에 진행된다."}, {"label": "B", "text": "입장료와 교통비는 개인이 각자 준비해야 한다."}, {"label": "C", "text": "신청한 사람 모두에게 수료증을 발급해 준다."}, {"label": "D", "text": "관심 있는 사람은 누구나 신청할 수 있다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Bảng thông tin ghi rõ \"비용: 무료 (단, 입장료와 교통비는 개인 부담)\" — khớp với B.\nA sai: chương trình học vào thứ Bảy chứ không phải các buổi tối ngày thường.\nC sai: phải tham gia đầy đủ các buổi mới được cấp giấy chứng nhận, không phải cứ đăng ký là có.\nD sai: chương trình chỉ dành cho người lớn và giới hạn 20 người, không phải ai cũng đăng ký được."}, {"num": 15, "correct": "D", "stem": "고혈압, 당뇨병과 같은 성인병은 대부분 ( )에서 시작된다. 짜게 먹는 습관, 운동 부족, 스트레스 등이 오랫동안 쌓이면 성인병으로 이어지기 쉽다. 따라서 규칙적으로 운동하고 싱겁게 먹는 등 건강한 생활 습관을 만드는 것이 성인병을 예방하는 가장 좋은 방법이다.\n윗글의 제목으로 가장 알맞은 것을 고르시오.", "options": [{"label": "A", "text": "성인병의 종류와 증상"}, {"label": "B", "text": "규칙적인 운동의 중요성"}, {"label": "C", "text": "건강 검진을 받는 방법"}, {"label": "D", "text": "성인병 예방을 위한 건강한 생활 습관"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Đoạn văn nói về việc bệnh người lớn xuất phát từ thói quen xấu, và cách phòng ngừa là xây dựng thói quen sinh hoạt lành mạnh — tiêu đề bao quát nhất là D.\nA chỉ nói về loại bệnh/triệu chứng, B chỉ là một phần nhỏ (vận động), C không phải nội dung chính của bài — đều hẹp hơn D."}, {"num": 16, "correct": "B", "stem": "고혈압, 당뇨병과 같은 성인병은 짜게 먹는 습관, 운동 부족, 스트레스 등 (ㄱ) 때문에 생기는 경우가 많아서 \"생활습관병\"이라고도 불린다. 그래서 규칙적으로 운동하고 싱겁게 먹는 등 건강한 생활 습관을 만드는 것이 성인병을 예방하는 가장 좋은 방법이다.\n윗글의 (ㄱ)에 들어갈 내용으로 알맞은 것을 고르시오.", "options": [{"label": "A", "text": "유전적인 요인"}, {"label": "B", "text": "잘못된 생활 습관"}, {"label": "C", "text": "다른 병의 합병증"}, {"label": "D", "text": "노화로 인한 자연스러운 현상"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Bệnh người lớn được gọi là \"생활 습관병\" (bệnh thói quen sinh hoạt), và bài liệt kê các thói quen xấu (ăn mặn, thiếu vận động, stress...) là nguyên nhân — nên (ㄱ) cần điền là \"thói quen sinh hoạt sai lầm\" — khớp với B.\nA(yếu tố di truyền), C(biến chứng của bệnh khác), D(hiện tượng tự nhiên do lão hóa) đều không phải nguyên nhân được bài nhấn mạnh."}, {"num": 17, "correct": "A", "stem": "<보기>\n· 국민의 기본적인 생활 수준을 보장한다\n· 소득이 낮은 사람들에게 생활비를 지원한다\n<보기>의 내용에 공통적으로 해당되는 것은?", "options": [{"label": "A", "text": "공공부조"}, {"label": "B", "text": "사회보험"}, {"label": "C", "text": "건강보험"}, {"label": "D", "text": "사회복지서비스"}], "correct_source": "docx", "options_source": "docx", "explanation": "공공부조 (trợ cấp công) là chế độ phúc lợi mà nhà nước hỗ trợ trực tiếp chi phí sinh hoạt cho người không có khả năng tự trang trải cuộc sống — khớp với A.\nB 사회보험(bảo hiểm xã hội) và C 건강보험(bảo hiểm y tế) là các hình thức bảo hiểm cần đóng phí trước, không phải trợ cấp trực tiếp; D 사회복지서비스(dịch vụ phúc lợi xã hội) là khái niệm rộng hơn, không khớp riêng với 2 đặc điểm nêu."}, {"num": 18, "correct": "D", "stem": "한국 농촌의 문제점을 해결하기 위한 방법으로 맞는 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 농촌 지역은 인구가 부족해서 살 집이 부족하다.\nㄴ. 젊은 사람들이 도시로 떠나면서 농촌에 일손이 부족해졌다.\nㄷ. 편의 시설을 늘리고 정보화 교육을 실시한다.\nㄹ. 새로운 기술을 도입하여 생산성을 높인다.", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄱ, ㄷ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Giải pháp thực sự cho vấn đề nông thôn là ㄷ (tăng cường cơ sở tiện ích và giáo dục tin học) và ㄹ (nâng cao năng suất bằng công nghệ mới) — khớp với D.\nㄱ sai vì nông thôn đang GIẢM dân số (không phải thiếu nhà vì thiếu dân).\nㄴ là một NGUYÊN NHÂN gây ra vấn đề (thiếu lao động trẻ), không phải một GIẢI PHÁP."}, {"num": 19, "correct": "A", "stem": "한국의 고등 교육기관에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "한국의 고등 교육기관에는 고등학교, 대학교, 대학원이 있다."}, {"label": "B", "text": "대학교는 4년제와 2~3년제 전문대학으로 나뉜다."}, {"label": "C", "text": "대학원은 석사 과정과 박사 과정으로 구성된다."}, {"label": "D", "text": "고등 교육기관에 진학하려면 고등학교를 졸업해야 한다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "\"고등 교육기관\" (giáo dục bậc cao) ở Hàn Quốc chỉ gồm Đại học (대학교) và Cao học (대학원) — trường cấp 3 (고등학교) thuộc \"중등 교육기관\" (giáo dục trung học), không phải giáo dục bậc cao — nên A là câu SAI, đây là đáp án đúng.\nB, C, D đều là mô tả đúng về hệ thống giáo dục đại học/sau đại học Hàn Quốc."}, {"num": 20, "correct": "D", "stem": "<보기>\n포크 · 휴지 · 찹쌀떡\n<보기>에 제시된 용어로 설명할 수 있는 한국의 사회 현상으로 가장 적절한 것은?", "options": [{"label": "A", "text": "명절에 조상들께 감사의 의미로 드리는 선물이다."}, {"label": "B", "text": "결혼식에서 신랑 신부에게 주는 전통 선물이다."}, {"label": "C", "text": "이사할 때 이웃에게 인사로 주는 선물이다."}, {"label": "D", "text": "대학수학능력시험이 중요하므로 시험을 잘 보라는 의미로 선물한다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Đây là những món quà truyền thống tặng cho sĩ tử trước kỳ thi đại học (수능), mang ý nghĩa chơi chữ: 포크(nĩa) liên tưởng \"찍다\" (đâm/chọn trúng đáp án), 휴지(giấy vệ sinh) liên tưởng \"풀다\" (gỡ/giải bài trôi chảy), 찹쌀떡(bánh nếp) liên tưởng \"붙다\" (dính/thi đậu) — khớp với D.\nA, B, C là các dịp tặng quà khác không liên quan đến 3 món quà chơi chữ này."}, {"num": 21, "correct": "D", "stem": "평생교육에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "평생교육은 정규 학교 교육 이외의 다양한 교육 활동을 말한다."}, {"label": "B", "text": "평생학습관, 도서관 등에서 다양한 평생교육 프로그램을 운영한다."}, {"label": "C", "text": "나이나 학력에 관계없이 누구나 참여할 수 있다."}, {"label": "D", "text": "최근에는 인터넷 등 미디어를 이용한 평생교육은 감소하고 있다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Thực tế hoàn toàn ngược lại — nhờ công nghệ, việc học tập suốt đời qua internet/media đang TĂNG rất mạnh, không phải giảm — nên D là câu SAI, đây là đáp án đúng.\nA, B, C đều là mô tả đúng về giáo dục suốt đời (평생교육) ở Hàn Quốc."}, {"num": 22, "correct": "B", "stem": "한국 음식에 대한 설명으로 옳은 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 숟가락과 젓가락을 이용해서 밥과 국을 먹는다.\nㄴ. 불고기는 대표적인 발효 음식이다.\nㄷ. 생일이나 명절에 떡을 먹는 풍습이 있다.\nㄹ. 국은 재료를 굽는 방식으로 만든 음식이다.", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄱ, ㄷ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "ㄱ đúng: người Hàn dùng thìa và đũa để ăn cơm, canh. ㄷ đúng: có phong tục ăn bánh tteok vào dịp sinh nhật, lễ Tết — khớp với B.\nㄴ sai: 불고기 (thịt nướng) không phải món ăn lên men.\nㄹ sai: 국 (canh) là món nấu bằng nước, không phải chế biến bằng cách nướng."}, {"num": 23, "correct": "B", "stem": "<보기>\n영화, 음악, 패션처럼 많은 사람들이 일상생활에서 즐기고 좋아하는 문화\n<보기>의 ( )에 공통으로 들어갈 말은?", "options": [{"label": "A", "text": "전통문화"}, {"label": "B", "text": "대중문화"}, {"label": "C", "text": "지역문화"}, {"label": "D", "text": "다문화"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Văn hóa được đông đảo người dân yêu thích trong đời sống hàng ngày (phim, nhạc, thời trang) gọi là \"대중문화\" (văn hóa đại chúng) — khớp với B.\nA 전통문화(văn hóa truyền thống), C 지역문화(văn hóa địa phương), D 다문화(đa văn hóa) đều là khái niệm khác, không khớp với đặc điểm \"được đông đảo yêu thích trong đời sống hàng ngày\"."}, {"num": 24, "correct": "A", "stem": "선거에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "보통선거는 만 20세가 된 국민은 누구나 선거에 참여할 수 있다는 것이다."}, {"label": "B", "text": "평등선거는 모든 유권자가 한 표씩 동등하게 행사하는 것이다."}, {"label": "C", "text": "직접선거는 유권자가 대리인 없이 직접 투표하는 것이다."}, {"label": "D", "text": "비밀선거는 누구에게 투표했는지 다른 사람이 알 수 없게 하는 것이다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Ở Hàn Quốc, độ tuổi có quyền bầu cử hiện tại là đủ 18 tuổi (만 18세), không phải 20 tuổi như A nêu — nên A là câu SAI, đây là đáp án đúng.\nB, C, D là mô tả đúng về 3 nguyên tắc còn lại trong 4 nguyên tắc bầu cử cơ bản (bình đẳng, trực tiếp, bí mật)."}, {"num": 25, "correct": "B", "stem": "<보기>\n영주(F-5) 자격을 얻은 후 3년이 지난 외국인\n<보기>의 내용에 해당하는 사람이 할 수 있는 것은?", "options": [{"label": "A", "text": "대통령 선거"}, {"label": "B", "text": "지방 선거"}, {"label": "C", "text": "국회의원 선거"}, {"label": "D", "text": "국민투표"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Người nước ngoài có thẻ vĩnh trú (F-5) trên 3 năm được quyền tham gia bỏ phiếu trong Bầu cử ĐỊA PHƯƠNG (지방 선거) để bầu thị trưởng, hội đồng địa phương — khớp với B.\nA(bầu Tổng thống), C(bầu Quốc hội), D(trưng cầu dân ý toàn quốc) đều chỉ dành cho công dân Hàn Quốc."}, {"num": 26, "correct": "C", "stem": "<보기>\n· 법에 따라 다툼을 해결하는 곳이다\n· 대법원, 지방법원 등이 있다\n<보기>의 내용에 공통적으로 해당되는 것은?", "options": [{"label": "A", "text": "입법부"}, {"label": "B", "text": "행정부"}, {"label": "C", "text": "사법부"}, {"label": "D", "text": "헌법재판소"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Hệ thống tòa án (법원) — nơi giải quyết tranh chấp theo pháp luật — chính là nhánh Tư pháp (사법부) — khớp với C.\nA 입법부(lập pháp — Quốc hội), B 행정부(hành pháp — Chính phủ) là 2 nhánh quyền lực khác; D 헌법재판소(Tòa án Hiến pháp) là một cơ quan cụ thể, không bao quát toàn bộ hệ thống tòa án được mô tả."}, {"num": 27, "correct": "A", "stem": "한국이 빠르게 경제 성장을 이룰 수 있었던 요인이 아닌 것은?", "options": [{"label": "A", "text": "자본과 자원"}, {"label": "B", "text": "높은 교육열과 우수한 인적 자원"}, {"label": "C", "text": "정부 주도의 수출 중심 경제 정책"}, {"label": "D", "text": "근면하고 성실한 노동력"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Sau chiến tranh, Hàn Quốc là một nước rất nghèo, gần như không có vốn (자본) và cực kỳ khan hiếm tài nguyên (자원) — nên \"vốn và tài nguyên\" KHÔNG phải là yếu tố giúp tăng trưởng, mà ngược lại là điểm bất lợi — nên A là câu trả lời đúng cho câu hỏi \"yếu tố KHÔNG phải\".\nB, C, D đều là những yếu tố thực sự đã giúp Hàn Quốc tăng trưởng nhanh: tinh thần hiếu học/nguồn nhân lực tốt, chính sách kinh tế hướng xuất khẩu do chính phủ chủ trì, và lực lượng lao động cần cù."}, {"num": 28, "correct": "B", "stem": "금융 기관에 대한 설명으로 옳은 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 농협이나 우체국은 안전하고 이용하기 편리하다.\nㄴ. 지방은행은 이자가 높지만 규모가 작다.\nㄷ. 인터넷전문은행은 절차가 간단하고 수수료가 낮다.\nㄹ. 한국은행은 개인과 직접 예금 거래를 한다.", "options": [{"label": "A", "text": "ㄱ, ㄴ, ㄷ"}, {"label": "B", "text": "ㄱ, ㄷ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄴ, ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "ㄱ đúng: Nonghyup và bưu điện an toàn, thuận tiện khi sử dụng. ㄷ đúng: ngân hàng Internet có thủ tục đơn giản và phí thấp. ㄹ sai: Ngân hàng Trung ương Hàn Quốc không trực tiếp nhận tiền gửi của cá nhân. Vì vậy đáp án phù hợp là B (ㄱ, ㄷ)."}, {"num": 29, "correct": "A", "stem": "전통 시장에 대한 설명으로 옳은 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 전통 시장은 매일 상시로 운영되는 시장이다.\nㄴ. 물건 값을 흥정할 수 있다.\nㄷ. 24시간 언제나 이용할 수 있다.\nㄹ. 대형 마트처럼 모든 물건을 대규모로 판매한다.", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄱ, ㄷ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "ㄴ đúng: tại chợ truyền thống người mua có thể thương lượng giá. ㄷ sai vì mở cửa 24/24 là đặc điểm của cửa hàng tiện lợi. ㄹ sai vì bán rất nhiều loại hàng hóa với quy mô lớn là đặc điểm của siêu thị lớn. Vì vậy đáp án phù hợp là A."}, {"num": 30, "correct": "D", "stem": "국적을 결정하는 방법에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "한국은 혈통주의를 원칙으로 국적을 결정한다."}, {"label": "B", "text": "부모 중 한 명이라도 한국인이면 자녀는 한국 국적을 가질 수 있다."}, {"label": "C", "text": "외국인은 일정 요건을 갖추면 귀화를 통해 한국 국적을 취득할 수 있다."}, {"label": "D", "text": "부모가 모두 외국인이라도 한국에서 태어난 자녀는 대한민국 국민이 될 수 있다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Hàn Quốc áp dụng nguyên tắc Huyết thống (혈통주의), không phải nguyên tắc Nơi sinh — nếu cả cha lẫn mẹ đều là người nước ngoài, đứa trẻ sinh ra ở Hàn Quốc vẫn KHÔNG tự động trở thành công dân Hàn Quốc — nên D là câu SAI, đây là đáp án đúng.\nA, B, C đều là mô tả đúng về nguyên tắc quốc tịch huyết thống và điều kiện nhập tịch của Hàn Quốc."}, {"num": 31, "correct": "B", "stem": "한국의 법 집행기관에 대한 설명으로 옳은 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 검찰은 범죄를 수사하고 기소하는 역할을 한다.\nㄴ. 검찰은 도로에서 교통 단속을 담당한다.\nㄷ. 경찰은 국민의 생명과 재산을 보호하는 역할을 한다.\nㄹ. 경찰은 법정에서 형량을 결정한다.", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄱ, ㄷ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "ㄱ đúng: Viện kiểm sát (검찰) điều tra và khởi tố tội phạm. ㄷ đúng: Cảnh sát (경찰) bảo vệ tính mạng/tài sản của người dân — khớp với B.\nㄴ sai: việc tuần tra giao thông là của Cảnh sát, không phải Viện kiểm sát.\nㄹ sai: việc quyết định hình phạt tại tòa là của Thẩm phán, không phải Cảnh sát."}, {"num": 32, "correct": "B", "stem": "고조선과 관련된 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 불교를 받아들여 국교로 삼았다.\nㄴ. 8조법으로 사회 질서를 유지했다.\nㄷ. 청동기 문화를 배경으로 성립되었다.\nㄹ. 한글을 창제하여 사용하였다.\nㅁ. 단군왕검이 세운 나라이다.", "options": [{"label": "A", "text": "ㄱ, ㄴ, ㄷ"}, {"label": "B", "text": "ㄴ, ㄷ, ㅁ"}, {"label": "C", "text": "ㄷ, ㄹ, ㅁ"}, {"label": "D", "text": "ㄱ, ㄹ, ㅁ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Gojoseon (고조선) do Dangun Wanggeom lập ra (ㅁ đúng), hình thành trên nền tảng văn hóa đồ đồng (ㄷ đúng), và xã hội được duy trì trật tự bằng Luật 8 điều — 8조법 (ㄴ đúng) — khớp với B.\nㄱ sai: việc tiếp nhận Phật giáo làm quốc giáo là của các vương triều sau này (như Silla, Goguryeo), không phải Gojoseon.\nㄹ sai: chữ Hangeul được vua Sejong triều Joseon sáng tạo, cách Gojoseon hàng nghìn năm."}, {"num": 33, "correct": "C", "stem": "<보기>\n(가) 3·1 운동\n(나) 8·15 광복\n(다) 대한제국 수립\n(라) 대한민국 임시정부 수립\n<보기>를 시간 순서대로 배열한 것은?", "options": [{"label": "A", "text": "(가)-(다)-(나)-(라)"}, {"label": "B", "text": "(다)-(라)-(가)-(나)"}, {"label": "C", "text": "(다)-(가)-(라)-(나)"}, {"label": "D", "text": "(라)-(다)-(가)-(나)"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Thứ tự thời gian chính xác: Thành lập Đại Hàn Đế Quốc (1897) → Phong trào 3·1 (1/3/1919) → Thành lập Chính phủ lâm thời (11/4/1919, ngay sau phong trào 3·1) → Quang phục (15/8/1945) — khớp với C.\nA, B, D đều sắp xếp sai thứ tự thời gian giữa các sự kiện."}, {"num": 34, "correct": "A", "stem": "조선 시대의 과학 기술에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "백성들에게 세금을 많이 받기 위해 과학 기술을 중요하게 생각했다."}, {"label": "B", "text": "세종대왕은 해시계와 물시계를 만들었다."}, {"label": "C", "text": "세계 최초로 측우기를 발명했다."}, {"label": "D", "text": "거중기를 이용해 수원 화성 건설 기간을 단축했다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Thời Joseon (đặc biệt thời vua Sejong), khoa học công nghệ được phát triển nhằm mục đích hỗ trợ nông nghiệp và đời sống bách tính (ví dụ: máy đo lượng mưa để biết thời điểm gieo trồng), chứ không phải để thu nhiều thuế hơn — nên A là câu SAI, đây là đáp án đúng.\nB, C, D đều là thành tựu khoa học kỹ thuật có thật thời Joseon: đồng hồ mặt trời/nước do vua Sejong cho chế tạo, máy đo lượng mưa (측우기) đầu tiên trên thế giới, và cần cẩu (거중기) giúp rút ngắn thời gian xây thành Suwon Hwaseong."}, {"num": 35, "correct": "C", "stem": "<보기>\n한국의 서해안과 남해안은 수심이 얕고 밀물과 썰물의 차이가 커서 ( )이/가 발달했다. 특히 서해안의 ( )은/는 세계 5대 ( ) 중 하나로 꼽힌다.\n<보기>의 ( )에 공통으로 들어갈 말은?", "options": [{"label": "A", "text": "산지"}, {"label": "B", "text": "평야"}, {"label": "C", "text": "갯벌"}, {"label": "D", "text": "하천"}], "correct_source": "docx", "options_source": "docx", "explanation": "Bờ biển phía Tây Hàn Quốc nổi tiếng thế giới với các bãi bùn/bãi triều (갯벌) rộng lớn, hình thành do chênh lệch thủy triều (밀물과 썰물) rất lớn — khớp với C.\nA 산지(vùng núi), B 평야(đồng bằng), D 하천(sông ngòi) đều không liên quan đến hiện tượng thủy triều ven biển được mô tả."}, {"num": 36, "correct": "C", "stem": "<보기>\n· 음식 문화가 발달했다\n· 전통문화가 잘 보존되어 있다\n· 최근 중국과의 교류가 늘고 있다\n<보기>의 내용과 가장 관계가 깊은 지역은?", "options": [{"label": "A", "text": "경기지역"}, {"label": "B", "text": "강원지역"}, {"label": "C", "text": "전라지역"}, {"label": "D", "text": "경상지역"}], "correct_source": "docx", "options_source": "docx", "explanation": "Vùng Jeolla (전라지역, Tây Nam Hàn Quốc) nổi tiếng nhất cả nước về văn hóa ẩm thực phong phú, còn bảo tồn nhiều văn hóa truyền thống (như làng Hanok Jeonju, nghệ thuật Pansori), và gần đây tăng cường giao lưu thương mại với Trung Quốc qua các cảng như Gunsan — khớp với C.\nA(vùng Gyeonggi), B(vùng Gangwon), D(vùng Gyeongsang) đều không khớp với cả 3 đặc điểm nêu trên."}], "tables": []}, "round2": {"title": "Mô phỏng KIIP cấp 5 - 5단계 2회", "source": "한국어_모의고사_(5단계_2회)_—_Giải_thích_chi_tiết.docx", "questions": [{"num": 1, "correct": "D", "stem": "아침에 출근하다가 가벼운 접촉 사고를 내서 ( )으로 10만 원을 주었다.", "options": [{"label": "A", "text": "등록금"}, {"label": "B", "text": "조의금"}, {"label": "C", "text": "축의금"}, {"label": "D", "text": "합의금"}], "correct_source": "docx", "options_source": "docx", "explanation": "Khi xảy ra va chạm giao thông nhẹ (접촉 사고), người ta thường đưa \"tiền thỏa thuận/bồi thường\" (합의금) để giải quyết nhanh — khớp với D.\nA 등록금(học phí), B 조의금(tiền phúng điếu), C 축의금(tiền mừng cưới) đều là loại tiền dùng trong dịp khác."}, {"num": 2, "correct": "D", "stem": "투이 씨는 대기업에 ( ) 위해서 이력서와 자기소개서를 준비하고 있다.", "options": [{"label": "A", "text": "모집하기"}, {"label": "B", "text": "작성하기"}, {"label": "C", "text": "졸업하기"}, {"label": "D", "text": "지원하기"}], "correct_source": "docx", "options_source": "docx", "explanation": "Chuẩn bị sơ yếu lý lịch và thư giới thiệu bản thân là để \"ứng tuyển\" (지원하다) vào công ty lớn — khớp với D.\nA 모집하기(tuyển dụng) là việc của công ty chứ không phải người xin việc.\nB 작성하기(viết) không đi với trợ từ \"에\" theo cấu trúc câu này.\nC 졸업하기(tốt nghiệp) không liên quan đến việc chuẩn bị hồ sơ xin việc."}, {"num": 3, "correct": "D", "stem": "아파트에 사는 사람들이 많아지면서 위층과 아래층 사이에 ( ) 문제가 많이 발생했다.", "options": [{"label": "A", "text": "무단 횡단"}, {"label": "B", "text": "음주 운전"}, {"label": "C", "text": "불법 주차"}, {"label": "D", "text": "층간 소음"}], "correct_source": "docx", "options_source": "docx", "explanation": "Vấn đề phổ biến nhất giữa tầng trên và tầng dưới ở chung cư là tiếng ồn giữa các tầng (층간 소음) — khớp với D.\nA 무단횡단(băng qua đường trái phép), B 음주운전(lái xe say rượu), C 불법주차(đậu xe trái phép) đều là vấn đề giao thông, không liên quan đến hàng xóm trên dưới."}, {"num": 4, "correct": "A", "stem": "그 영화는 배우들이 연기도 잘하고 영상미도 ( ) 인기가 많다.", "options": [{"label": "A", "text": "뛰어나서"}, {"label": "B", "text": "평범해서"}, {"label": "C", "text": "부정확해서"}, {"label": "D", "text": "흥미로워서"}], "correct_source": "docx", "options_source": "docx", "explanation": "\"영상미가 뛰어나다\" = hình ảnh/góc quay rất đẹp, xuất sắc — khớp với việc phim đang được khen (diễn xuất tốt + hình ảnh đẹp → nổi tiếng) — khớp với A.\nB 평범해서(bình thường), C 부정확해서(không chính xác) đều mang nghĩa tiêu cực/trung tính, không hợp lý do \"인기가 많다\".\nD 흥미로워서(thú vị) ít khi dùng để miêu tả \"영상미\" (thường dùng cho nội dung/cốt truyện hơn)."}, {"num": 5, "correct": "D", "stem": "가: 여기에 쓰레기를 버려도 돼요?\n나: 아니요, 여기에 쓰레기를 ( ) 안 돼요.", "options": [{"label": "A", "text": "버려도"}, {"label": "B", "text": "버려서"}, {"label": "C", "text": "버려야"}, {"label": "D", "text": "버리면"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cấu trúc cấm đoán \"-(으)면 안 되다\" (không được làm gì) — \"không được vứt rác ở đây\" — khớp với D.\nA 버려도(dù vứt), B 버려서(vì vứt), C 버려야(phải vứt) đều không tạo được cấu trúc cấm đoán đúng ngữ pháp."}, {"num": 6, "correct": "A", "stem": "가: 돈을 많이 ( ) 뭘 하고 싶어요?\n나: 새집으로 이사를 가고 싶어요.", "options": [{"label": "A", "text": "벌면"}, {"label": "B", "text": "벌도록"}, {"label": "C", "text": "벌려면"}, {"label": "D", "text": "벌지만"}], "correct_source": "docx", "options_source": "docx", "explanation": "Câu hỏi giả định \"-(으)면\": \"nếu kiếm được nhiều tiền thì muốn làm gì?\" — khớp với A.\nB 벌도록(để kiếm), C 벌려면(nếu muốn kiếm), D 벌지만(dù kiếm) đều không hợp cấu trúc giả định \"nếu...thì\" này."}, {"num": 7, "correct": "B", "stem": "가: 무슨 일 있었어요? 왜 이렇게 늦은 거예요?\n나: 미안해요. 버스를 반대 방향으로 잘못 ( ) 늦었어요.", "options": [{"label": "A", "text": "타고"}, {"label": "B", "text": "타서"}, {"label": "C", "text": "타되"}, {"label": "D", "text": "타다가"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cấu trúc chỉ nguyên nhân \"-아/어서\": \"vì lên nhầm xe buýt theo hướng ngược lại nên đã đến trễ\" — khớp với B.\nA 타고(lên và...) chỉ liệt kê hành động nối tiếp, không rõ nguyên nhân.\nC 타되(lên nhưng...) và D 타다가(đang lên thì...) đều không diễn tả đúng quan hệ nguyên nhân-kết quả cần thiết."}, {"num": 8, "correct": "C", "stem": "가: 영민 씨와 같은 회사에서 일한다면서요? 자주 만나지요?\n나: 아니요, 같은 회사에서 ( ) 자주 못 만나요.", "options": [{"label": "A", "text": "일해서"}, {"label": "B", "text": "일하더니"}, {"label": "C", "text": "일하는데"}, {"label": "D", "text": "일하므로"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cấu trúc \"-(으)ㄴ/는데\" dùng để nối hai vế có ý nghĩa tương phản — \"làm cùng công ty đấy nhưng không gặp nhau thường xuyên đâu\" — khớp với C.\nA 일해서(vì làm) và D 일하므로(vì làm) đều chỉ nguyên nhân, không hợp ý tương phản.\nB 일하더니(làm thế mà...) dùng cho một sự thay đổi/kết quả tiếp diễn theo thời gian, không hợp ngữ cảnh này."}, {"num": 9, "correct": "B", "stem": "청계천에서 하는 서울 등 축제에 갔는데 물 위에 띄운 유등이 아름답고 ( ).", "options": [{"label": "A", "text": "구경할 뻔했다"}, {"label": "B", "text": "구경할 만했다"}, {"label": "C", "text": "구경할지도 모른다"}, {"label": "D", "text": "구경하기 마련이다"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cấu trúc \"-ㄹ 만하다\" nghĩa là \"đáng để làm gì\" — đèn lồng thả trên mặt nước đẹp và đáng để ngắm — khớp với B.\nA 구경할 뻔했다(suýt ngắm — nghĩa là cuối cùng không xem được, sai logic), C 구경할지도 모른다(không biết chừng sẽ ngắm — mang tính phỏng đoán, sai ngữ cảnh vì người nói đã đi xem rồi), D 구경하기 마련이다(hiển nhiên là ngắm) đều không hợp."}, {"num": 10, "correct": "B", "stem": "선생님께서 공연이 9시에 시작하니까 8시 40분까지 ( ).", "options": [{"label": "A", "text": "오냐고 하셨다"}, {"label": "B", "text": "오라고 하셨다"}, {"label": "C", "text": "온다고 하셨다"}, {"label": "D", "text": "왔다고 하셨다"}], "correct_source": "docx", "options_source": "docx", "explanation": "Câu trần thuật gián tiếp của câu mệnh lệnh: giáo viên bảo \"hãy đến\" → \"오라고 하셨다\" — khớp với B.\nA 오냐고 하셨다(đã hỏi là có đến không) là câu gián tiếp của câu HỎI, không phải mệnh lệnh.\nC 온다고 하셨다(nói là thầy sẽ đến) và D 왔다고 하셨다(nói là đã đến) là câu gián tiếp của câu TRẦN THUẬT, không hợp ngữ cảnh giáo viên đang RA LỆNH cho học sinh đến sớm."}, {"num": 11, "correct": "B", "stem": "열심히 준비하다 / 입사시험에 떨어지다", "options": [{"label": "A", "text": "열심히 준비하려고 입사시험에 떨어질 뻔했다."}, {"label": "B", "text": "열심히 준비했지만 입사시험에 떨어질 것 같다."}, {"label": "C", "text": "열심히 준비하는 대신 입사시험에 떨어지고 말았다."}, {"label": "D", "text": "열심히 준비하다가 입사시험에 떨어지도록 했다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Nối 2 vế có ý nghĩa đối lập bằng \"-지만\" (tuy... nhưng...): \"đã chuẩn bị chăm chỉ nhưng có vẻ sẽ rớt\" — khớp với B. Đây là câu hợp lý nhất về ngữ nghĩa dù thì của động từ có thay đổi một chút so với 2 vế gốc.\nA \"-으려고...ㄹ 뻔하다\"(định làm... suýt...) sai nghĩa hoàn toàn. C \"-는 대신\"(thay vì) không hợp quan hệ đối lập cần có. D \"-다가...도록 하다\"(đang làm thì... để cho...) sai ngữ pháp và nghĩa."}, {"num": 12, "correct": "C", "stem": "서울은 대중교통이 발달하다 / 자가용 없이 여행하다 / 가능하다", "options": [{"label": "A", "text": "서울은 대중교통이 발달하지만 자가용 없이 여행하는 것이 가능하다."}, {"label": "B", "text": "서울은 대중교통이 발달하는 대신 자가용 없이 여행하는 것이 불가능하다."}, {"label": "C", "text": "서울은 대중교통이 발달해서 자가용 없이 여행하는 것이 가능하다."}, {"label": "D", "text": "서울은 대중교통이 발달하도록 자가용 없이 여행할 수밖에 없다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Nối 3 vế bằng quan hệ nguyên nhân-kết quả \"-아/어서\" và cấu trúc danh từ hóa \"-는 것이 가능하다\": \"vì giao thông công cộng phát triển nên có thể du lịch không cần xe riêng\" — khớp với C.\nA dùng \"-지만\"(nhưng) sai vì hai vế không đối lập mà là nhân-quả. B đảo ngược thành \"불가능하다\"(không thể) sai nghĩa hoàn toàn. D sai ngữ pháp/nghĩa."}, {"num": 13, "correct": "C", "stem": "돌잔치에서는 아기 앞에 실, 돈, 연필, 마이크 등 여러 가지 물건을 놓고 아기가 그중 하나를 고르게 하는 순서가 있다. 사람들은 아기가 어떤 물건을 집는지 보면서 아기의 미래를 상상해 보곤 한다. 이것은 ( ).", "options": [{"label": "A", "text": "아기의 건강을 기원하는 백일잔치였다"}, {"label": "B", "text": "부모의 결혼을 기념하는 행사였다"}, {"label": "C", "text": "아기의 장래를 추측하는 돌잡이 행사였다"}, {"label": "D", "text": "아기의 이름을 짓는 작명 행사였다"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Đoạn văn giải thích việc em bé chọn tiền, bút chì, micro... trong tiệc thôi nôi — đây chính là nghi thức Doljabi (돌잡이) để đoán tương lai của bé — khớp với C.\nA(tiệc mừng 100 ngày tuổi, khác dịp), B(kỷ niệm hôn nhân cha mẹ, không liên quan), D(lễ đặt tên, khác nghi thức) đều sai chủ đề."}, {"num": 14, "correct": "A", "stem": "[선거 포스터]\n○○시장 선거\n투표일: 6월 14일(수) 오전 6시 ~ 오후 6시\n사전투표일: 6월 9일(금) ~ 10일(토)\n준비물: 신분증 지참\n\n다음 선거 포스터의 내용과 같은 것은?", "options": [{"label": "A", "text": "투표를 하려면 주민등록증을 가져가야 한다."}, {"label": "B", "text": "국회의원을 뽑는 선거이다."}, {"label": "C", "text": "저녁 8시까지 투표할 수 있다."}, {"label": "D", "text": "14일은 사전투표일이다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Poster ghi rõ \"준비물: 신분증 지참\" (mang theo giấy tờ tùy thân) — CMND (주민등록증) là một loại giấy tờ tùy thân — khớp với A.\nB sai: đây là bầu cử ĐỊA PHƯƠNG, không phải bầu quốc hội.\nC sai: giờ bỏ phiếu kết thúc lúc 18:00 (6 giờ chiều), không phải 20:00 (8 giờ tối).\nD sai: ngày 14 là ngày bỏ phiếu CHÍNH THỨC, không phải ngày bỏ phiếu sớm."}, {"num": 15, "correct": "A", "stem": "스마트폰은 이제 우리 생활에서 없어서는 안 될 물건이 되었다. 스마트폰 하나만 있으면 길을 찾거나 물건을 사거나 은행 업무를 보는 등 많은 일을 신속하고 편리하게 해결할 수 있게 되었다. 하지만 스마트폰에 지나치게 의존하다 보면 사람들과 직접 얼굴을 보고 대화하는 시간이 줄어들고, 심한 경우에는 스마트폰 중독으로 이어지기도 한다.\n윗글의 제목으로 가장 알맞은 것을 고르시오.", "options": [{"label": "A", "text": "스마트폰의 장점과 단점"}, {"label": "B", "text": "스마트폰 중독의 위험성"}, {"label": "C", "text": "스마트폰을 올바르게 사용하는 방법"}, {"label": "D", "text": "최신 스마트폰의 다양한 기능"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Bài đọc có 2 phần rõ rệt: ưu điểm (tiện lợi) và nhược điểm (ít giao tiếp, gây nghiện) — tiêu đề bao quát nhất là A \"Ưu điểm và nhược điểm của smartphone\".\nB chỉ đề cập nhược điểm (nghiện), C và D không khớp với nội dung 2 phần đối lập được mô tả."}, {"num": 16, "correct": "D", "stem": "스마트폰은 이제 우리 생활에서 없어서는 안 될 물건이 되었다. 스마트폰 하나만 있으면 길을 찾거나 물건을 사거나 은행 업무를 보는 등 ( ). 하지만 스마트폰에 지나치게 의존하다 보면 사람들과 직접 얼굴을 보고 대화하는 시간이 줄어들고, 심한 경우에는 스마트폰 중독으로 이어지기도 한다.\n윗글의 ( )에 들어갈 내용으로 알맞은 것을 고르시오.", "options": [{"label": "A", "text": "사람들과의 대화가 줄어들게 되었다"}, {"label": "B", "text": "스마트폰 중독 문제가 심각해지고 있다"}, {"label": "C", "text": "예전보다 눈 건강이 나빠지고 있다"}, {"label": "D", "text": "많은 일을 신속하고 편리하게 해결할 수 있게 되었다"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Chỗ trống nằm trong phần nói về ƯU ĐIỂM của smartphone, cần một câu tóm tắt sự tiện lợi — khớp với D \"có thể giải quyết nhiều việc nhanh chóng, tiện lợi\".\nA, B, C đều là các câu đúng về smartphone nhưng mô tả NHƯỢC điểm (ít giao tiếp, gây nghiện, hại mắt), sai vị trí vì chỗ trống thuộc phần ưu điểm."}, {"num": 17, "correct": "A", "stem": "한국의 주거 문화의 변화에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "과거와 달리 요즘 단독 주택이 대부분이다."}, {"label": "B", "text": "아파트에 거주하는 가구의 비율이 점점 늘어나고 있다."}, {"label": "C", "text": "1인 가구가 증가하면서 소형 주택에 대한 수요도 늘고 있다."}, {"label": "D", "text": "직장과 가까운 곳에 거주하려는 경향이 강해지고 있다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Ở Hàn Quốc hiện nay, loại hình nhà ở phổ biến nhất là chung cư (아파트), không phải nhà riêng (단독 주택) — nên A là câu SAI, đây là đáp án đúng.\nB, C, D đều là xu hướng thực tế đúng trong sự thay đổi văn hóa cư trú của Hàn Quốc."}, {"num": 18, "correct": "A", "stem": "<보기>\n감기처럼 가벼운 증상이 있을 때는 집 근처에 있는 (가)에 가서 편하게 진료를 받을 수 있다. 예방접종이나 건강 상담은 국가에서 운영하는 (나)에서 저렴한 비용으로 받을 수 있다.\n<보기>의 (가), (나)에 들어갈 용어로 적절한 것은?", "options": [{"label": "A", "text": "(가) 동네 의원 - (나) 보건소"}, {"label": "B", "text": "(가) 종합병원 - (나) 보건소"}, {"label": "C", "text": "(가) 동네 의원 - (나) 종합병원"}, {"label": "D", "text": "(가) 보건소 - (나) 동네 의원"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Bệnh nhẹ thì đến phòng khám khu phố (동네 의원). Cơ quan y tế công cộng do nhà nước điều hành, phí rẻ, chuyên tiêm phòng là Trạm y tế (보건소) — khớp với A.\nB, C, D đều thay một hoặc cả hai vị trí bằng cơ sở y tế khác không đúng vai trò được mô tả trong <보기>."}, {"num": 19, "correct": "A", "stem": "<보기>\n· 나이에 관계없이 배울 수 있다\n· 문해 교육, 직업 교육 등을 포함한다\n· 도서관, 문화센터 등에서 이루어진다\n<보기>의 내용과 가장 관계가 깊은 것은?", "options": [{"label": "A", "text": "평생교육"}, {"label": "B", "text": "직업교육"}, {"label": "C", "text": "의무교육"}, {"label": "D", "text": "특수교육"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Việc học tập không ngừng nghỉ ở mọi lứa tuổi, tại nhiều địa điểm khác nhau (thư viện, trung tâm văn hóa) chính là \"giáo dục suốt đời\" (평생교육) — khớp với A.\nB 직업교육(giáo dục nghề nghiệp) chỉ là MỘT phần trong nội dung <보기>, không bao quát được \"học bất kể tuổi tác\". C 의무교육(giáo dục bắt buộc) và D 특수교육(giáo dục đặc biệt) là khái niệm khác hẳn."}, {"num": 20, "correct": "B", "stem": "한국의 교육에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "한국은 대학 진학률이 다른 나라에 비해 낮은 편이다."}, {"label": "B", "text": "한국에서는 교육이 사회적 지위를 상승시킬 수 있는 주요 방법으로 인식된다."}, {"label": "C", "text": "고등학교까지 무상 의무 교육이 시행되고 있어 사교육이 거의 없다."}, {"label": "D", "text": "대학 진학보다 취업을 목표로 하는 특성화고 진학률이 훨씬 높다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Giáo dục được coi là con đường chính để nâng cao địa vị xã hội — đặc điểm nổi bật của văn hóa \"nhiệt huyết giáo dục cao\" (교육열) ở Hàn Quốc — khớp với B.\nA sai: Hàn Quốc có tỷ lệ vào đại học thuộc hàng cao nhất thế giới, không phải thấp.\nC sai: dù có giáo dục công miễn phí đến cấp 3, giáo dục tư (사교육/học thêm) vẫn cực kỳ phổ biến.\nD sai: đa số học sinh vẫn hướng đến vào đại học hơn là trường nghề (특성화고)."}, {"num": 21, "correct": "C", "stem": "한국의 식사 예절에 대한 설명으로 옳은 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 밥그릇을 손에 들고 먹는다.\nㄴ. 웃어른이 수저를 든 후에 식사를 시작한다.\nㄷ. 음식을 먹을 때 큰 소리를 내도 예의에 어긋나지 않는다.\nㄹ. 기침이 나올 때는 고개를 돌리고 입을 가린다.", "options": [{"label": "A", "text": "ㄱ, ㄷ"}, {"label": "B", "text": "ㄱ, ㄴ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "ㄴ đúng: phải đợi người lớn tuổi cầm đũa/thìa lên trước rồi mới bắt đầu ăn. ㄹ đúng: khi ho phải quay mặt sang bên và che miệng — khớp với C.\nㄱ sai: bát cơm phải để trên bàn, không được cầm lên tay khi ăn (khác với văn hóa một số nước châu Á khác).\nㄷ sai: ăn phát ra tiếng to bị coi là thiếu lịch sự trong văn hóa Hàn Quốc."}, {"num": 22, "correct": "D", "stem": "한국인이 중시하는 연고에 대한 설명으로 옳은 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 지연은 같은 학교를 졸업한 사람들 사이의 인연이다.\nㄴ. 학연은 고향이 같은 사람들 사이의 인연이다.\nㄷ. 혈연은 부모, 형제 등 혈연 관계로 맺어진 인연이다.\nㄹ. 한국인은 공동체 의식과 관련된 인연을 중요하게 생각한다.", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄱ, ㄷ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "ㄷ đúng: 혈연 (huyết duyên) là nhân duyên ruột thịt. ㄹ đúng: người Hàn coi trọng các mối nhân duyên liên quan đến ý thức cộng đồng — khớp với D.\nㄱ sai: định nghĩa \"cùng trường\" thực ra là 학연 (học duyên), không phải 지연.\nㄴ sai: định nghĩa \"cùng quê\" thực ra là 지연 (địa duyên), không phải 학연 — hai khái niệm này bị đảo ngược."}, {"num": 23, "correct": "B", "stem": "한국의 종교에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "한국 사람들은 대부분 특정 종교를 가지고 있다."}, {"label": "B", "text": "개신교는 19세기에 선교사들에 의해 들어왔고 학교, 병원을 많이 설립했다."}, {"label": "C", "text": "제사를 지내는 문화는 기독교에서 유래한 것이다."}, {"label": "D", "text": "자비를 강조하는 종교는 개신교이다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Các trường như Yonsei, Ewha hay bệnh viện Severance đều do các nhà truyền giáo Tin lành (개신교) thành lập vào thế kỷ 19 — khớp với B.\nA sai: thực tế có rất nhiều người Hàn Quốc không theo tôn giáo nào.\nC sai: văn hóa cúng giỗ (제사) bắt nguồn từ Nho giáo, không phải Cơ Đốc giáo.\nD sai: tinh thần từ bi (자비) là đặc trưng của Phật giáo, không phải đạo Tin lành."}, {"num": 24, "correct": "C", "stem": "삼권분립에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "삼권분립은 입법부, 행정부, 사법부로 권력을 나누는 것이다."}, {"label": "B", "text": "국회는 법을 만드는 입법부의 역할을 한다."}, {"label": "C", "text": "대통령이 모든 권력을 가지고 다른 기관들을 견제한다."}, {"label": "D", "text": "법원은 법에 따라 재판하는 사법부의 역할을 한다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Tam quyền phân lập chia quyền lực làm 3 nhánh để kiềm chế và cân bằng lẫn nhau — Tổng thống (thuộc nhánh Hành pháp) KHÔNG nắm mọi quyền lực — nên C là câu SAI, đây là đáp án đúng.\nA, B, D đều là mô tả đúng về hệ thống tam quyền phân lập (lập pháp - hành pháp - tư pháp) của Hàn Quốc."}, {"num": 25, "correct": "B", "stem": "한국의 선거에 대한 설명으로 옳은 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 직접선거는 유권자가 대리인 없이 직접 투표하는 것이다.\nㄴ. 평등선거는 유권자마다 투표권의 수가 다르게 부여되는 것이다.\nㄷ. 비밀선거는 누구에게 투표했는지 다른 사람이 알 수 없게 하는 것이다.\nㄹ. 보통선거는 일정 재산을 가진 사람만 투표할 수 있는 것이다.", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄱ, ㄷ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "ㄱ đúng: bầu cử trực tiếp nghĩa là tự mình bỏ phiếu, không qua đại diện. ㄷ đúng: bầu cử kín nghĩa là không để người khác biết mình bầu cho ai — khớp với B.\nㄴ sai: đây thực ra là định nghĩa NGƯỢC của bầu cử bình đẳng — bình đẳng nghĩa là MỌI người có SỐ PHIẾU NGANG NHAU, không phải khác nhau.\nㄹ sai: đây là định nghĩa NGƯỢC của bầu cử phổ thông — phổ thông đầu phiếu nghĩa là KHÔNG phân biệt tài sản, ai đủ tuổi cũng được bầu."}, {"num": 26, "correct": "C", "stem": "<보기>는 한국의 시대별 수출 상품들이다.\n(가) 철강, 조선\n(나) 옷, 신발\n(다) 반도체, 휴대폰\n(라) 자동차, 전자제품\n이를 연도 순서대로 배열한 것은?", "options": [{"label": "A", "text": "(가)-(나)-(다)-(라)"}, {"label": "B", "text": "(나)-(다)-(가)-(라)"}, {"label": "C", "text": "(나)-(가)-(라)-(다)"}, {"label": "D", "text": "(다)-(라)-(가)-(나)"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Thứ tự xuất khẩu đúng theo thời gian: thập niên 1970 (나, quần áo/giày dép) → thập niên 1980 (가, thép/đóng tàu) → thập niên 1990 (라, ô tô/điện tử) → 2000 trở đi (다, bán dẫn/điện thoại) — khớp với C.\nA, B, D đều sắp xếp sai thứ tự thời gian giữa các mặt hàng."}, {"num": 27, "correct": "C", "stem": "<보기>\n(가)는 소비자가 제품의 원산지, 유통기한 등의 정보를 반드시 확인할 수 있도록 제조사가 표시해야 하는 제도이다. (나)는 소비자에게 피해를 줄 수 있는 불량품이 발견되었을 때 기업이 해당 제품을 회수하여 고치거나 교환해 주는 제도이다.\n<보기>의 (가), (나)에 해당하는 제도의 명칭으로 옳은 것은?", "options": [{"label": "A", "text": "(가) 리콜 제도 - (나) 의무표시제"}, {"label": "B", "text": "(가) 의무표시제 - (나) 원산지 표시제"}, {"label": "C", "text": "(가) 의무표시제 - (나) 리콜 제도"}, {"label": "D", "text": "(가) 품질보증제 - (나) 리콜 제도"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "(가) Bắt buộc hiển thị xuất xứ, hạn sử dụng là 의무표시제 (chế độ hiển thị bắt buộc). (나) Thu hồi/sửa chữa sản phẩm lỗi là 리콜 제도 (chế độ Recall) — khớp với C.\nA đảo ngược vị trí (가)(나). B, D thay một vị trí bằng tên chế độ khác không đúng vai trò mô tả."}, {"num": 28, "correct": "C", "stem": "<보기>\n결혼을 하는 두 사람은 주민센터나 구청에 가서 ( )를 해야 한다. ( )를 하지 않으면 재산이나 자녀 양육 등에서 법의 보호를 받을 수 없다. ( )를 하면 부부로 인정받아 법의 보호를 받을 수 있다.\n<보기>의 ( )에 공통으로 들어갈 말은?", "options": [{"label": "A", "text": "출생 신고"}, {"label": "B", "text": "이혼 신고"}, {"label": "C", "text": "혼인 신고"}, {"label": "D", "text": "전입 신고"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Thủ tục đăng ký để được pháp luật công nhận là vợ chồng gọi là \"혼인 신고\" (đăng ký kết hôn) — khớp với C. (Lưu ý: 결혼식/đám cưới chỉ là nghi lễ, không có giá trị pháp lý nếu chưa đăng ký).\nA 출생 신고(khai sinh), B 이혼 신고(khai ly hôn), D 전입 신고(khai chuyển hộ khẩu) đều là thủ tục hành chính khác, không liên quan đến việc công nhận quan hệ vợ chồng."}, {"num": 29, "correct": "D", "stem": "<보기>\n국가인권위원회\n국민권익위원회\n<보기>의 내용에 공통적으로 해당되는 것은?", "options": [{"label": "A", "text": "국가 기관의 잘못으로 피해를 입었을 때 소송을 제기할 수 있는 기관이다."}, {"label": "B", "text": "이민자가 한국 사회에 적응하도록 돕는 기관이다."}, {"label": "C", "text": "외국인을 보호하기 위한 전문 기관이다."}, {"label": "D", "text": "한국은 민주주의 국가로서 국민의 권리를 보호하기 위해 노력하고 있다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Cả hai ủy ban trên đều được lập ra với mục đích bảo vệ quyền lợi, nhân quyền của người dân khỏi sự lạm quyền/bất công — thể hiện việc \"Hàn Quốc là quốc gia dân chủ, nỗ lực bảo vệ quyền lợi người dân\" — khớp với D.\nA, B, C mỗi câu chỉ đúng với MỘT trong hai cơ quan (không phải điểm CHUNG của cả hai), nên không phải đáp án đúng cho câu hỏi \"công cộng chung cho cả hai\"."}, {"num": 30, "correct": "A", "stem": "<보기>\n한국 국민과 혼인하여 한국에 2년 이상 계속 거주하고 있는 외국인\n<보기>의 설명에 해당하는 것은?", "options": [{"label": "A", "text": "간이귀화"}, {"label": "B", "text": "일반귀화"}, {"label": "C", "text": "특별귀화"}, {"label": "D", "text": "인지"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Nhập tịch thông qua kết hôn với người Hàn Quốc chỉ yêu cầu thời gian cư trú ngắn hơn (2 năm) so với nhập tịch thông thường (5 năm) — gọi là 간이귀화 (nhập tịch giản lược/rút gọn) — khớp với A.\nB 일반귀화(nhập tịch thông thường) yêu cầu cư trú 5 năm, không cần thân nhân là người Hàn. C 특별귀화(nhập tịch đặc biệt) dành cho người có công lao đặc biệt hoặc có cha/mẹ là người Hàn. D 인지(nhận con) là thủ tục khác về quan hệ cha/mẹ - con, không liên quan hôn nhân."}, {"num": 31, "correct": "D", "stem": "나라의 이름과 나라를 건국한 사람을 바르게 연결한 것은?", "options": [{"label": "A", "text": "신라 - 단군"}, {"label": "B", "text": "발해 - 왕건"}, {"label": "C", "text": "고려 - 대조영"}, {"label": "D", "text": "조선 - 이성계"}], "correct_source": "docx", "options_source": "docx", "explanation": "Yi Seong-gye (Lý Thành Quế) là người sáng lập ra triều đại Joseon (조선) — khớp với D.\nA sai: Dangun (단군) lập ra Gojoseon, không phải Silla — Silla do Park Hyeokgeose lập.\nB sai: Wang Geon (왕건) lập ra Goryeo, không phải Balhae — Balhae do Dae Jo-yeong lập.\nC sai: Goryeo (고려) do Wang Geon lập, không phải Dae Jo-yeong."}, {"num": 32, "correct": "A", "stem": "<보기>\n· 삼국을 통일하였다\n· 삼국 중 가장 늦게 발전하였다\n<보기>에 해당하는 나라에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "유교 사상을 바탕으로 나라를 다스렸다."}, {"label": "B", "text": "화랑도를 만들어 통일의 기반이 되었다."}, {"label": "C", "text": "동양에서 가장 오래된 천문대인 첨성대를 세웠다."}, {"label": "D", "text": "석굴암, 불국사 등 불교 문화가 크게 발전했다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Nước cai trị dựa trên tư tưởng Nho giáo là Joseon (조선), không phải Silla — Silla chủ yếu sùng bái Phật giáo — nên A là câu SAI, đây là đáp án đúng.\nB, C, D đều là thành tựu/đặc điểm có thật của Silla: tổ chức Hwarangdo làm nền tảng thống nhất Tam Quốc, xây đài thiên văn cổ nhất phương Đông (Cheomseongdae), và văn hóa Phật giáo phát triển mạnh (Seokguram, Bulguksa)."}, {"num": 33, "correct": "A", "stem": "한국의 역사적인 인물에 대한 설명으로 옳은 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 서희는 싸우지 않고 외교로 전쟁을 막았다.\nㄴ. 허난설헌은 1919년 3.1운동에 참여하였다.\nㄷ. 이순신 장군은 거북선을 만들어서 일본군을 물리쳤다.\nㄹ. 김만덕은 제주도에 심한 흉년이 들었을 때 이 사실을 왕에게 알렸다.", "options": [{"label": "A", "text": "ㄱ, ㄷ"}, {"label": "B", "text": "ㄱ, ㄴ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "ㄱ đúng: Seo Hui dùng ngoại giao ngăn chặn chiến tranh, không cần giao tranh. ㄷ đúng: tướng Yi Sun-sin chế tạo thuyền rùa (거북선) đánh bại quân Nhật — khớp với A.\nㄴ sai: Heo Nanseolheon là nữ thi sĩ thời Joseon (thế kỷ 16), không thể tham gia phong trào 1/3 năm 1919 (cách nhau hơn 300 năm) — người nổi tiếng tham gia phong trào đó là Yu Gwan-sun (유관순).\nㄹ sai: Kim Man-deok là nữ thương gia dùng chính tài sản của mình mua gạo cứu đói cho dân Jeju khi mất mùa, không phải người \"báo tin cho vua\"."}, {"num": 34, "correct": "D", "stem": "<보기>\n· 2018년 평창 동계 올림픽을 개최하였다\n· 설악산, 경포대, 낙산해수욕장이 있다\n<보기>와 관련된 지역에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "산이 많아 고랭지 농업과 축산업이 발달했다."}, {"label": "B", "text": "강릉 단오제와 대관령 눈꽃 축제가 열린다."}, {"label": "C", "text": "태백산맥을 기준으로 영동과 영서로 나뉜다."}, {"label": "D", "text": "과학 도시가 만들어져서 사이언스 페스티벌이 열리고 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Thành phố khoa học (과학 도시) nổi tiếng của Hàn Quốc là Daejeon, thuộc vùng Chungcheong, không phải Gangwon — nên D là câu SAI, đây là đáp án đúng.\nA, B, C đều là đặc điểm có thật của vùng Gangwon: nhiều núi nên phát triển nông nghiệp vùng cao/chăn nuôi, có lễ hội Danoje ở Gangneung và lễ hội tuyết Daegwallyeong, và được chia thành Yeongdong/Yeongseo theo dãy núi Taebaek."}, {"num": 35, "correct": "B", "stem": "다음 중 각 지역의 축제에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "경상지역에서는 안동 탈춤 축제가 열린다."}, {"label": "B", "text": "전라지역의 대표적인 축제로 세계 도자기 엑스포를 들 수 있다."}, {"label": "C", "text": "충청지역에서는 보령 머드 축제와 백제 문화제가 열린다."}, {"label": "D", "text": "서울에서는 등불 축제와 거리 예술 축제가 열린다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Lễ hội Gốm sứ Thế giới (세계 도자기 엑스포) được tổ chức tại Icheon, Gwangju, Yeoju — thuộc vùng Gyeonggi (경기도), không phải Jeolla — nên B là câu SAI, đây là đáp án đúng.\nA, C, D đều là mô tả đúng: lễ hội múa mặt nạ Andong (Gyeongsang), lễ hội bùn Boryeong + văn hóa Baekje (Chungcheong), lễ hội đèn lồng + nghệ thuật đường phố (Seoul)."}, {"num": 36, "correct": "C", "stem": "<보기>\n(가) 사람들이 단풍을 구경하러 많이 간다\n(나) 폭설과 같은 자연재해가 발생하기도 한다\n(가), (나)에서 설명하는 계절의 현상에 알맞은 날씨는?", "options": [{"label": "A", "text": "(가) 따뜻하고 습한 날씨 - (나) 덥고 습한 날씨"}, {"label": "B", "text": "(가) 덥고 습한 날씨 - (나) 춥고 습한 날씨"}, {"label": "C", "text": "(가) 화창하고 건조한 날씨 - (나) 춥고 건조한 날씨"}, {"label": "D", "text": "(가) 따뜻하고 건조한 날씨 - (나) 덥고 습한 날씨"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Mùa Thu (가) ở Hàn Quốc: thời tiết trong xanh và hanh khô (화창하고 건조하다). Mùa Đông (나): thời tiết lạnh và hanh khô (춥고 건조하다) — khớp với C.\nB sai đặc biệt vì mùa đông Hàn Quốc thực chất rất KHÔ chứ không ẩm. A và D mô tả sai mùa/sai đặc điểm nhiệt độ so với 2 hiện tượng \"ngắm lá đỏ\" và \"bão tuyết\" đã cho."}], "tables": []}, "round1": {"title": "Mô phỏng KIIP cấp 5 - 5단계 1회", "source": "한국어_모의고사_(5단계_1회)_—_Giải_thích_chi_tiết.docx", "questions": [{"num": 1, "correct": "B", "stem": "우리 아이는 ( )이라서 혼자 조용히 있는 것을 좋아한다.", "options": [{"label": "A", "text": "긍정적"}, {"label": "B", "text": "내성적"}, {"label": "C", "text": "외향적"}, {"label": "D", "text": "적극적"}], "correct_source": "docx", "options_source": "docx", "explanation": "Người thích ở một mình yên tĩnh là người có tính cách hướng nội (내성적) — khớp với B.\nA 긍정적(tích cực), C 외향적(hướng ngoại — trái nghĩa hoàn toàn), D 적극적(chủ động) đều không hợp với \"thích ở một mình yên tĩnh\"."}, {"num": 2, "correct": "B", "stem": "싱크대가 ( ) 물이 안 내려가요.", "options": [{"label": "A", "text": "새서"}, {"label": "B", "text": "막혀서"}, {"label": "C", "text": "열려서"}, {"label": "D", "text": "쌓여서"}], "correct_source": "docx", "options_source": "docx", "explanation": "Nước bồn rửa bát không chảy xuống được là do bị TẮC (막히다) — khớp với B.\nA 새서(vì bị rò rỉ) thì nước sẽ CHẢY RA ngoài chứ không phải không chảy xuống được. C 열려서(vì bị mở) và D 쌓여서(vì bị tích tụ) đều không hợp nghĩa \"nước không thoát được\"."}, {"num": 3, "correct": "B", "stem": "연말에는 한 해를 돌아보며 회사 동료들이나 가족들과 모여서 ( )를 한다.", "options": [{"label": "A", "text": "동창회"}, {"label": "B", "text": "송년회"}, {"label": "C", "text": "반상회"}, {"label": "D", "text": "야유회"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cuối năm (연말) nhìn lại một năm đã qua chính là ý nghĩa của tiệc tất niên (송년회) — khớp với B.\nA 동창회(họp lớp cũ), C 반상회(họp tổ dân phố), D 야유회(dã ngoại) đều không gắn với dịp cuối năm được nêu."}, {"num": 4, "correct": "C", "stem": "나는 시간이 있으면 예쁜 풍경 사진을 찍어서 블로그에 ( ).", "options": [{"label": "A", "text": "내린다"}, {"label": "B", "text": "지운다"}, {"label": "C", "text": "올린다"}, {"label": "D", "text": "숨긴다"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "\"블로그에 올리다\" nghĩa là đăng bài/ảnh lên blog — khớp với C.\nA 내린다(tải xuống/hạ xuống) mang nghĩa ngược lại. B 지운다(xóa) và D 숨긴다(giấu đi) đều không hợp với hành động chụp ảnh đẹp rồi CHIA SẺ lên blog."}, {"num": 5, "correct": "B", "stem": "가: 머리를 어떻게 해 드릴까요?\n나: 여름이니까 좀 ( ) 잘라 주세요.", "options": [{"label": "A", "text": "길게"}, {"label": "B", "text": "짧게"}, {"label": "C", "text": "예쁘게"}, {"label": "D", "text": "이상하게"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "\"짧게 자르다\" (cắt ngắn) hợp lý vì trời đang mùa hè nóng nực — khớp với B. \"-게\" ở đây tạo phó từ chỉ cách thức cắt tóc.\nA 길게(dài) mang nghĩa ngược lại với lý do \"mùa hè\". C 예쁘게(đẹp) và D 이상하게(kỳ lạ) không liên quan đến lý do thời tiết được nêu."}, {"num": 6, "correct": "A", "stem": "가: 어릴 때 어떤 음식을 좋아했어요?\n나: 초콜릿과 같은 단 음식을 자주 ( ).", "options": [{"label": "A", "text": "먹곤 했어요"}, {"label": "B", "text": "먹기 마련이에요"}, {"label": "C", "text": "먹으려던 참이에요"}, {"label": "D", "text": "먹었을지도 몰라요"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cấu trúc \"-곤 하다\" diễn tả một thói quen lặp lại trong quá khứ — \"hồi nhỏ hay ăn đồ ngọt\" — khớp với A.\nB 먹기 마련이에요(đương nhiên là ăn — quy luật chung, không phải hồi tưởng thói quen cá nhân), C 먹으려던 참이에요(vừa định ăn — thì không khớp), D 먹었을지도 몰라요(không biết chừng đã ăn — phỏng đoán, không hợp câu hỏi về thói quen đã biết rõ) đều sai."}, {"num": 7, "correct": "D", "stem": "가: 의사 선생님께서 뭐라고 하셨어요?\n나: 감기가 심하니까 약을 먹고 푹 ( ) 하셨어요.", "options": [{"label": "A", "text": "쉰다고"}, {"label": "B", "text": "쉬냐고"}, {"label": "C", "text": "쉬었다고"}, {"label": "D", "text": "쉬라고"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Câu trần thuật gián tiếp của câu MỆNH LỆNH: bác sĩ bảo \"쉬세요\" (hãy nghỉ ngơi) → \"쉬라고 하셨다\" — khớp với D.\nA 쉰다고(nói là sẽ nghỉ) và C 쉬었다고(nói là đã nghỉ) là câu gián tiếp của câu TRẦN THUẬT, không phải mệnh lệnh. B 쉬냐고(hỏi là có nghỉ không) là câu gián tiếp của câu HỎI — cả 3 đều sai vì bác sĩ đang RA CHỈ THỊ, không phải kể chuyện hay hỏi."}, {"num": 8, "correct": "D", "stem": "가: 어제 본 영화는 어땠어요?\n나: 너무 재미있어서 배꼽이 ( ) 웃었어요.", "options": [{"label": "A", "text": "빠지지 않게"}, {"label": "B", "text": "빠질까 봐"}, {"label": "C", "text": "빠지는 대신"}, {"label": "D", "text": "빠질 정도로"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Quán dụng ngữ \"배꼽이 빠지다\" chỉ việc cười rất to — \"cười đến mức rớt rốn\" dùng cấu trúc \"-ㄹ 정도로\" (đến mức...) — khớp với D.\nA 빠지지 않게(để không rớt), B 빠질까 봐(sợ sẽ rớt), C 빠지는 대신(thay vì rớt) đều không diễn tả đúng mức độ cười to mà câu cần."}, {"num": 9, "correct": "B", "stem": "친구가 기다리고 있어서 수업이 끝나자마자 ( ).", "options": [{"label": "A", "text": "천천히 가도 돼요"}, {"label": "B", "text": "빨리 가야 돼요"}, {"label": "C", "text": "가지 않아도 돼요"}, {"label": "D", "text": "가면 안 돼요"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Bạn đang đợi nên ngay khi tan học (끝나자마자) thì \"phải\" đi nhanh — khớp với B.\nA 천천히 가도 돼요(có thể đi từ từ) mang nghĩa ngược lại với việc bạn đang chờ. C 가지 않아도 돼요(không cần đi cũng được) và D 가면 안 돼요(không được đi) đều mâu thuẫn với lý do \"bạn đang đợi\"."}, {"num": 10, "correct": "A", "stem": "극장 앞에 사람이 많은 걸 보니 ( ).", "options": [{"label": "A", "text": "저 영화가 재미있나 봐요"}, {"label": "B", "text": "저 영화가 재미없을 리가 없어요"}, {"label": "C", "text": "저 영화를 꼭 봐야 해요"}, {"label": "D", "text": "저 영화가 곧 끝날 거예요"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Cấu trúc \"-나 보다\" dùng để phỏng đoán dựa trên điều nhìn thấy — thấy rạp đông người nên suy đoán \"có vẻ phim đó hay\" — khớp với A.\nB \"-ㄹ 리가 없다\"(không thể nào) là cấu trúc khẳng định chắc chắn, không hợp với ngữ cảnh phỏng đoán nhẹ nhàng. C(nhất định phải xem) và D(sắp kết thúc) không diễn tả đúng ý suy đoán từ hiện tượng quan sát được."}, {"num": 11, "correct": "A", "stem": "대기업에 지원하다 / 열심히 준비하고 있다", "options": [{"label": "A", "text": "대기업에 지원하기 위해서 열심히 준비하고 있어요."}, {"label": "B", "text": "대기업에 지원하는 대신에 열심히 준비하고 있어요."}, {"label": "C", "text": "대기업에 지원하다가 열심히 준비하고 있어요."}, {"label": "D", "text": "대기업에 지원하도록 열심히 준비하고 있어요."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Nối 2 vế bằng cấu trúc chỉ mục đích \"-기 위해서\" (để...) — \"đang chuẩn bị chăm chỉ ĐỂ ứng tuyển vào công ty lớn\" — khớp với A.\nB \"-는 대신에\"(thay vì) sai quan hệ mục đích. C \"-다가\"(đang làm thì bị ngắt) sai ngữ pháp/nghĩa. D \"-도록\"(để cho) không hợp chủ thể của câu."}, {"num": 12, "correct": "C", "stem": "주말에 근무하다 / 평일에 쉬다 / 괜찮다", "options": [{"label": "A", "text": "주말에 근무하기 위해서 평일에 쉬니까 괜찮다."}, {"label": "B", "text": "주말에 근무하지만 평일에 쉬어도 괜찮다."}, {"label": "C", "text": "주말에 근무하는 대신에 평일에 쉬니까 괜찮다."}, {"label": "D", "text": "주말에 근무하도록 평일에 쉬니까 괜찮다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Cấu trúc \"-는 대신에\" (thay vì, bù lại) — bù lại việc phải làm cuối tuần là được nghỉ ngày thường, nên ổn — khớp với C.\nA \"-기 위해서\"(để) sai quan hệ nhân quả/mục đích. B đổi cấu trúc thành \"-지만\"(nhưng) làm mất đi ý nghĩa \"bù lại\". D \"-도록\"(để cho) sai nghĩa."}, {"num": 13, "correct": "B", "stem": "요즘 사람들은 휴대폰 속에 저장된 사람이 너무 많아서 오히려 스트레스를 받는다고 한다. 그래서 자주 연락하지 않거나 불편한 관계는 정리하는 사람들이 늘고 있다. 이런 \"인맥 다이어트\"는 ( ).", "options": [{"label": "A", "text": "새로운 친구를 많이 사귀는 것을 의미하는"}, {"label": "B", "text": "관계를 정리하는 것을 의미하는"}, {"label": "C", "text": "다른 사람과 연락을 완전히 끊는 것을 의미하는"}, {"label": "D", "text": "인맥을 넓히기 위해 노력하는 것을 의미하는"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Đoạn văn nói về \"인맥 다이어트\" (diet mối quan hệ) — tức cắt giảm, sắp xếp lại các mối quan hệ không cần thiết để tránh áp lực — khớp với B \"có ý nghĩa là sắp xếp lại các mối quan hệ\".\nA(kết bạn mới nhiều) và D(nỗ lực mở rộng mối quan hệ) đều mang nghĩa ngược lại (mở rộng thay vì thu gọn). C(cắt đứt liên lạc hoàn toàn) đi quá xa so với ý \"sắp xếp lại\" — dọn dẹp có chọn lọc, không phải cắt đứt tất cả."}, {"num": 14, "correct": "B", "stem": "[구인 광고]\n모집 분야: 주방 보조\n근무 시간: 09:00 ~ 18:00\n접수 방법: 방문 접수\n\n다음 구인 광고를 보고 알 수 없는 것은?", "options": [{"label": "A", "text": "채용 직종"}, {"label": "B", "text": "온라인 접수 방법"}, {"label": "C", "text": "근무 시간"}, {"label": "D", "text": "접수 방법"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Quảng cáo ghi rõ cách thức nộp hồ sơ là \"방문 접수\" (đến nộp trực tiếp) — không hề đề cập đến việc nộp hồ sơ online, nên đây là thông tin KHÔNG thể biết được — khớp với B.\nA(ngành nghề tuyển), C(giờ làm việc), D(cách nộp hồ sơ trực tiếp) đều là thông tin CÓ trong quảng cáo."}, {"num": 15, "correct": "B", "stem": "세계화 시대에는 외국어 능력뿐만 아니라 다른 나라의 문화를 이해하고 존중하는 태도, 그리고 폭넓은 기초 지식이 함께 필요하다. 이 세 가지를 고루 갖추어야 국제 사회에서 다양한 사람들과 원활하게 소통하고 협력할 수 있다.\n윗글의 제목으로 가장 알맞은 것을 고르시오.", "options": [{"label": "A", "text": "외국어를 배우는 방법"}, {"label": "B", "text": "국제화 시대에 필요한 능력"}, {"label": "C", "text": "다른 나라 문화를 소개하는 방법"}, {"label": "D", "text": "해외 여행을 준비하는 방법"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Đoạn văn bao quát nhiều năng lực cần thiết (ngoại ngữ, tôn trọng văn hóa, kiến thức nền) trong bối cảnh toàn cầu hóa — tiêu đề bao quát nhất là B.\nA chỉ nói về một phần (ngoại ngữ), C và D đều không khớp trọng tâm bài — cả hai đều là chủ đề hẹp/khác với nội dung chính."}, {"num": 16, "correct": "C", "stem": "세계화 시대에는 외국어 능력뿐만 아니라 다른 나라의 문화를 이해하고 존중하는 태도, 그리고 폭넓은 기초 지식이 함께 필요하다. 다른 문화에 대한 편견을 없애려면 어릴 때부터 ( ). 그래야 서로 다른 문화를 자연스럽게 받아들이고 존중할 수 있다.\n윗글의 ( )에 들어갈 내용으로 알맞은 것을 고르시오.", "options": [{"label": "A", "text": "외국어를 유창하게 구사해야 한다"}, {"label": "B", "text": "다른 나라 역사를 암기해야 한다"}, {"label": "C", "text": "다양한 문화를 경험해야 한다"}, {"label": "D", "text": "국제 기구에서 일해야 한다"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Để loại bỏ định kiến và tôn trọng văn hóa lẫn nhau, giáo dục từ nhỏ cần giúp trẻ \"trải nghiệm văn hóa đa dạng\" — khớp với C.\nA(nói ngoại ngữ trôi chảy), B(học thuộc lịch sử nước khác), D(làm việc ở tổ chức quốc tế) đều không trực tiếp giải quyết vấn đề \"định kiến văn hóa\" mà đoạn văn nhấn mạnh."}, {"num": 17, "correct": "D", "stem": "한국 도시의 문제점으로 맞는 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 일할 사람이 부족하다.\nㄴ. 의료 시설이 부족하다.\nㄷ. 집값이 올라 주택이 부족하다.\nㄹ. 환경 오염이 심각하다.", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄱ, ㄷ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Vấn đề của ĐÔ THỊ là (ㄷ) giá nhà tăng, thiếu nhà ở và (ㄹ) ô nhiễm môi trường — khớp với D.\n(ㄱ) thiếu lao động và (ㄴ) thiếu cơ sở y tế thực ra là vấn đề của NÔNG THÔN, không phải đô thị."}, {"num": 18, "correct": "B", "stem": "한국의 가족에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "산업화 이후 핵가족의 비율이 크게 늘어났다."}, {"label": "B", "text": "산업화가 진행되면서 부모와 함께 사는 가족이 늘고 있다."}, {"label": "C", "text": "1인 가구의 수가 계속 증가하는 추세이다."}, {"label": "D", "text": "맞벌이 부부가 늘어나면서 가족의 형태도 다양해지고 있다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Công nghiệp hóa làm tăng tỷ lệ \"gia đình hạt nhân\" (핵가족) và làm GIẢM số gia đình nhiều thế hệ sống chung (확대가족/gia đình mở rộng) — nên B (\"gia đình sống chung với bố mẹ đang tăng\") là câu SAI, đây là đáp án đúng.\nA, C, D đều là xu hướng thực tế đúng về sự thay đổi cấu trúc gia đình Hàn Quốc."}, {"num": 19, "correct": "D", "stem": "한국에서 태극기를 달아야 하는 국경일에 해당하는 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 설날\nㄴ. 어버이날\nㄷ. 광복절\nㄹ. 제헌절\nㅁ. 한글날\nㅂ. 크리스마스", "options": [{"label": "A", "text": "ㄱ, ㄴ, ㅂ"}, {"label": "B", "text": "ㄷ, ㄹ, ㅂ"}, {"label": "C", "text": "ㄴ, ㄷ, ㅁ"}, {"label": "D", "text": "ㄷ, ㄹ, ㅁ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "5 ngày lễ quốc gia (국경일) bắt buộc treo quốc kỳ là: 3.1절, 제헌절(ㄹ), 광복절(ㄷ), 개천절, 한글날(ㅁ) — trong <보기> này có ㄷ, ㄹ, ㅁ thuộc nhóm đó — khớp với D.\nㄱ 설날(Tết Nguyên đán), ㄴ 어버이날(Ngày Cha mẹ), ㅂ 크리스마스(Giáng sinh) đều là ngày lễ/kỷ niệm nhưng KHÔNG phải quốc khánh (국경일) yêu cầu treo cờ."}, {"num": 20, "correct": "D", "stem": "한국의 보육제도에 대한 설명 중 옳은 것은?", "options": [{"label": "A", "text": "유치원은 보건복지부 소속 기관이다."}, {"label": "B", "text": "아동수당은 만 5세 미만 아동만 받을 수 있다."}, {"label": "C", "text": "집에서 아이를 직접 키우면 보육 지원을 받을 수 없다."}, {"label": "D", "text": "어린이집은 만 0세부터 만 5세까지의 보육과 교육을 담당한다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Nhà trẻ (어린이집) nhận và chăm sóc/giáo dục trẻ từ 0 đến 5 tuổi — khớp với D.\nA sai: mẫu giáo (유치원) thuộc Bộ Giáo dục, không phải Bộ Y tế Phúc lợi.\nB sai: trợ cấp trẻ em (아동수당) dành cho trẻ dưới 8 tuổi, không phải chỉ dưới 5 tuổi.\nC sai: gia đình tự nuôi con tại nhà vẫn được nhận trợ cấp nuôi con tại nhà (가정양육수당)."}, {"num": 21, "correct": "A", "stem": "한국의 초·중등 교육기관에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "한국에서는 만 7세부터 초등학교에 입학할 수 있다."}, {"label": "B", "text": "초등학교와 중학교는 의무 교육에 해당한다."}, {"label": "C", "text": "중학교는 3년제로 운영된다."}, {"label": "D", "text": "고등학교부터는 의무 교육이 아니다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Ở Hàn Quốc, trẻ em nhập học tiểu học khi đủ 6 tuổi (만 6세), không phải 7 tuổi — nên A là câu SAI, đây là đáp án đúng.\nB, C, D đều là mô tả đúng về hệ thống giáo dục tiểu học/THCS/THPT Hàn Quốc."}, {"num": 22, "correct": "C", "stem": "<보기>\n· 사회통합프로그램\n· 한국 생활에 빨리 적응할 수 있도록 도와줌\n<보기>의 내용을 통해 알 수 있는 것으로 가장 적절한 것은?", "options": [{"label": "A", "text": "외국인 근로자의 취업을 알선하기 위한 제도이다."}, {"label": "B", "text": "다문화 가정의 자녀 교육만을 위한 제도이다."}, {"label": "C", "text": "이주민들의 적응과 정착을 지원하기 위한 프로그램이다."}, {"label": "D", "text": "귀화 시험에 합격한 사람에게 주는 혜택이다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Đây là chương trình nhằm hỗ trợ sự thích ứng và định cư của người di trú/nhập cư tại Hàn Quốc — khớp với C.\nA(giới thiệu việc làm) chỉ là một khía cạnh hẹp; B(chỉ dành cho giáo dục con em gia đình đa văn hóa) và D(chỉ dành cho người đã đỗ thi nhập tịch) đều thu hẹp phạm vi sai so với mục đích thực tế của chương trình."}, {"num": 23, "correct": "C", "stem": "<보기>\n설날\n<보기>에 해당하는 한국의 명절에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "세배를 하고 어른들께 새해 인사를 드린다."}, {"label": "B", "text": "떡국을 먹으면서 나이를 한 살 더 먹는다고 생각한다."}, {"label": "C", "text": "일반적으로 이날 전에 미리 조상의 묘지를 벌초한다."}, {"label": "D", "text": "윷놀이와 같은 전통 놀이를 즐긴다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Việc cắt cỏ mộ (벌초) thường được thực hiện trước dịp Chuseok (Trung thu), không phải trước Seollal (Tết Nguyên đán) — nên C là câu SAI, đây là đáp án đúng.\nA, B, D đều là phong tục đúng của Tết Nguyên đán: làm lễ chào năm mới (세배), ăn tteokguk (được coi là thêm 1 tuổi), và chơi trò chơi truyền thống như Yutnori."}, {"num": 24, "correct": "B", "stem": "한옥에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "온돌은 여름에 시원하게 지내기 위한 장치였다."}, {"label": "B", "text": "햇볕이 잘 들어오도록 남쪽으로 바라보고 지은 집을 선호했다."}, {"label": "C", "text": "풍수지리상 좋은 집터는 물을 등지고 산을 바라보는 곳이다."}, {"label": "D", "text": "신분에 관계없이 누구나 기와집에서 살 수 있었다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Người Hàn xưa thích xây nhà hướng Nam (남향) để đón nhiều ánh nắng — khớp với B.\nA sai: Ondol (온돌) là hệ thống SƯỞI cho mùa đông, còn Daecheongmaru (대청마루) mới là nơi làm mát mùa hè — câu này bị đảo ngược vai trò.\nC sai: theo phong thủy, đất tốt là \"lưng tựa núi, mặt hướng sông/nước\" (배산임수) — câu này mô tả ngược lại.\nD sai: chỉ quý tộc mới ở nhà ngói (기와집), thường dân ở nhà mái rạ (초가집), không phải ai cũng ở được nhà ngói."}, {"num": 25, "correct": "B", "stem": "한국인이 가장 많이 참여하는 여가 활동인 휴식 활동에 해당하지 않는 것은?", "options": [{"label": "A", "text": "텔레비전 시청"}, {"label": "B", "text": "쇼핑"}, {"label": "C", "text": "낮잠 자기"}, {"label": "D", "text": "산책하기"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Theo khảo sát KIIP, các hoạt động \"nghỉ ngơi\" phổ biến nhất là xem TV, ngủ trưa, đi dạo — mua sắm (쇼핑) thuộc nhóm hoạt động khác (mua sắm/tiêu dùng), không thuộc nhóm \"nghỉ ngơi thư giãn\" — khớp với B.\nA, C, D đều là các hoạt động nghỉ ngơi phổ biến nhất theo khảo sát."}, {"num": 26, "correct": "A", "stem": "<보기>: Chủ quyền thuộc về..., mọi quyền lực xuất phát từ...\n<보기>의 ( )에 공통으로 들어갈 말은?", "options": [{"label": "A", "text": "국민"}, {"label": "B", "text": "대통령"}, {"label": "C", "text": "국회"}, {"label": "D", "text": "법원"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Điều 1 Hiến pháp Hàn Quốc quy định: chủ quyền quốc gia thuộc về nhân dân (국민), mọi quyền lực nhà nước xuất phát từ nhân dân — khớp với A.\nB 대통령(Tổng thống), C 국회(Quốc hội), D 법원(Tòa án) đều là các CƠ QUAN thực thi quyền lực do nhân dân trao cho, không phải nguồn gốc của chủ quyền."}, {"num": 27, "correct": "D", "stem": "다음 중 입법부에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "법에 따라 재판을 진행한다."}, {"label": "B", "text": "국가의 정책을 집행하고 행정 업무를 담당한다."}, {"label": "C", "text": "대통령을 선출하고 국무총리를 임명한다."}, {"label": "D", "text": "국정 감사를 실시하여 행정부를 견제하고 감시한다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Quốc hội (nhánh Lập pháp) có quyền giám sát Chính phủ (nhánh Hành pháp) thông qua hoạt động Thanh tra Quốc chính (국정 감사) — khớp với D.\nA(xét xử theo pháp luật) là vai trò của Tư pháp. B(thực thi chính sách, hành chính) là vai trò của Hành pháp. C(bầu tổng thống, bổ nhiệm thủ tướng) không đúng với cách thức hoạt động thực tế của Quốc hội Hàn Quốc."}, {"num": 28, "correct": "B", "stem": "한국의 일자리 상황에 대한 설명으로 옳은 것을 <보기>에서 모두 고른 것은?\n<보기>\nㄱ. 한국의 실업률은 미국이나 유럽보다 높은 편이다.\nㄴ. 비정규직 근로자의 비율이 늘어나고 있다.\nㄷ. 여성의 경제 활동 참가율은 선진국에 비해 낮은 편이다.\nㄹ. 사회 보장 제도가 선진국 수준으로 잘 갖춰져 있다.", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄴ, ㄷ"}, {"label": "C", "text": "ㄴ, ㄹ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "ㄴ đúng: tỷ trọng lao động không chính thức (비정규직) đang tăng. ㄷ đúng: tỷ lệ tham gia kinh tế của phụ nữ Hàn Quốc thấp hơn các nước phát triển — khớp với B.\nㄱ sai: tỷ lệ thất nghiệp thực tế của Hàn Quốc thấp hơn Mỹ/châu Âu, không phải cao hơn.\nㄹ sai: chế độ an sinh xã hội của Hàn Quốc chưa đạt trình độ các nước phát triển."}, {"num": 29, "correct": "A", "stem": "개발원조위원회 회원국이면서 다른 나라로부터 원조를 받던 나라에서 원조를 주는 나라로 바뀐 첫 번째 사례로 꼽히는 나라는?", "options": [{"label": "A", "text": "한국"}, {"label": "B", "text": "미국"}, {"label": "C", "text": "일본"}, {"label": "D", "text": "중국"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Hàn Quốc là quốc gia đầu tiên trên thế giới chuyển từ vị thế \"nước nhận viện trợ\" (sau chiến tranh) sang \"nước đi viện trợ\" khi trở thành thành viên Ủy ban Hỗ trợ Phát triển (DAC) — khớp với A.\nB, C, D đều không phải là ví dụ điển hình được nêu trong tài liệu KIIP cho trường hợp chuyển đổi này."}, {"num": 30, "correct": "C", "stem": "대한민국에서 외국인의 기본적인 지위와 권리를 보장해 주는 기준이 되는 것은?", "options": [{"label": "A", "text": "관습법"}, {"label": "B", "text": "헌법"}, {"label": "C", "text": "국제법"}, {"label": "D", "text": "민법"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Các điều ước quốc tế (국제법) mà Hàn Quốc đã ký kết có hiệu lực như luật trong nước, nên đáp án phù hợp là C.\nA 관습법 (luật tập quán) và D 민법 (luật dân sự) không phải là căn cứ pháp lý chính cho vấn đề này."}, {"num": 31, "correct": "A", "stem": "<보기>\n돈을 빌려줄 때는 (가)를 받아 두고, 돈을 갚을 때는 갚았다는 것을 증명할 수 있는 (나)를 받아 두는 것이 좋다.\n<보기>의 (가), (나)에 들어갈 말로 알맞은 것은?", "options": [{"label": "A", "text": "차용증 - 영수증"}, {"label": "B", "text": "영수증 - 차용증"}, {"label": "C", "text": "차용증 - 계약서"}, {"label": "D", "text": "청구서 - 영수증"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "(가) Giấy vay nợ (차용증) — nhận từ người vay khi cho vay tiền, để chứng minh khoản vay. (나) Biên lai/giấy biên nhận (영수증) — nhận khi trả tiền, để chứng minh đã thanh toán — khớp với A.\nB đảo ngược vị trí (가)(나). C, D thay một vị trí bằng giấy tờ khác không đúng vai trò được mô tả."}, {"num": 32, "correct": "D", "stem": "고려의 왕건에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "궁예와 함께 나라 이름을 고려로 바꾸었다."}, {"label": "B", "text": "고조선을 계승하여 나라를 세웠다."}, {"label": "C", "text": "후백제를 먼저 공격한 후 신라를 통일했다."}, {"label": "D", "text": "백성의 생활을 안정시키려고 세금을 10% 이상 거두지 못하게 했다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Vua Taejo Wang Geon (Thái Tổ Vương Kiến) đã ban hành chính sách giảm thuế xuống còn khoảng 1/10 để ổn định đời sống bách tính — khớp với D.\nA sai: Wang Geon LẬT ĐỔ Gung Ye rồi mới đổi tên nước thành Goryeo, không phải \"cùng\" Gung Ye đổi tên.\nB sai: Goryeo kế thừa tinh thần Goguryeo, không phải Gojoseon.\nC sai: thực tế Silla tự nguyện đầu hàng trước, sau đó Goryeo mới tấn công và diệt Hậu Baekje — không phải tấn công Hậu Baekje rồi mới thống nhất Silla."}, {"num": 33, "correct": "B", "stem": "<보기>의 내용 중 세종대왕에 대한 설명으로 옳은 것을 모두 고른 것은?\n<보기>\nㄱ. 한글을 창제하였다.\nㄴ. 거북선을 만들어 일본군을 물리쳤다.\nㄷ. 경국대전을 편찬하였다.\nㄹ. 측우기 등 과학 기술을 발전시켜 농업을 도왔다.", "options": [{"label": "A", "text": "ㄱ, ㄴ"}, {"label": "B", "text": "ㄱ, ㄹ"}, {"label": "C", "text": "ㄴ, ㄷ"}, {"label": "D", "text": "ㄷ, ㄹ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "ㄱ đúng: vua Sejong sáng tạo ra chữ Hangeul. ㄹ đúng: ông phát triển khoa học kỹ thuật (như máy đo lượng mưa 측우기) giúp ích cho nông nghiệp — khớp với B.\nㄴ sai: thuyền rùa (거북선) là phát minh của tướng Yi Sun-sin (thời Joseon sau này), không phải vua Sejong.\nㄷ sai: Bộ luật Gyeongguk Daejeon (경국대전) được biên soạn dưới thời vua Seongjong, không phải vua Sejong."}, {"num": 34, "correct": "C", "stem": "<보기>\n· 부석사\n· 석굴암, 불국사\n· 도산서원, 하회마을\n<보기>에 해당하는 지역에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "창녕에 우포늪이라는 습지가 있다."}, {"label": "B", "text": "대구, 울산, 부산과 같은 도시를 포함한다."}, {"label": "C", "text": "이 지역은 한국의 중앙부 동쪽에 위치하고 있으며 눈이 많이 온다."}, {"label": "D", "text": "충무공 이순신을 기리는 한산대첩 축제가 통영에서 열린다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Vùng nằm ở phía Đông miền Trung và có nhiều tuyết thực ra là Gangwon (강원도), không phải Gyeongsang (nằm ở phía Đông NAM) — nên C là câu SAI, đây là đáp án đúng.\nA, B, D đều là đặc điểm có thật của vùng Gyeongsang: có đầm lầy Upo ở Changnyeong, bao gồm các thành phố lớn như Daegu/Ulsan/Busan, và có lễ hội Hansan Daecheop tại Tongyeong kỷ niệm tướng Yi Sun-sin."}, {"num": 35, "correct": "B", "stem": "<보기>\n(가)는 옛날에는 작은 포구였지만 지금은 국제 무역이 활발한 큰 항구 도시로 성장했다. (나) 공항은 한국에서 가장 큰 국제공항이다.\n<보기>의 (가), (나)에 들어갈 말로 알맞은 것은?", "options": [{"label": "A", "text": "제물포 - 김포국제공항"}, {"label": "B", "text": "제물포 - 인천국제공항"}, {"label": "C", "text": "부산포 - 인천국제공항"}, {"label": "D", "text": "목포 - 김해국제공항"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Cảng Incheon ngày xưa có tên là Jemulpo (제물포), nay đã phát triển thành thành phố cảng lớn. Sân bay lớn nhất Hàn Quốc là Sân bay Quốc tế Incheon (인천국제공항) — khớp với B.\nA thay sân bay bằng Gimpo (sân bay nội địa/khu vực Seoul, không phải lớn nhất). C, D thay cả tên cảng bằng địa danh khác không đúng."}, {"num": 36, "correct": "D", "stem": "충청지역에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "단양팔경이라는 8개의 명소가 있다."}, {"label": "B", "text": "대전에서는 과학과 문화가 결합된 사이언스 페스티벌이 열린다."}, {"label": "C", "text": "보령 머드 축제가 유명하다."}, {"label": "D", "text": "백제 문화제는 청주와 충주에서 매년 개최되는 역사·문화 축제이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Lễ hội Văn hóa Baekje (백제 문화제) thực ra được tổ chức tại Buyeo (부여) và Gongju (공주) — vốn là cố đô của Baekje — không phải Cheongju và Chungju — nên D là câu SAI, đây là đáp án đúng.\nA, B, C đều là đặc điểm có thật của vùng Chungcheong: Danyang Palgyeong (8 danh thắng ở Danyang), Lễ hội Khoa học Daejeon, và Lễ hội Bùn Boryeong nổi tiếng."}], "tables": []}, "geo8": {"title": "Ôn tập Địa lý - 5단계 bài 8", "source": "5단계_8-지리_종합평가_기출문제_—_Giải_thích_chi_tiết.docx", "questions": [{"num": 1, "correct": "A", "stem": "한국의 기후와 계절에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "봄은 꽃샘추위가 있지만 따뜻해지면서 꽃이 핀다."}, {"label": "B", "text": "여름은 무덥고 비가 많이 내리며 황사가 불어오는 날이 많다."}, {"label": "C", "text": "가을은 비가 많이 오지만 화창한 날씨인 경우도 많다."}, {"label": "D", "text": "겨울은 차가운 바람의 영향으로 춥고 눈이 와서 습하다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Mùa xuân Hàn Quốc có đặc trưng là \"꽃샘추위\" (đợt rét cuối xuân) nhưng dần ấm lên và hoa nở — khớp với A.\nB sai: 황사 (bụi vàng) là hiện tượng của mùa XUÂN, không phải mùa hè.\nC sai: mùa thu Hàn Quốc đặc trưng là ÍT mưa, trời trong xanh và hanh khô, không phải \"mưa nhiều\".\nD sai: mùa đông Hàn Quốc lạnh và KHÔ (건조하다), không phải ẩm (습하다)."}, {"num": 2, "correct": "C", "stem": "한국의 지형에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "한국은 산이 국토의 약 65%를 차지하고 있는 나라다."}, {"label": "B", "text": "한국의 서쪽과 남쪽에는 강을 따라서 넓은 평야가 있다."}, {"label": "C", "text": "한국은 삼면이 바다로 둘러싸여 있고 다양한 지형을 볼 수 있다."}, {"label": "D", "text": "한국의 남쪽에 있는 제주도에는 한국에서 제일 높은 산인 한라산이 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "A đúng: khoảng 70% lãnh thổ Hàn Quốc là đồi núi. B đúng: các đồng bằng phù sa rộng lớn tập trung ở phía Tây và Nam. D đúng: Hallasan (1.950 m) trên đảo Jeju là núi cao nhất Hàn Quốc. Hàn Quốc là bán đảo, tiếp giáp biển ở ba mặt Đông, Tây và Nam."}, {"num": 3, "correct": "C", "stem": "서울에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "문화 시설과 편의시설이 서울에 집중되어 있다."}, {"label": "B", "text": "서울에는 정부의 주요 기관들이 집중되어 있다."}, {"label": "C", "text": "최근에는 관공서를 서울로 옮기는 경우가 많다."}, {"label": "D", "text": "대한민국의 수도로 중앙에 한강이 흐른다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Thực tế thì ngược lại: các cơ quan chính phủ (관공서) đang được chuyển RA KHỎI Seoul đến Sejong (세종시), không phải chuyển VÀO Seoul — nên C là câu SAI, đây là đáp án đúng.\nA, B, D đều là mô tả đúng về Seoul: là trung tâm văn hóa/tiện ích cả nước, nhiều cơ quan chính phủ vẫn còn ở đây, và sông Hàn chảy qua trung tâm thành phố."}, {"num": 4, "correct": "A", "stem": "<보기>\n· 7개 도 중에서 인구가 가장 많다\n· 신도시를 계속 건설하고 있다\n· 기반 시설이 잘 갖춰져 있고 다양한 산업이 고르게 발달했다\n<보기>의 설명에 알맞은 지역은?", "options": [{"label": "A", "text": "경기도"}, {"label": "B", "text": "충청북도"}, {"label": "C", "text": "경상북도"}, {"label": "D", "text": "전라남도"}], "correct_source": "docx", "options_source": "docx", "explanation": "Gyeonggi-do (경기도) là tỉnh đông dân nhất Hàn Quốc, bao quanh Seoul, liên tục xây dựng thành phố mới để giải quyết dân số tràn từ Seoul — khớp với A.\nB 충청북도 là tỉnh nội địa nhỏ, không phải đông dân nhất. C 경상북도 nằm ở Đông Nam. D 전라남도 nằm ở Tây Nam — cả 3 đều không khớp đặc điểm \"đông dân nhất, bao quanh Seoul\" được mô tả."}, {"num": 5, "correct": "A", "stem": "인천에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "서울과 경기도의 동쪽에 위치해 있으며 인천국제공항이 있다."}, {"label": "B", "text": "무역이 많이 이루어지고 있는 한국의 대표적인 항구 도시다."}, {"label": "C", "text": "2014년에는 인천 아시안게임을 주최하여 이름을 널리 알렸다."}, {"label": "D", "text": "서울을 제외한 수도권의 도시 중 가장 큰 도시로 발달했다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Incheon nằm ở phía TÂY của Seoul và Gyeonggi, không phải phía Đông — nên A là câu SAI, đây là đáp án đúng.\nB, C, D đều là mô tả đúng: Incheon là cảng thương mại lớn nhất Hàn Quốc, tổ chức Đại hội Thể thao châu Á 2014, và là thành phố lớn nhất vùng thủ đô sau Seoul."}, {"num": 6, "correct": "D", "stem": "한반도의 동쪽에 위치한 주요산맥으로 남북을 가로지르는 산맥의 이름은?", "options": [{"label": "A", "text": "차령산맥"}, {"label": "B", "text": "설악산맥"}, {"label": "C", "text": "호남산맥"}, {"label": "D", "text": "태백산맥"}], "correct_source": "docx", "options_source": "docx", "explanation": "Dãy núi Taebaek (태백산맥) chạy dọc phía Đông bán đảo Triều Tiên từ Bắc xuống Nam, được coi là \"xương sống\" của bán đảo — khớp với D.\nA 차령산맥 nằm ở miền Trung. B 설악산맥 không phải tên một dãy núi chạy dọc bán đảo (Seoraksan là một ngọn núi cụ thể thuộc dãy Taebaek). C 호남산맥 nằm ở phía Tây Nam."}, {"num": 7, "correct": "A", "stem": "<보기>\n· 해안선이 단조롭다\n· 해수욕장이 많다\n· 설악산, 오대산과 가까워서 관광업이 발달했다\n<보기>의 설명에 알맞은 것은?", "options": [{"label": "A", "text": "동해"}, {"label": "B", "text": "남해"}, {"label": "C", "text": "서해"}, {"label": "D", "text": "다도해"}], "correct_source": "docx", "options_source": "docx", "explanation": "Biển Đông (동해): bờ biển đơn giản (단조롭다), nhiều bãi tắm (해수욕장), gần núi Seoraksan và Odaesan — khớp với A.\nB 남해 có bờ biển phức tạp, nhiều đảo nhỏ. C 서해 có bãi bùn rộng lớn, chênh lệch thủy triều lớn. D 다도해 chỉ là tên gọi vùng biển nhiều đảo ở Biển Nam, không phải tên một vùng biển riêng."}, {"num": 8, "correct": "B", "stem": "충청지역에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "수도권과 영남, 호남을 이어주며 교통의 중심지 역할을 한다."}, {"label": "B", "text": "충청남도는 남한에서 유일하게 바다를 접하지 않는 지역이다."}, {"label": "C", "text": "이곳에는 국제공항이 있는 청주와 호수로 유명한 충주가 있다."}, {"label": "D", "text": "충청남도에는 옛날 백제의 도읍지였던 공주와 부여 등이 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Tỉnh duy nhất ở miền Nam không giáp biển thực ra là Chungcheongbuk-do (충청북도, Chungcheong Bắc), không phải Chungcheongnam-do (충청남도, Chungcheong Nam — tỉnh này giáp Biển Tây) — nên B là câu SAI, đây là đáp án đúng.\nA, C, D đều là mô tả đúng: Chungcheong là trung tâm giao thông kết nối cả nước, Cheongju có sân bay quốc tế và Chungju nổi tiếng với hồ nước, còn Gongju/Buyeo là cố đô của Baekje."}, {"num": 9, "correct": "C", "stem": "<보기>\n· 영남지역이라고도 불린다\n· 공업 단지가 많다\n· 경주에는 신라의 문화유산이, 안동에는 조선 유교의 문화유산이 있다\n· 독도가 있다\n<보기>의 설명에 알맞은 지역은?", "options": [{"label": "A", "text": "강원지역"}, {"label": "B", "text": "전라지역"}, {"label": "C", "text": "경상지역"}, {"label": "D", "text": "충청지역"}], "correct_source": "docx", "options_source": "docx", "explanation": "Gyeongsang (경상지역, còn gọi là Yeongnam): công nghiệp nặng, di sản Silla ở Gyeongju, di sản Nho giáo ở Andong (Dosan Seowon, làng Hahoe), đảo Dokdo — khớp chính xác với C.\nA 강원지역 nằm ở Đông Bắc. B 전라지역 nằm ở Tây Nam. D 충청지역 nằm ở miền Trung — không khớp các đặc điểm nêu."}, {"num": 10, "correct": "C", "stem": "한국의 지역별 특징으로 옳지 않은 것은?", "options": [{"label": "A", "text": "제주지역은 바람, 여자, 돌이 많기로 유명하다."}, {"label": "B", "text": "호남지역은 다양한 식재료가 생산되는 곳으로 유명하다."}, {"label": "C", "text": "전라지역의 동해안은 갯벌이 발달하여 조개류 등을 양식한다."}, {"label": "D", "text": "경상지역은 한국의 동남쪽에 위치해 영남지역으로 불리기도 한다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Bãi bùn (갯벌) phát triển ở bờ biển phía Tây và Nam, không phải bờ biển phía Đông — mà vùng Jeolla vốn chỉ giáp Biển Tây và Nam, không hề giáp Biển Đông — nên C là câu SAI, đây là đáp án đúng.\nA, B, D đều là mô tả đúng: Jeju nổi tiếng \"Tam đa\" (đá/gió/phụ nữ), Honam (Jeolla) nổi tiếng về nông sản/ẩm thực, và Gyeongsang nằm ở Đông Nam còn gọi là Yeongnam."}, {"num": 11, "correct": "D", "stem": "수도권의 인구 집중 문제를 해결하고 국가 균형 발전을 위해서 만들어진 도시는?", "options": [{"label": "A", "text": "서울특별시"}, {"label": "B", "text": "인천광역시"}, {"label": "C", "text": "제주특별자치도"}, {"label": "D", "text": "세종특별자치시"}], "correct_source": "docx", "options_source": "docx", "explanation": "Sejong (세종특별자치시) được thành lập để chuyển các cơ quan chính phủ ra khỏi Seoul, giải quyết tình trạng tập trung dân số và thúc đẩy phát triển cân bằng quốc gia — khớp với D.\nA Seoul chính là nguyên nhân gây ra vấn đề tập trung dân số. B Incheon là thành phố cảng, không được lập vì lý do này. C Jeju là đảo, không liên quan đến việc giải quyết tập trung dân số thủ đô."}, {"num": 12, "correct": "C", "stem": "도시와 관련 있는 문화유산을 연결한 것으로 옳은 것은?", "options": [{"label": "A", "text": "상주 - 석굴암"}, {"label": "B", "text": "영주 - 불국사"}, {"label": "C", "text": "안동 - 도산서원"}, {"label": "D", "text": "경주 - 하회마을"}], "correct_source": "docx", "options_source": "docx", "explanation": "Dosan Seowon (Thư viện Dosan) nằm ở Andong (안동), là nơi học trò thờ và học theo Yi Hwang (이황) — khớp với C.\nA, B sai: Seokguram và Bulguksa đều nằm ở Gyeongju (경주), không phải Sangju hay Yeongju.\nD sai: làng Hahoe (하회마을) nằm ở Andong, không phải Gyeongju."}, {"num": 13, "correct": "D", "stem": "다음 중 강원지역의 명소가 아닌 것은?", "options": [{"label": "A", "text": "설악산"}, {"label": "B", "text": "오죽헌"}, {"label": "C", "text": "춘천 남이섬"}, {"label": "D", "text": "보성 녹차밭"}], "correct_source": "docx", "options_source": "docx", "explanation": "Boseong (보성) là vùng trồng chè nổi tiếng thuộc tỉnh Jeollanam-do (전라남도), không phải Gangwon — nên D không phải danh thắng Gangwon, đây là đáp án đúng.\nA, B, C đều là danh thắng thuộc Gangwon: Seoraksan, Ojukheon (Gangneung, nơi sinh của Yi I), và đảo Nami ở Chuncheon."}, {"num": 14, "correct": "B", "stem": "지역별 관광 명소로 옳지 않은 것은?", "options": [{"label": "A", "text": "인천 - 강화도 갯벌"}, {"label": "B", "text": "전라 - 창녕 우포늪"}, {"label": "C", "text": "서울 - 명동, 남대문, 경복궁"}, {"label": "D", "text": "강원 - 경포대, 낙산해수욕장"}], "correct_source": "docx", "options_source": "docx", "explanation": "Đầm lầy Upo (창녕 우포늪) nằm ở Changnyeong, tỉnh Gyeongsangnam-do (경상남도), không phải Jeolla — nên B là câu SAI, đây là đáp án đúng.\nA, C, D đều là mô tả đúng: bãi bùn Ganghwa-do thuộc Incheon, các danh thắng Myeongdong/Namdaemun/Gyeongbokgung thuộc Seoul, và Gyeongpodae/bãi biển Naksan thuộc Gangwon."}, {"num": 15, "correct": "B", "stem": "지역 축제에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "전주 세계 소리 축제와 남원 춘향제는 전라지역의 대표적인 축제이다."}, {"label": "B", "text": "경상지역에서는 평창 대관령 눈꽃 축제와 화천 산천어 축제 등이 있다."}, {"label": "C", "text": "충청지역의 대표적인 축제로 백제 문화제, 보령 머드 축제를 꼽을 수 있다."}, {"label": "D", "text": "경기지역의 대표적인 축제로는 이천 도자기 축제와 고양 국제꽃 박람회가 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Pyeongchang (평창) và Hwacheon (화천) đều thuộc Gangwon (강원), không phải Gyeongsang — nên B là câu SAI, đây là đáp án đúng.\nA, C, D đều là mô tả đúng về các lễ hội đặc trưng của Jeolla, Chungcheong, và Gyeonggi."}, {"num": 16, "correct": "B", "stem": "제주도는 세 가지가 많기 때문에 '삼다도'라고 불리기도 했는데, 이 세 가지에 해당하지 않는 것은?", "options": [{"label": "A", "text": "돌"}, {"label": "B", "text": "태풍"}, {"label": "C", "text": "여자"}, {"label": "D", "text": "바람"}], "correct_source": "docx", "options_source": "docx", "explanation": "Tam đa (삼다도) của Jeju là: Đá (돌), Gió (바람), Phụ nữ (여자) — Bão (태풍) không thuộc nhóm \"Tam đa\" này, dù Jeju cũng hay có bão — nên B là đáp án đúng cho câu hỏi \"không thuộc về\".\nA, C, D đều là 3 yếu tố chính thức của \"Tam đa đảo\" (삼다도)."}, {"num": 17, "correct": "A", "stem": "전라지역에 속해 있는 광역시는?", "options": [{"label": "A", "text": "광주광역시"}, {"label": "B", "text": "대전광역시"}, {"label": "C", "text": "울산광역시"}, {"label": "D", "text": "대구광역시"}], "correct_source": "docx", "options_source": "docx", "explanation": "Gwangju (광주광역시) là thành phố trực thuộc trung ương duy nhất thuộc vùng Jeolla (Honam) — khớp với A.\nB Daejeon thuộc vùng Chungcheong. C Ulsan và D Daegu đều thuộc vùng Gyeongsang."}, {"num": 18, "correct": "A", "stem": "다음 중 지역과 그 지역의 축제를 연결한 것으로 옳은 것은?", "options": [{"label": "A", "text": "강원지역 - 강릉 단오제"}, {"label": "B", "text": "전라지역 - 부산 국제 영화제"}, {"label": "C", "text": "충청지역 - 광주 디자인 비엔날레"}, {"label": "D", "text": "경상지역 - 대전 사이언스 페스티벌"}], "correct_source": "docx", "options_source": "docx", "explanation": "Lễ hội Dano Gangneung (강릉 단오제) là Di sản Văn hóa Phi vật thể của UNESCO, thuộc Gangwon — khớp với A.\nB sai: Liên hoan phim Busan (BIFF) thuộc Gyeongsang (Busan), không phải Jeolla.\nC sai: Gwangju Design Biennale thuộc Jeolla (Gwangju), không phải Chungcheong.\nD sai: Lễ hội Khoa học Daejeon thuộc Chungcheong (Daejeon), không phải Gyeongsang."}, {"num": 19, "correct": "C", "stem": "한국은 전체적으로 동쪽에 산이 많아서 동쪽이 높고 서쪽은 낮다. 이러한 한국의 지형을 의미하는 말은?", "options": [{"label": "A", "text": "북고남저"}, {"label": "B", "text": "서고동저"}, {"label": "C", "text": "동고서저"}, {"label": "D", "text": "남고북저"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Địa hình Hàn Quốc có đặc điểm phía Đông cao (nhiều núi, dãy Taebaek) và phía Tây thấp (đồng bằng, giáp biển) — đây là đặc điểm địa hình nổi bật nhất của bán đảo Triều Tiên, gọi là 동고서저 (Đông cao Tây thấp, 東高西低) — khớp với C.\nA, B, D là các hoán vị hướng khác của cùng cấu trúc từ, không đúng với đặc điểm địa hình Hàn Quốc."}, {"num": 20, "correct": "B", "stem": "국제적인 약속에 따라서 무장이 금지된 지역을 이르는 말로, 남한과 북한 사이에 있는 휴전선을 중심으로 남북으로 각각 2km, 좌우로는 250km를 차지하고 있는 곳은?", "options": [{"label": "A", "text": "군사분계선"}, {"label": "B", "text": "비무장지대"}, {"label": "C", "text": "판문점"}, {"label": "D", "text": "휴전선"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Khu vực phi quân sự (비무장지대, DMZ) là vùng đệm dọc theo đường ngừng bắn giữa Hàn Quốc và Bắc Triều Tiên, mỗi bên rộng 2km (tổng 4km) và kéo dài khoảng 250km từ Đông sang Tây theo Hiệp định đình chiến 1953 — khớp với B.\nA 군사분계선 (đường ranh giới quân sự, MDL) là đường CHÍNH GIỮA của khu DMZ, không phải bản thân vùng đệm rộng 4km. C 판문점 (Panmunjom) chỉ là MỘT địa điểm cụ thể trong khu DMZ, không phải tên gọi cả vùng. D 휴전선 (đường ngừng bắn) thường được dùng để chỉ đường ranh giới trung tâm, tương tự MDL, không phải khu vực rộng 4km xung quanh nó."}], "tables": []}, "hist7": {"title": "Ôn tập Lịch sử - 5단계 bài 7", "source": "5단계_7-역사_종합평가_기출문제_—_Giải_thích_chi_tiết.docx", "questions": [{"num": 1, "correct": "D", "stem": "한국 역사에서 처음으로 등장한 나라는?", "options": [{"label": "A", "text": "고려"}, {"label": "B", "text": "신라"}, {"label": "C", "text": "조선"}, {"label": "D", "text": "고조선"}], "correct_source": "docx", "options_source": "docx", "explanation": "Gojoseon (고조선, Cổ Triều Tiên) là nhà nước đầu tiên trong lịch sử Hàn Quốc, do Dangun Wanggeom lập ra — khớp với D.\nA Goryeo thành lập năm 918, B Silla là một trong Tam Quốc (xuất hiện sau Gojoseon), C Joseon thành lập năm 1392 — cả 3 đều muộn hơn Gojoseon rất nhiều."}, {"num": 2, "correct": "C", "stem": "삼국 중에 가장 늦게 발전하였으나 꾸준히 성장해서 삼국을 통일한 국가는?", "options": [{"label": "A", "text": "고려"}, {"label": "B", "text": "백제"}, {"label": "C", "text": "신라"}, {"label": "D", "text": "고구려"}], "correct_source": "docx", "options_source": "docx", "explanation": "Silla phát triển muộn nhất trong Tam Quốc nhưng liên minh với nhà Đường (Trung Quốc) để thống nhất Tam Quốc vào năm 676 — khớp với C.\nA Goryeo không thuộc Tam Quốc (xuất hiện sau khi Silla suy yếu). B Baekje phát triển sớm nhưng bị diệt trước. D Goguryeo hùng mạnh nhất nhưng bị diệt trước Baekje."}, {"num": 3, "correct": "B", "stem": "'나라의 교육과 역사가 없어지지 아니하면 그 나라는 망하지 않는다'라고 말한 사람은?", "options": [{"label": "A", "text": "김대중"}, {"label": "B", "text": "박은식"}, {"label": "C", "text": "유관순"}, {"label": "D", "text": "허난설헌"}], "correct_source": "docx", "options_source": "docx", "explanation": "Nhà sử học và nhà hoạt động độc lập Park Eun-sik đã nói câu này, nhấn mạnh tầm quan trọng của giáo dục và lịch sử trong việc bảo tồn dân tộc dưới thời Nhật thuộc — khớp với B.\nA Kim Dae-jung là Tổng thống Hàn Quốc (thời hiện đại, không liên quan). C Yu Gwan-sun là nữ anh hùng phong trào 1/3. D Heo Nanseolheon là nữ thi sĩ thời Joseon — cả 2 đều không phải người nói câu này."}, {"num": 4, "correct": "D", "stem": "나라 이름과 건국한 사람의 이름을 연결한 것으로 옳지 않은 것은?", "options": [{"label": "A", "text": "고려 - 왕건"}, {"label": "B", "text": "고조선 - 단군"}, {"label": "C", "text": "조선 - 이성계"}, {"label": "D", "text": "고구려 - 대조영"}], "correct_source": "docx", "options_source": "docx", "explanation": "Goguryeo được lập bởi Jumong (주몽), không phải Dae Joyeong — Dae Joyeong là người lập ra Balhae (발해) — nên D là câu SAI, đây là đáp án đúng.\nA, B, C đều là ghép đôi đúng: Wang Geon lập Goryeo (918), Dangun Wanggeom lập Gojoseon, Yi Seonggye lập Joseon (1392)."}, {"num": 5, "correct": "D", "stem": "세계 최초의 금속활자로 찍은 책의 이름은?", "options": [{"label": "A", "text": "경국대전"}, {"label": "B", "text": "삼강행실도"}, {"label": "C", "text": "팔만대장경"}, {"label": "D", "text": "직지심체요절"}], "correct_source": "docx", "options_source": "docx", "explanation": "Jikji (직지심체요절) in năm 1377 thời Goryeo là cuốn sách được in bằng chữ kim loại (금속활자) sớm nhất thế giới còn tồn tại đến nay, được UNESCO công nhận — khớp với D.\nA Gyeongguk Daejeon là bộ luật triều Joseon. B Samgang Haengsildo là sách đạo đức thời Joseon. C Tripitaka Koreana (Bát Vạn Đại Tạng Kinh) được khắc trên gỗ (목판), không phải chữ kim loại."}, {"num": 6, "correct": "A", "stem": "한국의 지폐와 관련된 인물의 이름과 특징을 알맞게 연결하시오.", "options": [{"label": "A", "text": "1.000원-이황, 5.000원-이이, 10.000원-세종대왕, 50.000원-신사임당"}, {"label": "B", "text": "1.000원-이이, 5.000원-이황, 10.000원-세종대왕, 50.000원-신사임당"}, {"label": "C", "text": "1.000원-이황, 5.000원-이이, 10.000원-신사임당, 50.000원-세종대왕"}, {"label": "D", "text": "1.000원-세종대왕, 5.000원-이이, 10.000원-이황, 50.000원-신사임당"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Ghép đôi đúng: tờ 1.000 won in hình Yi Hwang (퇴계 이황), tờ 5.000 won in hình Yi I (율곡 이이), tờ 10.000 won in hình vua Sejong, tờ 50.000 won in hình Shin Saimdang (mẹ của Yi I) — khớp với A.\nB đảo ngược cặp 1.000/5.000. C đảo ngược cặp 10.000/50.000. D đảo ngược cặp 1.000/10.000 — đều là các hoán vị sai của cùng 4 mệnh giá."}, {"num": 7, "correct": "A", "stem": "조선 시대 제주도에 심한 흉년이 들어 사람들이 굶어 죽게 되었을 때 자신의 돈으로 쌀을 사서 사람들에게 나누어 주어 백성을 구한 사람은?", "options": [{"label": "A", "text": "김만덕"}, {"label": "B", "text": "유관순"}, {"label": "C", "text": "신사임당"}, {"label": "D", "text": "허난설헌"}], "correct_source": "docx", "options_source": "docx", "explanation": "Kim Man-deok là nữ thương gia thời Joseon ở Jeju. Khi đảo Jeju bị nạn đói, bà đã dùng toàn bộ tài sản tích lũy được để mua gạo từ đất liền về phát cho dân cứu đói — khớp với A.\nB Yu Gwan-sun là nữ anh hùng phong trào 1/3 năm 1919. C Shin Saimdang là nghệ sĩ và người mẹ mẫu mực, không liên quan cứu đói. D Heo Nanseolheon là nữ thi sĩ thời Joseon — cả 3 đều không liên quan."}, {"num": 8, "correct": "B", "stem": "불교의 문화유산이 아닌 것은?", "options": [{"label": "A", "text": "불국사"}, {"label": "B", "text": "삼강행실도"}, {"label": "C", "text": "팔만대장경"}, {"label": "D", "text": "정림사지 5층 석탑"}], "correct_source": "docx", "options_source": "docx", "explanation": "Samgang Haengsildo (삼강행실도, Tam Cương Hành Thực Đồ) là sách giáo dục đạo đức NHO GIÁO thời Joseon, không phải di sản Phật giáo — nên B là đáp án đúng cho câu hỏi \"không phải\".\nA Bulguksa là ngôi chùa Phật giáo nổi tiếng ở Gyeongju. C Tripitaka Koreana là bộ kinh Phật giáo khắc trên 81.258 tấm gỗ. D Tháp đá 5 tầng ở Jeongnimsaji là di tích Phật giáo thời Baekje — cả 3 đều là di sản Phật giáo thật sự."}, {"num": 9, "correct": "A", "stem": "외교를 통해 선란과위 전쟁을 막아낸 고려의 장군은?", "options": [{"label": "A", "text": "서희 (Seo Hui)"}, {"label": "B", "text": "김만덕"}, {"label": "C", "text": "이순신"}, {"label": "D", "text": "을지문덕"}], "correct_source": "docx", "options_source": "docx", "explanation": "Tướng Seo Hui của Goryeo đã dùng ngoại giao (외교 담판) để đàm phán với tướng Khiết Đan (거란), không chỉ ngăn chiến tranh mà còn giành lại vùng đất Gangdong 6 châu (강동 6주) — khớp với A.\nB Kim Man-deok là nữ thương gia, không phải tướng quân. C Yi Sun-sin là đô đốc thời Joseon (chiến tranh Nhật Bản). D Eulji Mundeok là tướng Goguryeo, đánh bại quân Tùy tại Salsu — cả 2 đều liên quan chiến tranh khác, không phải Khiết Đan bằng ngoại giao."}, {"num": 10, "correct": "D", "stem": "허난설헌에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "홍길동전을 지은 허균의 누나이다."}, {"label": "B", "text": "어렸을 때부터 글재주가 훌륭해서 시를 잘 지었다."}, {"label": "C", "text": "허난설헌의 시는 중국과 일본에서 높은 평가를 받았다."}, {"label": "D", "text": "허난설헌은 그림에 재능이 있었고 아들을 훌륭하게 키웠다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Heo Nanseolheon nổi tiếng về THƠ CA, không phải hội họa. Ngoài ra bà không có con trai sống sót (mất sớm ở tuổi 27) — người nổi tiếng vì nuôi dạy con trai xuất sắc (Yi I) là Shin Saimdang, không phải Heo Nanseolheon — nên D là câu SAI, đây là đáp án đúng.\nA, B, C đều là mô tả đúng: bà là chị gái của Heo Gyun (tác giả Hong Gil-dong jeon), có tài thơ văn từ nhỏ, và thơ của bà được đánh giá cao ở cả Trung Quốc và Nhật Bản."}, {"num": 11, "correct": "A", "stem": "3·1운동 이후 중국 상하이에 대한민국 임시정부를 세우고 독립운동을 이끌었던 인물은?", "options": [{"label": "A", "text": "김구 (Kim Gu)"}, {"label": "B", "text": "유관순"}, {"label": "C", "text": "안중근"}, {"label": "D", "text": "윤봉길"}], "correct_source": "docx", "options_source": "docx", "explanation": "Kim Gu là nhà lãnh đạo phong trào độc lập, Chủ tịch Chính phủ lâm thời Đại Hàn Dân Quốc tại Thượng Hải, là biểu tượng của phong trào kháng Nhật — khớp với A.\nB Yu Gwan-sun lãnh đạo biểu tình 1/3 ở Cheonan, không phải người lập Chính phủ lâm thời. C Ahn Jung-geun ám sát Ito Hirobumi năm 1909 (trước khi có Chính phủ lâm thời). D Yun Bong-gil ném bom vào quan chức Nhật tại Thượng Hải năm 1932, là THÀNH VIÊN của phong trào do Kim Gu lãnh đạo, không phải người lập ra nó."}, {"num": 12, "correct": "B", "stem": "백제에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "삼국 중 가장 먼저 발전하였다."}, {"label": "B", "text": "중국에 한자와 유교를 전하였다."}, {"label": "C", "text": "중국과 일본까지 활발하게 무역을 하였다."}, {"label": "D", "text": "대표적인 유적으로 부여 정림사지 5층 석탑이 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Baekje truyền bá Phật giáo, chữ Hán và văn hóa sang NHẬT BẢN (일본), không phải truyền cho Trung Quốc — bản thân chữ Hán và Nho giáo vốn có nguồn gốc từ Trung Quốc nên Baekje không thể \"truyền\" ngược lại cho Trung Quốc — nên B là câu SAI, đây là đáp án đúng.\nA, C, D đều là mô tả đúng: Baekje phát triển sớm nhất trong Tam Quốc, có quan hệ thương mại sôi động với cả Trung Quốc và Nhật Bản, và có di tích tiêu biểu là tháp đá 5 tầng ở Jeongnimsaji (Buyeo)."}, {"num": 13, "correct": "B", "stem": "신라에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "5세기에 영토를 크게 넓혔다."}, {"label": "B", "text": "한국 최초로 통일 국가를 이루었다."}, {"label": "C", "text": "동양에서 가장 오래된 천문대인 혼천의를 만들었다."}, {"label": "D", "text": "유교를 국가 이념으로 삼고 유교 문화를 발전시켰다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Silla thống nhất Tam Quốc vào năm 676, trở thành nhà nước thống nhất đầu tiên trong lịch sử Hàn Quốc — khớp với B.\nA sai: Goguryeo mới là nước mở rộng lãnh thổ lớn nhất vào thế kỷ 5 (thời vua Gwanggaeto).\nC sai: đài thiên văn cổ nhất châu Á là Cheomseongdae (첨성대), không phải Honcheonui (혼천의 — dụng cụ đo thiên văn khác, thuộc thời Joseon).\nD sai: Silla sùng bái Phật giáo (불교), không phải Nho giáo — Nho giáo mới là quốc giáo của Joseon."}, {"num": 14, "correct": "C", "stem": "발해에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "대조영이 고구려 유민들과 함께 세웠다."}, {"label": "B", "text": "통일 신라와 함께 '남북국 시대'라고 한다."}, {"label": "C", "text": "5세기에 가장 발전하여 영토를 크게 넓혔다."}, {"label": "D", "text": "고구려인들이 옛 고구려 땅인 만주에 세운 나라이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Balhae phát triển cực thịnh vào THẾ KỶ 9 (thời vua Seon - 선왕), không phải thế kỷ 5 — thế kỷ 5 là thời kỳ của Goguryeo — nên C là câu SAI, đây là đáp án đúng.\nA, B, D đều là mô tả đúng: Dae Joyeong lập Balhae năm 698 cùng người Goguryeo di tản, thời kỳ Balhae + Silla thống nhất gọi là \"Thời đại Nam Bắc Quốc\", và Balhae được lập ở vùng Mãn Châu (đất cũ Goguryeo)."}, {"num": 15, "correct": "D", "stem": "고려에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "벽란도로 아라비아 상인들도 들어와 무역하였다."}, {"label": "B", "text": "왕건은 발해 사람들까지 받아들여 고려를 건국했다."}, {"label": "C", "text": "고구려의 영토를 회복하겠다는 뜻으로 고려라고 지었다."}, {"label": "D", "text": "유교 이념으로 나라를 건국했으나 불교 행사도 많이 열었다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Goryeo lấy PHẬT GIÁO (불교) làm quốc giáo, không phải Nho giáo — Joseon mới lấy Nho giáo làm quốc giáo — Goryeo tổ chức nhiều lễ hội Phật giáo như Yeondeunghoe (연등회) và Palguanhoe (팔관회) — nên D là câu SAI, đây là đáp án đúng.\nA, B, C đều là mô tả đúng: cảng Byeokrando đón cả thương nhân Ả Rập, Wang Geon chào đón người Balhae di tản, và tên \"Goryeo\" lấy từ \"Goguryeo\" thể hiện ý chí khôi phục lãnh thổ."}, {"num": 16, "correct": "D", "stem": "조선 후기에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "서양의 여러 나라와 적극적으로 교류하였다."}, {"label": "B", "text": "조선의 발달된 문물을 서양으로 수출하였다."}, {"label": "C", "text": "쇄국정책을 실시하여 나라가 더욱 발전하였다."}, {"label": "D", "text": "정약용이 거중기를 만들어 수원 화성을 완성했다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Jeong Yak-yong (Dasan) đã phát minh ra cần cẩu (거중기) giúp xây dựng thành Hwaseong ở Suwon dưới thời vua Jeongjo — khớp với D.\nA, B sai: Joseon hậu kỳ theo chính sách bế quan tỏa cảng (쇄국정책), không tích cực giao lưu hay xuất khẩu văn hóa sang phương Tây.\nC sai: chính sách bế quan tỏa cảng thực ra làm Joseon CHẬM phát triển và dễ bị xâm lược hơn, không phải giúp phát triển hơn."}, {"num": 17, "correct": "D", "stem": "세종대왕에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "한글이라는 명칭은 세종대왕이 만들었다."}, {"label": "B", "text": "조선 시대의 법전인 경국대전을 완성하였다."}, {"label": "C", "text": "훈민정음이란 널리 인간을 이롭게 한다는 뜻이다."}, {"label": "D", "text": "조선의 네 번째 왕으로 과학 기술에 관심이 많았다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Vua Sejong là vị vua thứ 4 của Joseon và rất quan tâm đến khoa học kỹ thuật, đã cho chế tạo nhiều dụng cụ đo lường như 측우기 (đồng hồ mưa), 앙부일구 (đồng hồ mặt trời) — khớp với D.\nA sai: tên gọi \"한글 (Hangeul)\" được đặt bởi học giả Ju Si-gyeong (주시경) vào thế kỷ 20 — vua Sejong gọi chữ viết do ông sáng tạo là \"훈민정음 (Hunminjeongeum)\".\nB sai: Gyeongguk Daejeon được hoàn thành dưới thời vua Seongjong (성종), không phải Sejong.\nC sai: \"널리 인간을 이롭게 한다\" là ý nghĩa của Hongik Ingan (홍익인간) — lý tưởng lập quốc của Dangun, không phải nghĩa của Hunminjeongeum (nghĩa đúng là \"âm thanh đúng đắn để dạy dân\")."}, {"num": 18, "correct": "A", "stem": "신사임당에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "이이를 훌륭하게 키운 어머니이다."}, {"label": "B", "text": "한국 지폐에 있는 유일한 여성이다."}, {"label": "C", "text": "고려 시대를 대표하는 훌륭한 여성이다."}, {"label": "D", "text": "신사임당의 시가 중국과 일본에서 칭찬을 받았다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Shin Saimdang là mẹ của học giả Nho giáo Yi I (율곡 이이) và được tôn kính là người mẹ mẫu mực của Hàn Quốc — khớp với A.\nC sai: Shin Saimdang sống vào thời Joseon, không phải Goryeo.\nD sai: người nổi tiếng với thơ ca được đánh giá cao ở Trung Quốc và Nhật Bản là Heo Nanseolheon, không phải Shin Saimdang; Shin Saimdang nổi tiếng về hội họa và thư pháp."}, {"num": 19, "correct": "D", "stem": "수나라가 큰 군대를 이끌고 쳐들어 왔을 때 평양 가까이 살수에서 크게 승리한 고구려의 장군은?", "options": [{"label": "A", "text": "서희"}, {"label": "B", "text": "이순신"}, {"label": "C", "text": "김유신"}, {"label": "D", "text": "을지문덕"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Tướng Eulji Mundeok của Goguryeo đã đánh bại đại quân nhà Tùy (Trung Quốc) tại trận Salsu (살수대첩, năm 612) — một trong những chiến thắng vĩ đại nhất trong lịch sử Hàn Quốc, tiêu diệt hơn 300.000 quân Tùy — khớp với D.\nA Seo Hui dùng ngoại giao chống Khiết Đan (thời Goryeo, không phải chiến trận với nhà Tùy). B Yi Sun-sin là đô đốc thời Joseon chống Nhật Bản. C Kim Yu-sin là tướng thời Silla, liên quan việc thống nhất Tam Quốc, không liên quan trận Salsu."}, {"num": 20, "correct": "C", "stem": "임진왜란 때 거북선을 만들어 일본과의 전쟁을 승리로 이끌었던 인물은?", "options": [{"label": "A", "text": "김구"}, {"label": "B", "text": "을지문덕"}, {"label": "C", "text": "이순신 (Yi Sun-sin)"}, {"label": "D", "text": "서희"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Đô đốc Yi Sun-sin là người phát minh ra thuyền rùa (거북선) và lãnh đạo hải quân Joseon đánh bại quân Nhật trong chiến tranh Imjin (임진왜란, 1592-1598) — ông là anh hùng dân tộc vĩ đại nhất của Hàn Quốc — khớp với C.\nA Kim Gu là nhà lãnh đạo phong trào độc lập đầu thế kỷ 20, không liên quan chiến tranh Imjin. B Eulji Mundeok đánh quân Tùy thời Goguryeo. D Seo Hui dùng ngoại giao chống Khiết Đan thời Goryeo — cả 3 đều là nhân vật lịch sử khác thời kỳ."}], "tables": []}, "law6": {"title": "Ôn tập Pháp luật - 5단계 bài 6", "source": "5단계_6-법_종합평가_기출문제_—_Giải_thích_chi_tiết.docx", "questions": [{"num": 1, "correct": "A", "stem": "개인 간에 발생하는 문제를 해결하기 위한 재판은?", "options": [{"label": "A", "text": "민사 재판"}, {"label": "B", "text": "형사 재판"}, {"label": "C", "text": "가사 재판"}, {"label": "D", "text": "행정 재판"}], "correct_source": "docx", "options_source": "docx", "explanation": "Tòa dân sự (민사 재판) giải quyết các tranh chấp giữa cá nhân với cá nhân, như tranh chấp tài sản, hợp đồng, bồi thường thiệt hại — khớp với A.\nB Tòa hình sự xử lý các vụ phạm tội hình sự. C Tòa gia đình xử lý các vụ liên quan đến hôn nhân, ly hôn, nuôi con. D Tòa hành chính xử lý tranh chấp giữa cá nhân và cơ quan nhà nước."}, {"num": 2, "correct": "A", "stem": "검찰과 경찰의 공통점에 해당하는 것은?", "options": [{"label": "A", "text": "범죄에 대한 수사를 한다."}, {"label": "B", "text": "재판 과정에 직접 참여한다."}, {"label": "C", "text": "범죄자에 대한 재판을 청구한다."}, {"label": "D", "text": "범죄자에 대한 처벌을 요구한다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Cả Cảnh sát (경찰) và Viện Kiểm sát (검찰) đều có quyền điều tra tội phạm — đây là điểm chung duy nhất — khớp với A.\nB chỉ Viện Kiểm sát mới trực tiếp tham gia phiên tòa với tư cách công tố viên. C chỉ Viện Kiểm sát mới có quyền đề nghị truy tố (기소). D là chức năng của Viện Kiểm sát tại phiên tòa, không phải của Cảnh sát."}, {"num": 3, "correct": "D", "stem": "대한민국 국적법에서 국적 취득의 중요한 기준이 되는 것은?", "options": [{"label": "A", "text": "태어난 곳"}, {"label": "B", "text": "재산 정도"}, {"label": "C", "text": "출생증명서"}, {"label": "D", "text": "부모의 국적"}], "correct_source": "docx", "options_source": "docx", "explanation": "Hàn Quốc áp dụng nguyên tắc \"Quyền theo huyết thống\" (혈통주의/속인주의) — quốc tịch của đứa trẻ được xác định dựa trên quốc tịch của cha hoặc mẹ — khớp với D.\nA là nguyên tắc \"quyền theo nơi sinh\" (출생지주의), không phải nguyên tắc chính của Hàn Quốc. B tài sản không phải tiêu chí xác định quốc tịch. C giấy khai sinh chỉ là tài liệu, không phải tiêu chí."}, {"num": 4, "correct": "C", "stem": "학생을 대상으로 학교 안팎에서 신체적, 정신적, 재산상의 피해를 주는 행위는?", "options": [{"label": "A", "text": "음주 운전자"}, {"label": "B", "text": "가정 폭력"}, {"label": "C", "text": "학교 폭력"}, {"label": "D", "text": "무단 투기"}], "correct_source": "docx", "options_source": "docx", "explanation": "Bạo lực học đường (학교 폭력) là hành vi gây tổn hại về thể chất, tinh thần hoặc tài sản cho học sinh trong và ngoài phạm vi trường học — khớp với C.\nA không liên quan đến hành vi gây hại cho học sinh tại trường. B bạo lực gia đình xảy ra trong phạm vi gia đình, không phải tại trường. D là hành vi vi phạm môi trường, không liên quan."}, {"num": 5, "correct": "B", "stem": "<보기>\n· 한국에 3년 이상 계속 주소가 있고 부모 중 한 사람이 한국인이었던 사람\n· 한국인과 결혼하여 한국에서 2년 이상 계속 거주하고 있는 사람\n이러한 사람들이 신청할 수 있는 것은?", "options": [{"label": "A", "text": "특별귀화"}, {"label": "B", "text": "간이귀화"}, {"label": "C", "text": "일반귀화"}, {"label": "D", "text": "보통귀화"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Nhập tịch giản lược (간이귀화) áp dụng cho người có liên hệ với Hàn Quốc qua huyết thống hoặc hôn nhân, yêu cầu thời gian cư trú ngắn hơn (2-3 năm) so với nhập tịch thông thường (5 năm) — khớp với B.\nA đặc biệt dành cho người có công lao đặc biệt với Hàn Quốc. C yêu cầu cư trú liên tục 5 năm. D không phải thuật ngữ chính thức trong luật quốc tịch Hàn Quốc."}, {"num": 6, "correct": "C", "stem": "<보기>\n돈을 빌려줄 때는 ( )을/를 작성하는 것이 좋다. 여기에는 빌려주는 사람과 빌리는 사람의 이름, 주소, 전화번호, 원금, 이자율, 거래 날짜, 서명 등을 반드시 적어야 한다.\n다음 빈칸에 공통으로 들어갈 단어는?", "options": [{"label": "A", "text": "사증"}, {"label": "B", "text": "영수증"}, {"label": "C", "text": "차용증"}, {"label": "D", "text": "보증서"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Giấy vay nợ (차용증) là văn bản ghi rõ thông tin người vay, người cho vay, số tiền, lãi suất, ngày giao dịch và chữ ký — tài liệu pháp lý quan trọng khi cho vay tiền — khớp với C.\nA Visa là giấy phép nhập cảnh, không liên quan. B biên lai dùng để xác nhận đã nhận tiền/hàng, không phải giấy vay nợ. D giấy bảo lãnh là văn bản của người thứ ba cam kết trả nợ thay."}, {"num": 7, "correct": "C", "stem": "부동산에 대한 권리 관계를 보여주는 문서는?", "options": [{"label": "A", "text": "계약서"}, {"label": "B", "text": "확인설명서"}, {"label": "C", "text": "등기부 등본"}, {"label": "D", "text": "주민등록 등본"}], "correct_source": "docx", "options_source": "docx", "explanation": "Sổ đăng ký bất động sản (등기부 등본) là tài liệu pháp lý chính thức ghi rõ quyền sở hữu, thế chấp và các quyền liên quan đến bất động sản — khớp với C.\nA hợp đồng ghi lại thỏa thuận, không phải tài liệu chứng minh quyền sở hữu. B là tài liệu môi giới cung cấp thông tin, không phải tài liệu quyền sở hữu. D chỉ ghi thông tin nơi cư trú."}, {"num": 8, "correct": "D", "stem": "부부가 각자 자신의 재산을 가질 수 있고 자신의 뜻에 따라 그 재산을 처분할 수 있는 권리는?", "options": [{"label": "A", "text": "협의 이혼"}, {"label": "B", "text": "재산 분할"}, {"label": "C", "text": "면접 교섭권"}, {"label": "D", "text": "부부 별산제"}], "correct_source": "docx", "options_source": "docx", "explanation": "Chế độ tài sản riêng (부부 별산제) là nguyên tắc mỗi vợ/chồng có quyền sở hữu và tự do định đoạt tài sản riêng của mình trong hôn nhân — khớp với D.\nA là hình thức ly hôn, không phải quyền về tài sản. B là quyền khi ly hôn, không phải quyền sở hữu tài sản riêng trong hôn nhân. C là quyền của cha/mẹ không nuôi con được thăm con sau ly hôn."}, {"num": 9, "correct": "D", "stem": "외국인이 한국에 체류하려고 할 때 옳지 않은 것은?", "options": [{"label": "A", "text": "체류지를 변경했을 때는 반드시 체류지 변경 신고를 해야 한다."}, {"label": "B", "text": "외국인등록과 체류지 변경 신고는 출입국·외국인청에서 할 수 있다."}, {"label": "C", "text": "한국에 머무르는 기간에 따라 단기체류자와 장기체류자로 나눌 수 있다."}, {"label": "D", "text": "90일을 초과하여 한국에 체류하려면 입국하자마자 외국인등록을 해야 한다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Người nước ngoài dự định lưu trú trên 90 ngày phải đăng ký ngoại kiều TRONG VÒNG 90 ngày kể từ ngày nhập cảnh, không phải \"ngay khi vừa nhập cảnh\" (입국하자마자) — nên D là câu SAI, đây là đáp án đúng.\nA, B, C đều là mô tả đúng: phải khai báo khi thay đổi nơi cư trú, cơ quan có thẩm quyền là Cục Xuất nhập cảnh và Người nước ngoài, và có thể phân loại theo thời gian lưu trú."}, {"num": 10, "correct": "A", "stem": "이혼에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "이혼에는 협의 이혼과 재판상 이혼이 있다."}, {"label": "B", "text": "부부 간의 합의가 없을 경우에는 이혼할 수 없다."}, {"label": "C", "text": "원인을 제공하고 잘못이 있는 배우자는 자녀를 만날 수 없다."}, {"label": "D", "text": "부부 모두 이혼을 원하면 고등법원이나 대법원에서 이혼할 수 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Hàn Quốc có 2 hình thức ly hôn: Ly hôn thuận tình (협의 이혼) khi cả hai đồng ý, và Ly hôn theo phán quyết tòa án (재판상 이혼) khi một bên không đồng ý — khớp với A.\nB sai: khi không có sự đồng ý của cả hai bên, vẫn có thể ly hôn qua tòa án nếu có lý do chính đáng.\nC sai: ngay cả người có lỗi trong hôn nhân vẫn có quyền thăm con (면접 교섭권) sau ly hôn.\nD sai: khi cả hai đồng ý ly hôn, thủ tục được thực hiện tại Tòa án gia đình (가정법원), không phải Tòa cấp cao hay Tòa tối cao."}, {"num": 11, "correct": "A", "stem": "법을 통해 권리를 보장받는 소송에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "모든 분쟁을 재판으로 해결하는 것이 가장 바람직하다."}, {"label": "B", "text": "법원의 판사는 법률에 따라 공정하게 판결을 내려 분쟁을 해결한다."}, {"label": "C", "text": "개인 간의 재산문제, 가족문제, 세금문제 등을 소송으로 해결할 수 있다."}, {"label": "D", "text": "재판 과정에서는 변호사나 대한법률구조공단의 도움을 받는 것이 바람직하다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Không phải mọi tranh chấp đều cần giải quyết bằng tòa án. Trên thực tế, các phương thức giải quyết thay thế (ADR) như hòa giải (조정), thương lượng (협상), trọng tài (중재) thường được khuyến khích vì nhanh hơn, ít tốn kém hơn và ít căng thẳng hơn — nên A là câu SAI, đây là đáp án đúng.\nB, C, D đều là mô tả đúng về chức năng của tòa án và quyền được tư vấn pháp lý."}, {"num": 12, "correct": "A", "stem": "<보기>\n(가) 국가인권위원회  (나) 국민권익위원회  (다) 외국인지원센터\nㄱ. 기본적인 인권을 위한 국가기관이다\nㄴ. 국가기관으로 인한 피해를 구제한다\nㄷ. 이민자나 외국인의 권리 보호를 돕는다\n<보기>의 기관과 설명을 알맞게 연결한 것은?", "options": [{"label": "A", "text": "(가)-ㄱ, (나)-ㄴ, (다)-ㄷ"}, {"label": "B", "text": "(가)-ㄴ, (나)-ㄱ, (다)-ㄷ"}, {"label": "C", "text": "(가)-ㄱ, (나)-ㄷ, (다)-ㄴ"}, {"label": "D", "text": "(가)-ㄷ, (나)-ㄴ, (다)-ㄱ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "국가인권위원회 (Ủy ban Nhân quyền Quốc gia) là cơ quan nhà nước độc lập bảo vệ nhân quyền cơ bản (ㄱ). 국민권익위원회 (Ủy ban Quyền lợi Nhân dân) giải quyết khiếu nại, tố cáo về hành vi sai trái của cơ quan nhà nước, tức \"cứu trợ thiệt hại do cơ quan nhà nước gây ra\" (ㄴ). 외국인지원센터 (Trung tâm Hỗ trợ Người nước ngoài) cung cấp thông tin, bảo vệ quyền lợi người nhập cư/người nước ngoài (ㄷ) — khớp với A.\nB, C, D đều ghép sai ít nhất một cặp cơ quan-chức năng."}, {"num": 13, "correct": "A", "stem": "<보기>\n(가) 협상  (나) 조정  (다) 중재\nㄱ. 제3자가 모든 권한을 부여받아 강제로 해결한다\nㄴ. 자발적으로 합의하고 대화로 해결한다\nㄷ. 제3자가 참여해서 조언이나 자문을 제공한다\n<보기>의 용어와 의미를 알맞게 연결한 것은?", "options": [{"label": "A", "text": "(가)-ㄴ, (나)-ㄷ, (다)-ㄱ"}, {"label": "B", "text": "(가)-ㄱ, (나)-ㄴ, (다)-ㄷ"}, {"label": "C", "text": "(가)-ㄷ, (나)-ㄱ, (다)-ㄴ"}, {"label": "D", "text": "(가)-ㄴ, (나)-ㄱ, (다)-ㄷ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "협상 (Thương lượng): hai bên tự nguyện đàm phán trực tiếp để đạt thỏa thuận, không cần bên thứ ba (ㄴ). 조정 (Hòa giải): bên thứ ba tham gia hỗ trợ, đưa ra gợi ý/tư vấn nhưng không quyết định thay (ㄷ). 중재 (Trọng tài): bên thứ ba được trao quyền đưa ra phán quyết có tính ràng buộc, bắt buộc các bên phải tuân theo (ㄱ) — khớp với A.\nB, C, D đều ghép sai ít nhất một cặp thuật ngữ-ý nghĩa."}, {"num": 14, "correct": "B", "stem": "태어난 아이의 국적을 결정할 때 부모가 가진 국적을 기준으로 아이의 국적을 결정하는 것은?", "options": [{"label": "A", "text": "속지주의"}, {"label": "B", "text": "혈통주의"}, {"label": "C", "text": "출생지주의"}, {"label": "D", "text": "죄형법정주의"}], "correct_source": "docx", "options_source": "docx", "explanation": "Nguyên tắc huyết thống (혈통주의/속인주의): quốc tịch của đứa trẻ được xác định dựa trên quốc tịch của cha hoặc mẹ — Hàn Quốc áp dụng nguyên tắc này — khớp với B.\nA, C đều là nguyên tắc xác định quốc tịch theo NƠI SINH, ngược lại với nguyên tắc huyết thống. D (nguyên tắc pháp định hình sự — \"không có tội nếu không có luật\") thuộc lĩnh vực luật hình sự, không liên quan đến quốc tịch."}, {"num": 15, "correct": "D", "stem": "다음 중 가정 폭력의 예로 옳지 않은 것은?", "options": [{"label": "A", "text": "가족에게 물건을 던지거나 때리는 것"}, {"label": "B", "text": "가족에게 욕설을 하거나 협박하는 것"}, {"label": "C", "text": "어린이나 노인을 제대로 돌보지 않는 것"}, {"label": "D", "text": "청소, 빨래, 요리 등 가사노동을 하지 않는 것"}], "correct_source": "docx", "options_source": "docx", "explanation": "Không làm việc nhà (가사노동 거부) không được pháp luật Hàn Quốc định nghĩa là bạo lực gia đình — bạo lực gia đình phải là hành vi CHỦ ĐỘNG gây hại, không phải hành vi thụ động không làm việc — nên D là đáp án đúng cho câu hỏi \"không phải bạo lực\".\nA là bạo lực thể chất (신체적 폭력). B là bạo lực tinh thần/ngôn ngữ (정신적/언어적 폭력). C (bỏ bê, sao nhãng — 방임) cũng là một hình thức bạo lực gia đình."}, {"num": 16, "correct": "B", "stem": "법의식에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "안전한 사회가 되면 법을 잘 지키게 된다."}, {"label": "B", "text": "법을 잘 지키는 정신을 준법정신이라고 한다."}, {"label": "C", "text": "법은 지키는 것보다 잘 만드는 것이 더 중요하다."}, {"label": "D", "text": "외국인은 한국의 법을 잘 모르므로 안 지켜도 된다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Tinh thần tuân thủ pháp luật gọi là \"준법정신\" (tinh thần tuân pháp) — đây là khái niệm cơ bản trong giáo dục pháp luật — khớp với B.\nA sai: thực ra ngược lại — chính việc mọi người tuân thủ pháp luật mới tạo ra xã hội an toàn.\nC sai: cả việc làm luật tốt lẫn tuân thủ luật đều quan trọng như nhau, luật tốt mà không ai tuân thủ thì vô nghĩa.\nD sai: nguyên tắc pháp lý cơ bản là \"không biết luật không được miễn trách nhiệm\" — người nước ngoài sống tại Hàn Quốc vẫn phải tuân thủ luật pháp Hàn Quốc."}, {"num": 17, "correct": "D", "stem": "정의로운 법을 만들도록 노력해야 하는 이유는?", "options": [{"label": "A", "text": "외국인은 헌법소원을 청구할 수 없기 때문이다."}, {"label": "B", "text": "국회에서 국민의 뜻에 따라 법을 만들기 때문이다."}, {"label": "C", "text": "국민의 기본권이나 인권이 자주 침해되기 때문이다."}, {"label": "D", "text": "정의로운 법을 통해 정의로운 사회가 될 수 있기 때문이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Mục đích cốt lõi của việc nỗ lực làm ra pháp luật công bằng là để xây dựng một xã hội công bằng — khớp trực tiếp với D.\nA không đúng thực tế (người nước ngoài có những quyền khiếu nại nhất định tùy trường hợp) và không phải lý do cần làm luật công bằng. B mô tả QUY TRÌNH lập pháp, không phải LÝ DO cần luật công bằng. C là một vấn đề cần giải quyết chứ không phải lý do/mục đích của việc làm luật công bằng."}, {"num": 18, "correct": "A", "stem": "다음 중 일반귀화의 조건이 아닌 것은?", "options": [{"label": "A", "text": "한국에서 3년 이상 생활할 것"}, {"label": "B", "text": "영주(F-5) 자격을 가지고 있는 외국인"}, {"label": "C", "text": "한국에 주소가 있는 만 19세 이상의 외국인"}, {"label": "D", "text": "품행이 단정하고 생계유지능력이 있는 외국인"}], "correct_source": "docx", "options_source": "docx", "explanation": "Nhập tịch thông thường (일반귀화) yêu cầu cư trú liên tục tại Hàn Quốc ít nhất 5 NĂM, không phải 3 năm — điều kiện 3 năm là của nhập tịch giản lược (간이귀화) — nên A là câu SAI, đây là đáp án đúng.\nB, C, D đều là điều kiện thật của nhập tịch thông thường: có tư cách thường trú F-5, có địa chỉ tại Hàn Quốc và đủ 19 tuổi, phẩm hạnh tốt và có khả năng tự nuôi sống bản thân."}, {"num": 19, "correct": "A", "stem": "한국에서는 외국인들이 한국 생활에 잘 적응하고 행복하게 생활할 수 있도록 2007년에 이 법을 제정하였다. 한국에 살고 있는 외국인들이 한국에서 불합리한 차별을 받지 않고 인권을 보장받도록 돕기 위해 제정한 이 법의 이름은?", "options": [{"label": "A", "text": "재한외국인 처우 기본법"}, {"label": "B", "text": "다문화가족지원법"}, {"label": "C", "text": "출입국관리법"}, {"label": "D", "text": "국적법"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Đạo luật \"재한외국인 처우 기본법\" (Luật cơ bản về đãi ngộ người nước ngoài tại Hàn Quốc) được ban hành năm 2007 nhằm hỗ trợ người nước ngoài hội nhập vào xã hội Hàn Quốc, bảo đảm họ không bị phân biệt đối xử và được bảo vệ nhân quyền cơ bản — khớp với A.\nB chuyên hỗ trợ gia đình đa văn hóa (không bao quát mọi người nước ngoài). C quy định thủ tục xuất nhập cảnh. D quy định điều kiện quốc tịch — cả 3 đều là luật liên quan nhưng không phải luật được mô tả trong câu hỏi."}, {"num": 20, "correct": "A", "stem": "2018년 12월 20일부터 국적법 개정에 따라 귀화나 국적 회복 허가를 받은 사람이 한국 국적을 가지기 위해서 국적증서 수여식에 참석하여 해야 하는 것은?", "options": [{"label": "A", "text": "국민선서"}, {"label": "B", "text": "시민권 신청"}, {"label": "C", "text": "외국인등록"}, {"label": "D", "text": "주민등록"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Từ ngày 20/12/2018, theo Luật Quốc tịch sửa đổi, người được cấp phép nhập tịch hoặc khôi phục quốc tịch phải tham dự Lễ trao Giấy chứng nhận quốc tịch (국적증서 수여식) và thực hiện Tuyên thệ quốc dân (국민선서) — cam kết tuân thủ Hiến pháp và pháp luật Hàn Quốc — để chính thức trở thành công dân Hàn Quốc — khớp với A.\nB không phải thủ tục của Hàn Quốc. C, D là các thủ tục đăng ký cư trú khác, không liên quan đến lễ nhập tịch."}], "tables": []}, "econ5": {"title": "Ôn tập Kinh tế - 5단계 bài 5", "source": "5단계_5-경제_종합평가_기출문제_—_Giải_thích_chi_tiết.docx", "questions": [{"num": 1, "correct": "C", "stem": "한국 경제가 빠르게 성장할 수 있었던 요인에 해당하지 않는 것은?", "options": [{"label": "A", "text": "풍부한 노동력"}, {"label": "B", "text": "뜨거운 교육열"}, {"label": "C", "text": "풍부한 자본과 기술"}, {"label": "D", "text": "경제 위기를 극복하겠다는 의지"}], "correct_source": "docx", "options_source": "docx", "explanation": "Hàn Quốc sau chiến tranh (1950-1953) không có vốn và công nghệ — tăng trưởng kinh tế ban đầu dựa vào lao động giá rẻ và viện trợ nước ngoài, không phải vốn và công nghệ sẵn có — nên C là câu trả lời đúng cho câu hỏi \"không phải yếu tố\".\nA, B, D đều là yếu tố thật giúp Hàn Quốc tăng trưởng nhanh: lực lượng lao động cần cù, nhiệt huyết giáo dục cao, và ý chí vượt qua khủng hoảng (ví dụ phong trào gom vàng năm 1997)."}, {"num": 2, "correct": "C", "stem": "1980년대 한국의 대표적인 수출 품목은?", "options": [{"label": "A", "text": "가발"}, {"label": "B", "text": "반도체"}, {"label": "C", "text": "자동차"}, {"label": "D", "text": "휴대폰"}], "correct_source": "docx", "options_source": "docx", "explanation": "Thập niên 1980s, Hàn Quốc bắt đầu xuất khẩu ô tô mạnh mẽ ra thị trường quốc tế (Hyundai, Kia) — khớp với C.\nA tóc giả là mặt hàng xuất khẩu chủ lực của thập niên 1960s. B chất bán dẫn trở thành mặt hàng xuất khẩu lớn từ thập niên 1990s-2000s. D điện thoại di động là mặt hàng xuất khẩu lớn từ thập niên 2000s."}, {"num": 3, "correct": "C", "stem": "'한강의 기적'에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "한강을 이용해 경제 성장을 이루었다."}, {"label": "B", "text": "한강이 없었다면 경제 성장을 할 수 없었다."}, {"label": "C", "text": "세계가 놀랄 정도로 빠르게 경제 성장이 이루어졌다."}, {"label": "D", "text": "다른 나라의 도움을 받아 빠른 경제 발전을 이루었다."}], "correct_source": "docx", "options_source": "docx", "explanation": "\"한강의 기적\" (Kỳ tích sông Hàn) là cách gọi cho việc kinh tế Hàn Quốc tăng trưởng nhanh đến mức cả thế giới phải kinh ngạc — khớp với C.\nA, B đều hiểu sai — tên gọi chỉ mang tính biểu tượng (Seoul nằm bên sông Hàn), không phải sông Hàn trực tiếp tạo ra tăng trưởng. D không phải ý nghĩa chính của cụm từ này."}, {"num": 4, "correct": "A", "stem": "다음 중 상설 시장에 해당하지 않는 것은?", "options": [{"label": "A", "text": "5일장"}, {"label": "B", "text": "백화점"}, {"label": "C", "text": "전통 시장"}, {"label": "D", "text": "대형 마트"}], "correct_source": "docx", "options_source": "docx", "explanation": "Chợ phiên 5 ngày (5일장) chỉ họp vào các ngày cố định trong tháng, không mở cửa hàng ngày — đây là chợ truyền thống định kỳ (정기 시장), không phải thường trực (상설 시장) — nên A là đáp án đúng.\nB, C, D đều mở cửa hàng ngày, là chợ/cửa hàng thường trực thật sự."}, {"num": 5, "correct": "D", "stem": "한국에서 화폐를 발행하는 은행은?", "options": [{"label": "A", "text": "국민은행"}, {"label": "B", "text": "우리은행"}, {"label": "C", "text": "농협은행"}, {"label": "D", "text": "한국은행"}], "correct_source": "docx", "options_source": "docx", "explanation": "Ngân hàng Trung ương Hàn Quốc (한국은행/Bank of Korea) là cơ quan duy nhất có quyền phát hành tiền tệ tại Hàn Quốc — khớp với D.\nA, B, C đều là ngân hàng thương mại/nông nghiệp, không có quyền phát hành tiền."}, {"num": 6, "correct": "B", "stem": "24시간 문을 열며 식료품과 간단한 생활용품을 파는 곳은?", "options": [{"label": "A", "text": "3일장"}, {"label": "B", "text": "편의점"}, {"label": "C", "text": "백화점"}, {"label": "D", "text": "슈퍼마켓"}], "correct_source": "docx", "options_source": "docx", "explanation": "Cửa hàng tiện lợi (편의점) như GS25, CU, 7-Eleven mở cửa 24/7, bán thực phẩm và đồ dùng thiết yếu — khớp với B.\nA chợ phiên họp định kỳ, không mở 24 giờ. C bách hóa không mở 24 giờ và không chuyên bán thực phẩm. D siêu thị nhỏ thường không mở 24 giờ."}, {"num": 7, "correct": "A", "stem": "은행에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "시중은행에는 신한은행, 국민은행, 제주은행이 있다."}, {"label": "B", "text": "은행이란 일반적으로 시중은행과 지방은행을 말한다."}, {"label": "C", "text": "대표적인 상품으로 보통예금 정기적금 정기예금이 있다."}, {"label": "D", "text": "인터넷, 스마트폰, 현금 인출기에서도 금융 거래를 할 수 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Ngân hàng Jeju (제주은행) là ngân hàng ĐỊA PHƯƠNG (지방은행), không phải ngân hàng thương mại toàn quốc (시중은행) — các ngân hàng thương mại lớn gồm Kookmin, Shinhan, Hana, Woori, SC제일은행... — nên A là câu SAI, đây là đáp án đúng.\nB, C, D đều là mô tả đúng về hệ thống ngân hàng Hàn Quốc."}, {"num": 8, "correct": "D", "stem": "최근 스마트폰 사용 증가와 함께 사용이 늘고 있는 결제 수단은?", "options": [{"label": "A", "text": "수표"}, {"label": "B", "text": "신용카드"}, {"label": "C", "text": "체크카드"}, {"label": "D", "text": "모바일 간편 결제"}], "correct_source": "docx", "options_source": "docx", "explanation": "Thanh toán di động (모바일 간편 결제) như KakaoPay, Samsung Pay, Naver Pay đang tăng mạnh cùng với sự phổ biến của smartphone — khớp với D.\nA không liên quan đến thanh toán qua smartphone. B, C (thẻ tín dụng/ghi nợ) đã phổ biến trước khi smartphone ra đời, không đặc biệt gắn với sự tăng trưởng của smartphone."}, {"num": 9, "correct": "C", "stem": "한국에서는 금융 기관이 망해도 예금자 보호법에 따라 원금과 이자를 합쳐 1인당 최고 ( )까지는 보호받을 수 있다.", "options": [{"label": "A", "text": "3천만 원"}, {"label": "B", "text": "4천만 원"}, {"label": "C", "text": "5천만 원"}, {"label": "D", "text": "1억 원"}], "correct_source": "docx", "options_source": "docx", "explanation": "Theo Luật Bảo vệ người gửi tiền (예금자 보호법) của Hàn Quốc, mỗi người được bảo vệ tối đa 50 triệu won (5천만 원), bao gồm cả gốc và lãi, tại một tổ chức tài chính — khớp với C.\nA, B đều thấp hơn mức bảo vệ thực tế. D vượt quá mức bảo vệ theo luật hiện hành."}, {"num": 10, "correct": "C", "stem": "일정한 금액을 정기적으로 입금하고 만기일에 원금과 이자를 한꺼번에 받는 상품은?", "options": [{"label": "A", "text": "주식"}, {"label": "B", "text": "정기예금"}, {"label": "C", "text": "정기적금"}, {"label": "D", "text": "보통예금"}], "correct_source": "docx", "options_source": "docx", "explanation": "Tiết kiệm định kỳ (정기적금): gửi một khoản tiền cố định hàng tháng, đến ngày đáo hạn nhận cả gốc lẫn lãi một lần — sản phẩm phù hợp để tích lũy dần — khớp với C.\nA cổ phiếu là đầu tư, không phải sản phẩm tiết kiệm định kỳ. B tiền gửi có kỳ hạn là gửi MỘT LẦN số tiền lớn, không phải gửi định kỳ hàng tháng. D tiền gửi thông thường có thể rút bất cứ lúc nào, không có kỳ hạn cố định."}, {"num": 11, "correct": "D", "stem": "시대별로 주요 수출 품목이 바르게 연결된 것은?", "options": [{"label": "A", "text": "1960년대 - 철강, 배"}, {"label": "B", "text": "1970년대 - 가발, 신발"}, {"label": "C", "text": "1980년대 - 자동차, 신발"}, {"label": "D", "text": "2000년대 - 반도체, 휴대폰"}], "correct_source": "docx", "options_source": "docx", "explanation": "Thập niên 2000s, Hàn Quốc xuất khẩu mạnh chất bán dẫn (반도체) và điện thoại di động (휴대폰) — Samsung, LG trở thành thương hiệu toàn cầu — khớp với D.\nA sai: thập niên 1960s xuất khẩu chủ yếu là tóc giả, quần áo, giày dép — thép và tàu là thập niên 1970s-80s.\nB sai: tóc giả và giày dép là thập niên 1960s — thập niên 1970s là thép, tàu, hóa chất.\nC sai: thập niên 1980s chủ yếu là ô tô và điện tử — giày dép đã giảm."}, {"num": 12, "correct": "B", "stem": "과거에는 국제사회의 원조를 받는 나라였다가 이제는 다른 나라를 원조하게 된 최초의 나라라고 평가를 받는 나라는?", "options": [{"label": "A", "text": "중국"}, {"label": "B", "text": "한국"}, {"label": "C", "text": "베트남"}, {"label": "D", "text": "우즈베키스탄"}], "correct_source": "docx", "options_source": "docx", "explanation": "Hàn Quốc là quốc gia đầu tiên trên thế giới chuyển từ vị thế \"nước nhận viện trợ\" (수원국) sang \"nước đi viện trợ\" (공여국), trở thành thành viên DAC (Ủy ban Hỗ trợ Phát triển) của OECD — khớp với B.\nA, C, D đều không có lịch sử chuyển đổi vị thế tương tự Hàn Quốc."}, {"num": 13, "correct": "B", "stem": "물건을 구입하는 도중에나 그 후에 피해를 입은 소비자를 도와주는 전문기관은?", "options": [{"label": "A", "text": "금융실명제"}, {"label": "B", "text": "한국소비자원"}, {"label": "C", "text": "예금자 보호제도"}, {"label": "D", "text": "외국인근로자지원센터"}], "correct_source": "docx", "options_source": "docx", "explanation": "한국소비자원 (Viện Người tiêu dùng Hàn Quốc) là cơ quan chuyên môn hỗ trợ người tiêu dùng bị thiệt hại khi mua sắm, giải quyết khiếu nại và bảo vệ quyền lợi người tiêu dùng — khớp với B.\nA là một chế độ tài chính, không phải cơ quan hỗ trợ người tiêu dùng. C là chế độ bảo vệ tiền gửi ngân hàng, không liên quan đến mua sắm. D hỗ trợ lao động nước ngoài, không phải người tiêu dùng nói chung."}, {"num": 14, "correct": "A", "stem": "수출이나 수입을 할 때 관세를 줄이거나 없애서 무역을 활발하게 하도록 하는 것은?", "options": [{"label": "A", "text": "자유무역협정"}, {"label": "B", "text": "제조물 책임법"}, {"label": "C", "text": "예금자 보호제도"}, {"label": "D", "text": "경제협력개발기구"}], "correct_source": "docx", "options_source": "docx", "explanation": "FTA (자유무역협정, Hiệp định Thương mại Tự do) là hiệp định giữa các quốc gia nhằm giảm hoặc xóa bỏ thuế quan (관세), thúc đẩy thương mại tự do — khớp với A.\nB quy định trách nhiệm của nhà sản xuất đối với sản phẩm lỗi, không liên quan đến thương mại quốc tế. C là chế độ tài chính trong nước. D (OECD) là tổ chức hợp tác kinh tế, không phải hiệp định thương mại."}, {"num": 15, "correct": "C", "stem": "한국의 실업률이 미국이나 유럽에 비해서 낮은 이유는?", "options": [{"label": "A", "text": "비정규직 노동자의 비율이 점점 낮아지고 있기 때문이다."}, {"label": "B", "text": "실업에 대한 사회보장제도가 잘 이루어져 있기 때문이다."}, {"label": "C", "text": "여성의 경제 활동 참여율이 적고 자영업자가 많기 때문이다."}, {"label": "D", "text": "예전에 비하여 근로 조건이 좋은 일자리가 늘어났기 때문이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Tỷ lệ tham gia kinh tế của phụ nữ thấp và có nhiều người tự kinh doanh (자영업자) khiến tỷ lệ thất nghiệp CHÍNH THỨC (thống kê) của Hàn Quốc thấp hơn — khớp với C.\nA, B, D đều không phải lý do thực tế — tỷ lệ lao động không chính thức không giảm, chế độ an sinh thất nghiệp chưa hoàn thiện bằng phương Tây, và việc làm tốt không tăng đáng kể."}, {"num": 16, "correct": "C", "stem": "취업 준비를 하는 자세로 옳지 않은 것은?", "options": [{"label": "A", "text": "전문성을 갖추기 위해 자격증을 취득한다."}, {"label": "B", "text": "구직이나 구인 정보에 많은 관심을 가진다."}, {"label": "C", "text": "구직 중 문제가 발생하면 출입국·외국인청과 상담한다."}, {"label": "D", "text": "원하는 직업을 찾고 필요한 능력을 갖추기 위해 노력한다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Khi gặp vấn đề trong quá trình tìm việc (như bị lừa đảo, vi phạm hợp đồng), nên liên hệ với Trung tâm Hỗ trợ Lao động Nước ngoài (외국인근로자지원센터) hoặc Bộ Lao động (고용노동부), không phải Cục Xuất nhập cảnh (출입국·외국인청) vốn chuyên về visa và cư trú — nên C là câu SAI, đây là đáp án đúng.\nA, B, D đều là thái độ chuẩn bị việc làm đúng đắn: lấy chứng chỉ nâng cao chuyên môn, theo dõi thông tin tuyển dụng, nỗ lực phát triển bản thân."}, {"num": 17, "correct": "C", "stem": "대표적인 저축 상품에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "자유롭게 돈을 넣고 빼서 쓸 수 있는 것은 보통예금이다."}, {"label": "B", "text": "매달 일정 금액을 일정 기간 동안 적립하는 것은 정기적금이다."}, {"label": "C", "text": "은행보다 안전하고 많은 이익을 얻을 수 있는 것은 보험예금이다."}, {"label": "D", "text": "일정 기간 동안 돌려받지 않을 것을 약속하고 돈을 맡기는 것은 정기예금이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "Không có sản phẩm nào gọi là \"보험예금\" (bảo hiểm tiền gửi) — bảo hiểm (보험) và tiền gửi (예금) là hai loại sản phẩm tài chính khác nhau. Hơn nữa, không sản phẩm nào \"an toàn hơn ngân hàng và lợi nhuận cao hơn\" cùng lúc — đây là mâu thuẫn với nguyên tắc tài chính cơ bản (rủi ro cao = lợi nhuận cao) — nên C là câu SAI, đây là đáp án đúng.\nA, B, D đều là mô tả đúng về tiền gửi thông thường, tiết kiệm định kỳ, và tiền gửi có kỳ hạn."}, {"num": 18, "correct": "A", "stem": "<보기>\n(가) 리콜제도  (나) 의무표시제  (다) 제조물 책임법\nㄱ. 상품에 대한 책임을 제조업체가 진다\nㄴ. 생산자가 소비자에게 상품의 문제를 알려주고 수리, 교환해 준다\nㄷ. 원산지 표시, 유통 기한, 영양 성분 표시 등 소비자의 안전에 중요한 표시를 반드시 하도록 한다\n<보기>의 제도와 설명을 알맞게 연결한 것은?", "options": [{"label": "A", "text": "(가)-ㄴ, (나)-ㄷ, (다)-ㄱ"}, {"label": "B", "text": "(가)-ㄱ, (나)-ㄴ, (다)-ㄷ"}, {"label": "C", "text": "(가)-ㄷ, (나)-ㄱ, (다)-ㄴ"}, {"label": "D", "text": "(가)-ㄴ, (나)-ㄱ, (다)-ㄷ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "리콜제도 (Chế độ thu hồi sản phẩm): khi phát hiện lỗi sản phẩm, nhà sản xuất phải chủ động thông báo và thu hồi/sửa chữa/đổi mới cho người tiêu dùng (ㄴ). 의무표시제 (Chế độ ghi nhãn bắt buộc): bắt buộc ghi xuất xứ, hạn sử dụng, thành phần dinh dưỡng... để bảo vệ người tiêu dùng (ㄷ). 제조물 책임법 (Luật Trách nhiệm sản phẩm): quy định nhà sản xuất phải bồi thường khi sản phẩm gây thiệt hại (ㄱ) — khớp với A.\nB, C, D đều ghép sai ít nhất một cặp chế độ-giải thích."}, {"num": 19, "correct": "A", "stem": "<보기>\n(가) 재화  (나) 물가  (다) 서비스\nㄱ. 물건 배달, 의사의 진료 등과 같은 무형의 활동이다\nㄴ. 상품과 서비스의 가치를 종합하여 계산한 평균 가격이다\nㄷ. 스마트폰, 화장품처럼 눈에 보이고 만질 수 있는 상품이다\n<보기>의 용어와 설명을 알맞게 연결한 것은?", "options": [{"label": "A", "text": "(가)-ㄷ, (나)-ㄴ, (다)-ㄱ"}, {"label": "B", "text": "(가)-ㄱ, (나)-ㄷ, (다)-ㄴ"}, {"label": "C", "text": "(가)-ㄴ, (나)-ㄱ, (다)-ㄷ"}, {"label": "D", "text": "(가)-ㄷ, (나)-ㄱ, (다)-ㄴ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "재화 (Hàng hóa): sản phẩm hữu hình có thể chạm vào được như điện thoại, mỹ phẩm (ㄷ). 물가 (Mức giá): mức giá trung bình chung của hàng hóa và dịch vụ trong nền kinh tế (ㄴ). 서비스 (Dịch vụ): hoạt động vô hình tạo ra giá trị như vận chuyển, khám bệnh (ㄱ) — khớp với A.\nB, C, D đều ghép sai ít nhất một cặp thuật ngữ-giải thích."}, {"num": 20, "correct": "A", "stem": "은행 계좌를 만들 때 본인이 은행을 직접 방문해서 자신의 이름으로 금융 거래를 해야만 하는 제도는?", "options": [{"label": "A", "text": "금융실명제"}, {"label": "B", "text": "예금자 보호제도"}, {"label": "C", "text": "신용카드제도"}, {"label": "D", "text": "전자상거래법"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "Chế độ giao dịch tài chính bằng tên thật (금융실명제) yêu cầu tất cả các giao dịch tài chính phải được thực hiện bằng tên thật của người giao dịch — khi mở tài khoản, người dùng phải đến trực tiếp ngân hàng và xác minh danh tính — chế độ này áp dụng từ năm 1993 nhằm ngăn chặn tham nhũng, trốn thuế và rửa tiền — khớp với A.\nB là chế độ bảo vệ tiền gửi khi ngân hàng phá sản, không liên quan đến việc xác minh danh tính khi mở tài khoản. C, D là các chế độ tài chính/thương mại khác, không liên quan trực tiếp."}], "tables": []}, "pol4": {"title": "5단계 4-정치 종합평가 기출문제", "source": "5단계_4-정치_종합평가_기출문제_—_Giải_thích_chi_tiết.docx", "questions": [{"num": 1, "correct": "D", "stem": "대한민국 헌법 제1장 제1조의 내용이 아닌 것은?", "options": [{"label": "A", "text": "대한민국은 민주공화국이다."}, {"label": "B", "text": "대한민국의 주권은 국민에게 있다."}, {"label": "C", "text": "모든 권력은 국민으로부터 나온다."}, {"label": "D", "text": "국민의 의견을 다수결의 원칙에 따라서 정한다."}], "correct_source": "docx", "options_source": "docx", "explanation": "헌법 제1조 제1항은 \"대한민국은 민주공화국이다\", 제2항은 \"대한민국의 주권은 국민에게 있고, 모든 권력은 국민으로부터 나온다\"이다. 다수결의 원칙(D)은 제1조에 나오는 내용이 아니다 — 정답은 D.\nA, B, C는 모두 제1조 제1항·제2항에 그대로 나오는 내용이다."}, {"num": 2, "correct": "D", "stem": "4.19 혁명의 원인이 된 사건은?", "options": [{"label": "A", "text": "외환 위기"}, {"label": "B", "text": "8.15 광복"}, {"label": "C", "text": "6.25 전쟁"}, {"label": "D", "text": "3.15 부정 선거"}], "correct_source": "docx", "options_source": "docx", "explanation": "1960년 3월 15일에 있었던 이승만 정부의 부정 선거(3.15 부정 선거)가 학생과 시민들의 시위를 촉발시켜 독재 정권을 무너뜨린 4.19 혁명으로 이어졌다 — 정답은 D.\nA 외환 위기는 1997년, B 8.15 광복은 1945년, C 6.25 전쟁은 1950~1953년의 사건으로 모두 4.19 혁명의 원인과 관련이 없다."}, {"num": 3, "correct": "B", "stem": "지방자치제가 필요한 이유로 옳지 않은 것은?", "options": [{"label": "A", "text": "각 지역마다 상황이나 문제점이 다르다."}, {"label": "B", "text": "국민이 정치에 참여하는 기본적인 방법이다."}, {"label": "C", "text": "지역 주민이 정치에 일상적으로 참여할 수 있다."}, {"label": "D", "text": "중앙 정부가 권력을 함부로 사용하는 것을 막는다."}], "correct_source": "docx", "options_source": "docx", "explanation": "국민이 정치에 참여하는 가장 기본적인 방법은 선거이며, 지방자치제는 그중 하나의 형태일 뿐 \"기본적인 방법\"이라고 할 수는 없다 — 옳지 않은 것은 B.\nA 지역마다 상황과 문제가 다르므로 지방자치가 필요하고, C 주민이 일상적으로 정치에 참여할 수 있게 하며, D 중앙 정부의 권력 남용을 견제하는 효과도 있다."}, {"num": 4, "correct": "D", "stem": "6월 민주항쟁의 결과로 옳은 것은?", "options": [{"label": "A", "text": "초대 대통령이 선출되었다."}, {"label": "B", "text": "대통령의 권한이 강화되었다."}, {"label": "C", "text": "군부 세력이 정권을 장악하였다."}, {"label": "D", "text": "국민이 직접 대통령을 선출하게 되었다."}], "correct_source": "docx", "options_source": "docx", "explanation": "1987년 6월 민주항쟁의 결과로 6.29 선언이 발표되어 대통령 직선제가 부활했고, 국민이 직접 대통령을 뽑을 수 있게 되었다 — 정답은 D.\nA 초대 대통령 선출은 1948년의 일이다. B 오히려 대통령의 권한은 이후 축소되었다. C 군부가 정권을 장악한 것은 그 이전(전두환 정권)의 일이며, 6월 민주항쟁은 이를 끝내기 위한 운동이었다."}, {"num": 5, "correct": "C", "stem": "다음 중 행정부가 하는 일은?", "options": [{"label": "A", "text": "법에 따라 재판을 한다."}, {"label": "B", "text": "국민을 위한 법을 만든다."}, {"label": "C", "text": "법률에 따라 국가를 운영한다."}, {"label": "D", "text": "정책을 잘 집행하는지 살펴본다."}], "correct_source": "docx", "options_source": "docx", "explanation": "행정부는 법률에 따라 국가를 운영하고 정책을 실제로 집행하는 역할을 한다 — 정답은 C.\nA 법에 따라 재판하는 것은 사법부의 일이다. B 법을 만드는 것은 입법부(국회)의 일이다. D 정책 집행을 감시하는 국정 감사는 국회(입법부)의 일이다."}, {"num": 6, "correct": "D", "stem": "국회에서 하는 일이 아닌 것은?", "options": [{"label": "A", "text": "법을 만든다."}, {"label": "B", "text": "1년 예산을 확정한다."}, {"label": "C", "text": "국정 감사를 실시한다."}, {"label": "D", "text": "법을 해석하고 적용한다."}], "correct_source": "docx", "options_source": "docx", "explanation": "법을 해석하고 적용하는 것은 사법부(법원)의 역할이며 국회가 하는 일이 아니다 — 정답은 D.\nA 입법, B 예산 심의·확정, C 국정 감사는 모두 국회 고유의 업무이다."}, {"num": 7, "correct": "A", "stem": "정부에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "대통령은 정부의 최고 책임자이다."}, {"label": "B", "text": "국무총리는 국민의 직접 선거로 선출된다."}, {"label": "C", "text": "대통령의 임기는 5년이며, 중임을 할 수 있다."}, {"label": "D", "text": "국무회의는 최고 의사 결정 기구로 의장은 국무총리이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "대통령은 행정부(정부)의 최고 책임자이다 — 정답은 A.\nB 국무총리는 대통령이 임명하며 국민이 직접 뽑지 않는다. C 대통령의 임기는 5년이지만 단임제로 중임(재선)을 할 수 없다. D 국무회의의 의장은 국무총리가 아니라 대통령이다."}, {"num": 8, "correct": "B", "stem": "영주권을 받은 후 3년이 지난 만 18세 이상의 외국인이 참여할 수 있는 선거는?", "options": [{"label": "A", "text": "국민 투표"}, {"label": "B", "text": "시장 선거"}, {"label": "C", "text": "대통령 선거"}, {"label": "D", "text": "국회의원 선거"}], "correct_source": "docx", "options_source": "docx", "explanation": "영주권(F-5)을 취득한 지 3년이 지나고 만 18세 이상인 외국인은 지방 선거(시장, 도지사, 지방의회 의원 등)에 투표할 수 있다 — 정답은 B.\nA 국민 투표, C 대통령 선거, D 국회의원 선거는 모두 대한민국 국민만 참여할 수 있다."}, {"num": 9, "correct": "D", "stem": "대통령의 권한으로 옳지 않은 것은?", "options": [{"label": "A", "text": "국군을 지휘하는 권한"}, {"label": "B", "text": "공무원을 임명하는 권한"}, {"label": "C", "text": "외국과 조약을 맺을 수 있는 권한"}, {"label": "D", "text": "범죄자의 형량을 늘릴 수 있는 권한"}], "correct_source": "docx", "options_source": "docx", "explanation": "대통령은 형(刑)을 줄이거나 없애 주는 사면권은 가지고 있지만, 형량을 늘리는 권한은 없다 — 옳지 않은 것은 D.\nA 국군 통수권, B 공무원 임명권, C 조약 체결권은 모두 헌법상 대통령의 권한이다."}, {"num": 10, "correct": "C", "stem": "선거에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "보통 선거 - 조건에 관계없이 공평하게 한 표씩 투표한다."}, {"label": "B", "text": "평등 선거 - 어떤 후보에 투표했는지 다른 사람이 모르게 한다."}, {"label": "C", "text": "직접 선거 - 다른 사람이 대신할 수 없고 자신이 직접 투표한다."}, {"label": "D", "text": "비밀 선거 - 만 18세 이상 한국 국민은 누구나 선거에 참여한다."}], "correct_source": "docx", "options_source": "docx", "explanation": "직접 선거는 본인이 직접 투표해야 하며 다른 사람이 대신할 수 없다는 원칙이다 — 정답은 C.\nA는 평등 선거(한 표의 가치가 모두 같음)에 대한 설명이다. B는 비밀 선거(누구에게 투표했는지 알 수 없음)에 대한 설명이다. D는 보통 선거(일정 연령 이상이면 누구나 투표 가능)에 대한 설명이다."}, {"num": 11, "correct": "B", "stem": "공정한 재판을 위한 제도로 옳지 않은 것은?", "options": [{"label": "A", "text": "사법부의 독립을 헌법으로 보장한다."}, {"label": "B", "text": "법원은 국회가 만든 법안을 거부할 수 있다."}, {"label": "C", "text": "특별한 이유가 없으면 재판 과정을 공개한다."}, {"label": "D", "text": "한 사건에 대해 세 번까지 재판을 받을 수 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "법원은 국회가 만든 법률을 거부할 권한이 없다. 법률의 위헌 여부는 헌법재판소가 판단한다 — 옳지 않은 것은 B.\nA 사법부 독립 보장, C 재판 공개주의, D 3심 제도는 모두 공정한 재판을 위한 실제 제도이다."}, {"num": 12, "correct": "D", "stem": "법원의 구성에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "대법원, 고등법원, 지방법원의 세 종류가 있다."}, {"label": "B", "text": "고등법원은 18개로 전국의 주요 지방에 설치되어 있다."}, {"label": "C", "text": "대법원은 대법원장 13명과 대법관 1명으로 구성되어 있다."}, {"label": "D", "text": "대법원에서 판결한 내용은 최종 판단이므로 변경할 수 없다."}], "correct_source": "docx", "options_source": "docx", "explanation": "대법원의 판결은 3심 제도의 마지막 단계로, 최종 판단이며 더 이상 상소할 수 없다 — 정답은 D.\nA 대법원·고등법원·지방법원 외에도 가정법원, 행정법원 등이 있다. B 18개는 지방법원의 수이며 고등법원은 전국에 5~6곳뿐이다. C 실제로는 대법원장 1명과 대법관 13명, 총 14명으로 구성된다."}, {"num": 13, "correct": "C", "stem": "정부의 역할에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "고용노동부는 취업과 노동 등에 관한 일을 한다."}, {"label": "B", "text": "법무부는 법질서와 이민 정책 등에 관한 일을 한다."}, {"label": "C", "text": "교육부는 각종 질병, 전염병 관리와 검역에 관한 일을 한다."}, {"label": "D", "text": "여성가족부는 여성과 청소년, 가족 정책 등에 관한 일을 한다."}], "correct_source": "docx", "options_source": "docx", "explanation": "질병과 전염병 관리, 검역은 보건복지부의 업무이며 교육부의 업무가 아니다 — 옳지 않은 것은 C.\nA 고용노동부, B 법무부, D 여성가족부에 대한 설명은 모두 옳다."}, {"num": 14, "correct": "C", "stem": "한국에서 외국인의 선거 참여에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "외국인은 한국에서 선거에 참여할 수 없다."}, {"label": "B", "text": "외국인은 선거의 4대 원칙과 관계없이 선거에 참여한다."}, {"label": "C", "text": "일정한 자격이 있는 외국인은 지방 선거에 참여할 수 있다."}, {"label": "D", "text": "외국인은 각 지역의 지방자치단체장 선거에만 투표권을 행사할 수 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "영주권(F-5)을 취득한 지 3년이 지나고 만 18세 이상이며 한국에 주소가 있는 외국인은 지방 선거에 참여할 수 있다 — 정답은 C.\nA 일정 자격을 갖춘 외국인은 참여할 수 있다. B 외국인도 선거의 4대 원칙(보통·평등·직접·비밀)을 똑같이 따라야 한다. D 지방자치단체장뿐 아니라 지방의회 의원 선거에도 투표할 수 있다."}, {"num": 15, "correct": "D", "stem": "지방의 행정을 지방 주민이 선출한 기관을 통하여 처리하는 제도는?", "options": [{"label": "A", "text": "신분제"}, {"label": "B", "text": "대통령제"}, {"label": "C", "text": "삼권 분립"}, {"label": "D", "text": "지방자치제"}], "correct_source": "docx", "options_source": "docx", "explanation": "지방자치제는 지역 주민이 직접 뽑은 대표 기관을 통해 그 지역의 행정을 스스로 처리하는 제도이다 — 정답은 D.\nA 신분제는 봉건 시대의 계급 구분 제도, B 대통령제는 국가 단위의 행정 체계, C 삼권 분립은 입법·행정·사법 권력을 나누는 원리로 모두 지방 행정과는 관련이 없다."}, {"num": 16, "correct": "B", "stem": "1980년 5.18 민주화운동의 주된 장소가 되었던 도시는?", "options": [{"label": "A", "text": "경주"}, {"label": "B", "text": "광주"}, {"label": "C", "text": "인천"}, {"label": "D", "text": "부산"}], "correct_source": "docx", "options_source": "docx", "explanation": "1980년 5.18 민주화운동은 광주에서 일어났다. 전두환 군사 정권에 맞서 시민들이 일으킨 항쟁으로, 유네스코 세계기록유산으로 등재되어 있다 — 정답은 B.\nA 경주는 신라의 옛 수도, C 인천, D 부산은 모두 5.18 민주화운동과 직접적인 관련이 없는 도시이다."}, {"num": 17, "correct": "B", "stem": "국가 권력을 입법부·행정부·사법부로 나누고, 각각의 기관에 권력을 분담시켜 국가 권력의 집중과 남용을 방지하려는 통치 조직 원리는?", "options": [{"label": "A", "text": "삼심 제도"}, {"label": "B", "text": "삼권 분립"}, {"label": "C", "text": "지방자치제"}, {"label": "D", "text": "헌법 재판소"}], "correct_source": "docx", "options_source": "docx", "explanation": "삼권 분립은 국가 권력을 입법부·행정부·사법부 세 기관으로 나누어 권력이 한곳에 집중되거나 남용되는 것을 막는 원리이다 — 정답은 B.\nA 삼심 제도는 재판을 세 번까지 받을 수 있는 사법상의 제도, C 지방자치제는 지역별 권한 분산, D 헌법재판소는 구체적인 기관 이름으로 모두 이 질문의 \"원리\" 자체를 가리키지 않는다."}, {"num": 18, "correct": "D", "stem": "민주정치의 발전에 영향을 미친 사건들을 발생 순서대로 배열한 것은?", "options": [{"label": "A", "text": "4.19 혁명 → 5.18 민주화운동 → 6월 민주항쟁 → 대한민국 정부 수립"}, {"label": "B", "text": "4.19 혁명 → 6월 민주항쟁 → 대한민국 정부 수립 → 5.18 민주화운동"}, {"label": "C", "text": "대한민국 정부 수립 → 6월 민주항쟁 → 5.18 민주화운동 → 4.19 혁명"}, {"label": "D", "text": "대한민국 정부 수립 → 4.19 혁명 → 5.18 민주화운동 → 6월 민주항쟁"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "역사적 순서는 대한민국 정부 수립(1948년) → 4.19 혁명(1960년, 이승만 정권을 무너뜨림) → 5.18 민주화운동(1980년, 광주에서 전두환 군사 정권에 맞선 항쟁) → 6월 민주항쟁(1987년, 대통령 직선제를 이끌어 냄) 순이다 — 정답은 D.\nA, B, C는 모두 이 순서와 다르게 뒤섞여 있어 옳지 않다."}, {"num": 19, "correct": "D", "stem": "국가를 다스리는 기본 원칙을 담고 있는 최고의 법은?", "options": [{"label": "A", "text": "법률"}, {"label": "B", "text": "명령"}, {"label": "C", "text": "조례"}, {"label": "D", "text": "헌법"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "헌법은 국가를 다스리는 기본 원칙과 국민의 권리·의무를 규정한 국가 최고의 법이며, 다른 모든 법은 헌법에 어긋날 수 없다 — 정답은 D.\nA 법률은 국회가 헌법에 따라 만드는 하위 법, B 명령은 행정부가 만드는 더 하위 규정, C 조례는 지방자치단체가 만드는 규정으로 모두 헌법보다 아래 단계의 법이다."}, {"num": 20, "correct": "D", "stem": "결혼, 이혼, 재산 상속, 자녀 양육 등과 관련된 분쟁을 해결하기 위한 재판은?", "options": [{"label": "A", "text": "민사 재판"}, {"label": "B", "text": "형사 재판"}, {"label": "C", "text": "행정 재판"}, {"label": "D", "text": "가사 재판"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "가사 재판은 결혼, 이혼, 재산 상속, 자녀 양육 등 가족 관계에서 생기는 분쟁을 전문적으로 다루는 재판이다 — 정답은 D.\nA 민사 재판은 개인 간의 일반적인 재산·계약 분쟁, B 형사 재판은 범죄에 대한 처벌, C 행정 재판은 개인과 국가 기관 사이의 분쟁을 다루며 가사 재판과는 구분된다."}], "tables": []}, "edu2": {"title": "5단계 2-교육 종합평가 기출문제", "source": "5단계_2-교육_종합평가_기출문제_—_Giải_thích_chi_tiết.docx", "questions": [{"num": 1, "correct": "D", "stem": "한국의 교육열에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "한국의 높은 교육열로 경제가 크게 발전했다."}, {"label": "B", "text": "높은 교육열로 인해서 부작용도 나타나고 있다."}, {"label": "C", "text": "대학교에 진학하기 위해서 대학수학능력시험을 치른다."}, {"label": "D", "text": "한국에서는 의무 교육만 받으면 거의 모든 교육이 끝난다."}], "correct_source": "docx", "options_source": "docx", "explanation": "한국의 의무 교육은 초등학교와 중학교(6+3년)뿐이다. 그러나 교육열이 매우 높아 대부분의 학생이 고등학교와 대학교까지 진학하고, 학원 등에서 추가로 공부한다. \"의무 교육만 받으면 교육이 거의 끝난다\"는 설명은 사실과 다르다 — 정답은 D.\nA, B, C는 모두 한국의 높은 교육열에 대한 옳은 설명이다."}, {"num": 2, "correct": "A", "stem": "한국의 고등 교육기관에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "한국의 고등 교육기관은 고등학교와 대학교이다."}, {"label": "B", "text": "교육대학교는 초등학교 교원 양성을 목적으로 한다."}, {"label": "C", "text": "직업과 관련된 기술을 가르치는 학교는 전문대학교이다."}, {"label": "D", "text": "요즘은 방송통신대학교나 사이버대학교 등도 인기가 높다."}], "correct_source": "docx", "options_source": "docx", "explanation": "\"고등 교육기관\"은 대학교, 대학원 등을 가리키는 용어이며 고등학교(중등 교육기관)는 포함되지 않는다. 따라서 \"고등 교육기관은 고등학교와 대학교이다\"라는 설명은 옳지 않다 — 정답은 A.\nB 교육대학교가 초등 교원을 양성한다는 설명은 그 자체로는 사실이므로 \"옳지 않은 것\"이 될 수 없다. C 전문대학교의 역할, D 방송통신대·사이버대의 인기는 모두 옳은 설명이다."}, {"num": 3, "correct": "C", "stem": "한국의 초·중등 교육 제도와 교육 일정에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "한국의 초·중등 교육은 무상 교육이다."}, {"label": "B", "text": "한국의 초·중등 교육은 모두 의무 교육이다."}, {"label": "C", "text": "1년은 2학기로 나누어 1학기는 9월에 시작한다."}, {"label": "D", "text": "학생을 집에서 가까운 사립 교육기관에 배정한다."}], "correct_source": "docx", "options_source": "docx", "explanation": "정답은 B — 한국의 초등학교와 중학교 교육은 모두 의무 교육이다.\nA 무상 교육과 의무 교육은 다른 개념이다. C 1학기는 3월에 시작하며 9월이 아니다. D 학생은 보통 집과 가까운 공립 교육기관에 배정되며 사립이 원칙은 아니다."}, {"num": 4, "correct": "D", "stem": "어린이집과 유치원에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "어린이집은 만 3세부터, 유치원은 만 0세부터 다닐 수 있다."}, {"label": "B", "text": "어린이집은 교육부에서, 유치원은 보건복지부에서 관할한다."}, {"label": "C", "text": "어린이집은 보통 평일 오전 9시~오후 2시 정도까지 운영한다."}, {"label": "D", "text": "유치원 교육비는 일반적으로 국공립이 사립보다 저렴한 편이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "정답은 D — 국공립 유치원은 사립 유치원보다 교육비가 저렴한 편이다.\nA 반대로 어린이집은 만 0세부터, 유치원은 만 3세부터 다닐 수 있다. B 반대로 어린이집은 보건복지부, 유치원은 교육부에서 관할한다. C 어린이집은 대개 더 긴 시간(오전 7시~오후 7시 등) 운영된다."}, {"num": 5, "correct": "A", "stem": "사회통합프로그램에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "이 과정을 신청하면 국적을 취할 수 있다."}, {"label": "B", "text": "이수하면 체류자격을 변경할 때 이점이 있다."}, {"label": "C", "text": "이민자의 한국 사회 적응을 지원하기 위해 만들어졌다."}, {"label": "D", "text": "한국어와 한국 문화 및 한국 사회의 이해 교육으로 이루어져 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "사회통합프로그램은 신청 자체로 국적을 주지 않는다. 이수하면 귀화 신청 시 일부 요건이 면제되는 혜택이 있을 뿐이다 — 옳지 않은 것은 A.\nB 체류자격 변경 시 이점, C 이민자 적응 지원 목적, D 한국어·문화·사회 이해 교육으로 구성된 점은 모두 옳은 설명이다."}, {"num": 6, "correct": "B", "stem": "한국의 보육제도에 대한 설명 중 옳은 것은?", "options": [{"label": "A", "text": "아이행복카드 신청은 인터넷에서만 할 수 있다."}, {"label": "B", "text": "아이행복카드로 유치원에 보육비를 낼 수 있다."}, {"label": "C", "text": "자녀의 나이나 기관의 유형에 상관없이 지원 금액이 같다."}, {"label": "D", "text": "집에서 취학 전 자녀를 양육하는 경우 지원을 받을 수 없다."}], "correct_source": "docx", "options_source": "docx", "explanation": "정답은 B — 아이행복카드로 어린이집, 유치원의 보육비·교육비를 결제할 수 있다.\nA 인터넷뿐 아니라 주민센터 방문 신청도 가능하다. C 자녀의 나이와 기관 유형에 따라 지원 금액이 다르다. D 가정에서 양육하는 경우에도 양육수당 등 지원을 받을 수 있다."}, {"num": 7, "correct": "D", "stem": "초·중등 교육기관의 교육 활동에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "초·중등 교육 과정은 교과와 창의적 체험 활동으로 구성된다."}, {"label": "B", "text": "학교 교육은 수업뿐만 아니라 현장 체험 학습으로도 이루어진다."}, {"label": "C", "text": "방과 후 학교 프로그램은 학생들의 사교육비 부담을 줄일 수 있다."}, {"label": "D", "text": "초등학교는 1개 차시 수업이 50분, 중학교는 45분, 고등학교는 40분이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "실제로는 그 반대이다: 초등학교 40분, 중학교 45분, 고등학교 50분으로 학년이 올라갈수록 수업 시간이 길어진다 — 옳지 않은 것은 D.\nA 교과와 창의적 체험 활동으로 구성된다는 것, B 현장 체험 학습도 포함된다는 것, C 방과 후 학교가 사교육비 부담을 줄여 준다는 것은 모두 옳은 설명이다."}, {"num": 8, "correct": "D", "stem": "다음 중 고등학교의 종류에 해당하지 않는 것은?", "options": [{"label": "A", "text": "일반 고등학교"}, {"label": "B", "text": "특성화 고등학교"}, {"label": "C", "text": "특수 목적 고등학교"}, {"label": "D", "text": "자유학년제 고등학교"}], "correct_source": "docx", "options_source": "docx", "explanation": "자유학년제는 중학교에 적용되는 제도이며, 고등학교의 한 종류가 아니다 — 정답은 D.\nA 일반 고등학교, B 특성화 고등학교, C 특수 목적 고등학교는 모두 실제 존재하는 고등학교의 종류이다."}, {"num": 9, "correct": "A", "stem": "<보기>\n(가) 기초 문해 교육  (나) 학력 보완 교육  (다) 직업 능력 교육\nㄱ. 문자를 읽고 쓰고 셈하는 기초 능력을 기르는 교육이다\nㄴ. 정규 학교 과정을 마치지 못한 성인에게 학습 기회를 제공하는 교육이다\nㄷ. 실업자의 취업이나 창업을 지원하는 교육이다\n<보기>의 평생교육 영역과 설명을 알맞게 연결한 것은?", "options": [{"label": "A", "text": "(가)-ㄱ, (나)-ㄴ, (다)-ㄷ"}, {"label": "B", "text": "(가)-ㄴ, (나)-ㄱ, (다)-ㄷ"}, {"label": "C", "text": "(가)-ㄷ, (나)-ㄱ, (다)-ㄴ"}, {"label": "D", "text": "(가)-ㄴ, (나)-ㄷ, (다)-ㄱ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "기초 문해 교육(가)은 읽기·쓰기·셈하기 등 가장 기본적인 능력을 기르는 교육이다(ㄱ). 학력 보완 교육(나)은 정규 학교를 마치지 못한 성인에게 학습 기회를 주는 교육이다(ㄴ). 직업 능력 교육(다)은 실업자의 취업·창업을 지원하는 교육이다(ㄷ) — 정답은 A.\nB, C, D는 모두 최소 한 쌍 이상 잘못 연결되어 있다."}, {"num": 10, "correct": "D", "stem": "여러 기관에서 다양하게 이루어지고 있으며, 누구든지 본인이 관심 있는 분야에 대해 언제, 어디서나 원할 때 계속적으로 배울 수 있음을 의미하는 교육 활동은?", "options": [{"label": "A", "text": "정규 교육"}, {"label": "B", "text": "사회통합프로그램"}, {"label": "C", "text": "학점은행제"}, {"label": "D", "text": "평생교육"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "평생교육은 여러 기관에서 다양하게 이루어지며, 누구나 관심 있는 분야를 언제 어디서나 계속 배울 수 있는 교육 활동을 의미한다 — 정답은 D.\nA 정규 교육은 학교 제도 안에서 정해진 기간에 이루어지는 교육이다. B 사회통합프로그램은 이민자 대상의 특정 프로그램이다. C 학점은행제는 학점을 인정받아 학위를 취득하는 제도로, 평생교육 전체를 가리키는 말은 아니다."}, {"num": 11, "correct": "D", "stem": "한국의 사회보험에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "병원에 갈 때 국민연금으로 의료비를 지원받을 수 있다."}, {"label": "B", "text": "건강보험은 회사에서 일하다가 다치면 보상해 주는 것이다."}, {"label": "C", "text": "산업재해보상보험은 정년퇴임 이후의 생활비를 지원해 주는 것이다."}, {"label": "D", "text": "고용보험에 가입하면 회사에서 해고된 후 일정 기간 동안 도움을 받을 수 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "정답은 D — 고용보험은 실직 후 일정 기간 동안 실업 급여 등을 지원한다.\nA 병원비 지원은 건강보험의 역할이다. B 근무 중 사고 보상은 산업재해보상보험의 역할이다. C 정년 이후 생활비 지원은 국민연금의 역할이다."}, {"num": 12, "correct": "A", "stem": "공공부조에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "모든 외국인은 공공부조를 받을 수 없다."}, {"label": "B", "text": "한국어 교육은 공공부조의 대표적인 혜택이다."}, {"label": "C", "text": "원칙적으로 공공부조는 한국 국민들에게만 적용된다."}, {"label": "D", "text": "한국 사람이라면 소득에 상관없이 지원받을 수 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "공공부조는 원칙적으로 한국 국민을 대상으로 하며, 일반적인 외국인은 대상이 아니다 — 정답은 A.\n참고: A와 C는 내용이 서로 가까워 헷갈릴 수 있는데, 원 자료의 정답은 A이다. B 한국어 교육은 공공부조가 아니라 별도의 지원 사업이다. D 공공부조는 소득이 낮은 사람을 대상으로 하므로 소득과 무관하다는 설명은 옳지 않다."}, {"num": 13, "correct": "A", "stem": "안전한 생활을 위한 방법으로 옳지 않은 것은?", "options": [{"label": "A", "text": "국가 재난 관리를 담당하는 기관은 법무부이다."}, {"label": "B", "text": "재난대응 안전한국훈련에 적극적으로 참여한다."}, {"label": "C", "text": "재난이나 사고가 발생했을 때는 긴급신고전화로 신고한다."}, {"label": "D", "text": "평소에 위험한 시설을 발견하면 안전신문고에 신고할 수 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "국가 재난 관리를 담당하는 기관은 행정안전부와 소방청이며, 법무부는 법질서·이민 정책을 담당한다 — 옳지 않은 것은 A.\nB 안전한국훈련 참여, C 긴급신고전화 이용, D 안전신문고 신고는 모두 안전한 생활을 위한 옳은 방법이다."}, {"num": 14, "correct": "C", "stem": "한국에서 집을 구하는 방법으로 옳지 않은 것은?", "options": [{"label": "A", "text": "전세로 집을 구하는 방식은 한국에서만 사용된다."}, {"label": "B", "text": "최근에는 반전세라는 방식으로 집을 구하기도 한다."}, {"label": "C", "text": "집을 구할 때는 친한 친구와 직접 거래하는 것이 좋다."}, {"label": "D", "text": "보증금을 안전하게 돌려받기 위해서 확정일자를 받는 것이 좋다."}], "correct_source": "docx", "options_source": "docx", "explanation": "집을 구할 때는 공인중개사를 통해 거래하는 것이 안전하며, 친한 친구와 직접 거래하는 것은 법적 보호를 받기 어려워 권장되지 않는다 — 옳지 않은 것은 C.\nA 전세 제도는 한국의 독특한 방식이라는 것, B 반전세가 늘고 있다는 것, D 확정일자를 받아야 보증금을 안전하게 지킬 수 있다는 것은 모두 옳은 설명이다."}, {"num": 15, "correct": "C", "stem": "한국에서 사용되는 통신 수단에 대한 내용으로 옳은 것은?", "options": [{"label": "A", "text": "퀵서비스는 택배보다 저렴하게 사용할 수 있다."}, {"label": "B", "text": "한국에서 유선 전화는 더 이상 사용하지 않게 되었다."}, {"label": "C", "text": "택배 회사나 편의점을 통해 택배 서비스를 이용할 수 있다."}, {"label": "D", "text": "스마트폰은 도시를 중심으로 보급되어 사용하는 데 제한이 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "정답은 C — 택배 회사뿐만 아니라 편의점에서도 택배를 접수하거나 받을 수 있다.\nA 퀵서비스는 택배보다 대체로 더 비싸다. B 유선 전화는 여전히 가정과 사무실에서 사용된다. D 스마트폰은 도시와 지방을 가리지 않고 전국적으로 널리 보급되어 있다."}, {"num": 16, "correct": "A", "stem": "한국의 의료기관의 종류와 이용 방법으로 옳은 것은?", "options": [{"label": "A", "text": "보건소는 국가가 운영하는 공공 보건 기관이다."}, {"label": "B", "text": "병이 심하지 않은 경우에는 우선 종합 병원에 간다."}, {"label": "C", "text": "갑자기 크게 다쳤을 때는 빨리 택시를 타고 병원에 간다."}, {"label": "D", "text": "한의원과 한방 병원을 이용할 때는 진료의뢰서가 필요하다."}], "correct_source": "docx", "options_source": "docx", "explanation": "정답은 A — 보건소는 국가나 지방자치단체가 운영하는 공공 보건 기관이다.\nB 가벼운 병은 먼저 동네 의원(병·의원)을 이용하는 것이 원칙이다. C 크게 다쳤을 때는 119를 불러 구급차로 이송하는 것이 안전하다. D 한의원·한방 병원은 별도의 진료의뢰서 없이도 바로 이용할 수 있다."}, {"num": 17, "correct": "A", "stem": "<보기>\n(가) 화재가 났을 때  (나) 도둑이 들었을 때  (다) 인터넷에서 범죄가 발생했을 때\nㄱ. 112  ㄴ. 118  ㄷ. 119\n<보기>의 상황과 신고 전화번호를 알맞게 연결한 것은?", "options": [{"label": "A", "text": "(가)-ㄷ, (나)-ㄱ, (다)-ㄴ"}, {"label": "B", "text": "(가)-ㄱ, (나)-ㄴ, (다)-ㄷ"}, {"label": "C", "text": "(가)-ㄴ, (나)-ㄷ, (다)-ㄱ"}, {"label": "D", "text": "(가)-ㄷ, (나)-ㄴ, (다)-ㄱ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "화재가 났을 때(가)는 119(소방·구급)에 신고한다(ㄷ). 도둑이 들었을 때(나)는 112(경찰)에 신고한다(ㄱ). 인터넷에서 범죄가 발생했을 때(다)는 118(인터넷 침해 신고)에 신고한다(ㄴ) — 정답은 A.\nB, C, D는 모두 최소 한 쌍 이상 잘못 연결되어 있다."}, {"num": 18, "correct": "D", "stem": "공공부조의 한 형태로 갑작스럽게 어려운 일을 당해 생계유지가 어려운 저소득층 가구를 지원하는 제도는?", "options": [{"label": "A", "text": "국민기초생활보장제도"}, {"label": "B", "text": "사회보험"}, {"label": "C", "text": "국민연금"}, {"label": "D", "text": "긴급복지지원제도"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "긴급복지지원제도는 갑작스러운 위기(실직, 사고, 질병 등)로 생계유지가 어려워진 저소득층 가구에 생계비, 의료비, 주거비 등을 신속히 지원하는 공공부조 제도이다 — 정답은 D.\nA 국민기초생활보장제도는 지속적인 저소득 가구를 대상으로 하는 좀 더 일반적인 공공부조이다. B 사회보험, C 국민연금은 공공부조가 아니라 보험 방식의 사회보장제도이다."}, {"num": 19, "correct": "D", "stem": "유네스코가 문맹퇴치사업에 세계적으로 큰 공을 세운 사람이나 단체에게 주는 상은?", "options": [{"label": "A", "text": "노벨 평화상"}, {"label": "B", "text": "아시아 문화상"}, {"label": "C", "text": "대한민국 문화 훈장"}, {"label": "D", "text": "세종대왕상"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "유네스코는 문맹 퇴치(문해 교육)에 큰 공을 세운 개인이나 단체에게 매년 세종대왕상을 수여한다. 한글을 창제한 세종대왕의 이름을 따서 만든 상이다 — 정답은 D.\nA 노벨 평화상은 평화 증진에 기여한 사람에게 주는 별도의 국제적인 상이다. B, C는 실제 문맹퇴치 관련 유네스코 상이 아니다."}], "tables": []}, "soc1": {"title": "5단계 1-사회 종합평가 기출문제", "source": "5단계_1-사회_종합평가_기출문제_—_Giải_thích_chi_tiết.docx", "questions": [{"num": 1, "correct": "C", "stem": "대한민국에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "대한민국을 상징하는 꽃은 벚꽃이다."}, {"label": "B", "text": "태극기는 대한민국의 국가(國歌)이다."}, {"label": "C", "text": "국기에 대한 경례를 할 때는 오른손을 왼쪽 가슴에 댄다."}, {"label": "D", "text": "대한민국을 줄여서 한국이라고 하며, 영어로는 'Korea'라고 한다."}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "국기에 대한 경례를 할 때는 오른손을 펴서 왼쪽 가슴에 대는 것이 예의이다 — 정답은 C.\nA 대한민국을 상징하는 꽃은 벚꽃이 아니라 무궁화이다. B 태극기는 국기(國旗)이며, 국가(國歌·나라를 상징하는 노래)는 애국가이다 — 둘을 혼동한 설명이다.\n참고: D \"한국\"과 \"Korea\"라는 설명도 사실이지만, 원 자료에서 기대하는 답은 C이다."}, {"num": 2, "correct": "D", "stem": "애국가와 태극기의 설명으로 옳은 것은?", "options": [{"label": "A", "text": "애국가 1절에는 남산과 무궁화가 나온다."}, {"label": "B", "text": "태극기의 4괘는 밝음, 순수, 평화, 조화를 의미한다."}, {"label": "C", "text": "국경일이나 국가기념일에만 태극기를 집 안이나 창문에 단다."}, {"label": "D", "text": "애국가는 4절로 구성되어 있으며, '나라를 사랑하는 노래'라는 뜻이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "애국가는 총 4절로 이루어져 있으며, 그 이름은 \"나라를 사랑하는 노래\"라는 뜻이다 — 정답은 D.\nA 남산과 무궁화는 애국가 1절이 아니라 후렴이나 다른 절에 나오는 내용이다. B 태극기의 4괘(건곤감리)는 하늘·땅·물·불을 의미하며, \"밝음, 순수, 평화, 조화\"는 태극기의 흰색 바탕이 상징하는 의미이다. C 태극기는 국경일뿐 아니라 평상시에도 집 안이나 관공서 등에 게양할 수 있다."}, {"num": 3, "correct": "D", "stem": "한국의 가족에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "부모와 미혼 자녀가 같이 사는 것을 확대가족이라고 한다."}, {"label": "B", "text": "산업화가 이루어지면서 부모와 함께 사는 가족이 늘고 있다."}, {"label": "C", "text": "1인 가구가 늘고 있으며 최근 결혼 연령이 점점 낮아지고 있다."}, {"label": "D", "text": "과거에는 결혼한 후에도 부모님을 모시고 함께 사는 경우가 많았다."}], "correct_source": "docx", "options_source": "docx", "explanation": "정답은 D — 과거 한국에서는 결혼 후에도 부모를 모시고 함께 사는 확대가족 형태가 흔했다.\nA 부모와 미혼 자녀만 사는 가족은 확대가족이 아니라 핵가족이다. B 산업화 이후에는 오히려 부모와 따로 사는 핵가족이 늘어났다. C 1인 가구가 느는 것은 맞지만, 결혼 연령은 낮아지는 것이 아니라 점점 높아지고 있다."}, {"num": 4, "correct": "D", "stem": "한국의 일터에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "한국에서는 만 15세 이상부터 일을 하는 것이 가능하다."}, {"label": "B", "text": "현재 한국 사람들이 가장 많이 원하는 일자리는 공무원이다."}, {"label": "C", "text": "여성들은 출산, 양육 문제로 재취업이 쉽지 않은 경우가 많다."}, {"label": "D", "text": "개인적으로 회사나 가게를 만들어 사업을 하는 사람이 거의 없다."}], "correct_source": "docx", "options_source": "docx", "explanation": "실제로는 자영업자 비율이 전체 노동 인구의 약 20~25%로, 다른 OECD 국가들에 비해 매우 높은 편이다 — 옳지 않은 것은 D.\nA 근로 가능 최소 연령이 만 15세라는 것, B 공무원이 가장 선호되는 직업이라는 것, C 여성의 경력 단절 문제는 모두 옳은 설명이다."}, {"num": 5, "correct": "C", "stem": "한글에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "1443년 세종대왕이 만들었다."}, {"label": "B", "text": "한글을 만든 후 문맹이 많이 줄어들었다."}, {"label": "C", "text": "자음은 하늘, 땅, 사람을 결합하여 만들었다."}, {"label": "D", "text": "한글은 자음 14개와 모음 10개로 이루어져 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "하늘·땅·사람(삼재)을 결합해 만든 것은 모음이며, 자음은 발음 기관(혀, 이, 목구멍 등)의 모양을 본떠 만들었다 — 옳지 않은 것은 C.\nA 세종대왕이 1443년에 창제한 것, B 문맹률이 크게 줄어든 것, D 기본 자음 14개와 모음 10개로 구성된 것은 모두 옳은 설명이다."}, {"num": 6, "correct": "A", "stem": "<보기>\n(가) 부부가 모두 일하는 것  (나) 같은 직장 사람들의 저녁 식사 모임\n(다) 퇴근 시간 후에 밤늦게까지 일하는 것  (라) 월요일부터 금요일까지 5일만 일하는 것\nㄱ. 맞벌이  ㄴ. 회식  ㄷ. 시간 외 근무  ㄹ. 주 5일제\n<보기>의 의미와 명칭을 알맞게 연결한 것은?", "options": [{"label": "A", "text": "(가)-ㄱ, (나)-ㄴ, (다)-ㄷ, (라)-ㄹ"}, {"label": "B", "text": "(가)-ㄴ, (나)-ㄱ, (다)-ㄹ, (라)-ㄷ"}, {"label": "C", "text": "(가)-ㄷ, (나)-ㄹ, (다)-ㄱ, (라)-ㄴ"}, {"label": "D", "text": "(가)-ㄹ, (나)-ㄷ, (다)-ㄴ, (라)-ㄱ"}], "correct_source": "docx", "options_source": "reconstructed", "explanation": "부부가 모두 일하는 것(가)은 맞벌이이다(ㄱ). 같은 직장 사람들의 저녁 식사 모임(나)은 회식이다(ㄴ). 퇴근 후 밤늦게까지 일하는 것(다)은 시간 외 근무이다(ㄷ). 월요일부터 금요일까지 5일만 일하는 것(라)은 주 5일제이다(ㄹ) — 정답은 A.\nB, C, D는 모두 최소 한 쌍 이상 잘못 연결되어 있다."}, {"num": 7, "correct": "D", "stem": "대중교통 이용을 장려하는 제도에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "환승 할인 제도"}, {"label": "B", "text": "버스 전용차로제"}, {"label": "C", "text": "버스 도착 알림 서비스"}, {"label": "D", "text": "자전거 무인 대여 시스템"}], "correct_source": "docx", "options_source": "docx", "explanation": "무인 자전거 대여 시스템(예: 서울의 따릉이)은 개인용 이동 수단이며, 버스·지하철 같은 대중교통을 장려하는 제도가 아니다 — 옳지 않은 것은 D.\nA 환승 할인, B 버스 전용차로제, C 버스 도착 알림 서비스는 모두 대중교통 이용을 장려하는 실제 제도이다."}, {"num": 8, "correct": "D", "stem": "오늘날의 인구 분포에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "농촌 지역에 인구가 많다."}, {"label": "B", "text": "도시 지역에 인구가 적다."}, {"label": "C", "text": "지역에 따른 인구 차이가 없어졌다."}, {"label": "D", "text": "서울을 중심으로 수도권에 집중되어 있다."}], "correct_source": "docx", "options_source": "docx", "explanation": "정답은 D — 한국의 인구는 서울을 중심으로 한 수도권에 크게 집중되어 있다.\nA, B는 실제와 반대이며(도시에 인구가 많고 농촌은 적다), C 지역별 인구 차이는 오히려 더 뚜렷해지고 있다."}, {"num": 9, "correct": "C", "stem": "다음 중 도시 문제에 해당하지 않는 것은?", "options": [{"label": "A", "text": "환경 오염이 심해진다."}, {"label": "B", "text": "교통 체증이 심해진다."}, {"label": "C", "text": "도시에 노동력이 부족해진다."}, {"label": "D", "text": "사람들이 살 집이 부족해진다."}], "correct_source": "docx", "options_source": "docx", "explanation": "노동력 부족은 오히려 농촌의 문제이다. 젊은 인구가 도시로 이동하면서 농촌에 일할 사람이 부족해지는 반면, 도시는 오히려 인구 과밀·실업 문제가 나타난다 — 정답은 C.\nA 환경 오염, B 교통 체증, D 주택 부족은 모두 대표적인 도시 문제이다."}, {"num": 10, "correct": "B", "stem": "도시화 현상이 나타난 이유로 가장 적절한 것은?", "options": [{"label": "A", "text": "주말농장"}, {"label": "B", "text": "빠른 산업화"}, {"label": "C", "text": "높은 교육열"}, {"label": "D", "text": "신도시 개발"}], "correct_source": "docx", "options_source": "docx", "explanation": "빠른 산업화로 도시에 일자리가 많이 생기면서 농촌 인구가 도시로 이동한 것이 한국 도시화의 가장 큰 원인이다 — 정답은 B.\nA 주말농장은 오히려 도시민이 농촌을 찾는 최근 현상이다. C 교육열은 한국 사회의 특징이지만 도시화의 직접적인 원인은 아니다. D 신도시 개발은 도시화의 원인이 아니라 결과이다."}, {"num": 11, "correct": "B", "stem": "한국의 농촌에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "농촌 지역 특산물을 이용하여 지역 축제를 연다."}, {"label": "B", "text": "혼잡 통행료 등의 새로운 제도를 시행하고 있다."}, {"label": "C", "text": "1960년대에는 도시 인구보다 농촌 인구가 더 많았다."}, {"label": "D", "text": "고령화 현상은 농촌이 해결해야 할 대표적인 문제이다."}], "correct_source": "docx", "options_source": "docx", "explanation": "혼잡 통행료는 교통 체증을 줄이기 위한 도시의 제도이며, 농촌과는 관련이 없다 — 옳지 않은 것은 B.\nA 특산물을 활용한 지역 축제, C 1960년대 농촌 인구가 더 많았다는 것, D 고령화가 농촌의 대표적인 문제라는 것은 모두 옳은 설명이다."}], "tables": []}, "kinat": {"title": "KIIP 영주용 종합평가 (KINAT)", "source": "KIIP 영주용 종합평가 (KINAT)", "questions": [{"num": 1, "correct": "C", "stem": "옆집에서 피아노를 치는 ( )이/가 들려서 잠을 못 잤다.", "options": [{"label": "A", "text": "느낌"}, {"label": "B", "text": "냄새"}, {"label": "C", "text": "소리"}, {"label": "D", "text": "모양"}], "explanation": "소리 là âm thanh và kết hợp tự nhiên với 들리다 (nghe thấy). Câu hoàn chỉnh có nghĩa: Vì nghe thấy tiếng đàn piano từ nhà bên nên tôi không ngủ được."}, {"num": 2, "correct": "B", "stem": "다음 달이면 지금 살고 있는 아파트의 ( ) 기간이 끝나서 이사를 해야 한다.", "options": [{"label": "A", "text": "할부"}, {"label": "B", "text": "계약"}, {"label": "C", "text": "주택"}, {"label": "D", "text": "신청"}], "explanation": "계약 기간 nghĩa là thời hạn hợp đồng. Các từ còn lại lần lượt mang nghĩa trả góp, nhà ở và đăng ký nên không phù hợp."}, {"num": 3, "correct": "D", "stem": "한국어를 처음 배울 때에는 내 발음이 ( ) 한국 사람들이 내 말을 알아듣지 못했었다.", "options": [{"label": "A", "text": "뿌듯해서"}, {"label": "B", "text": "서먹해서"}, {"label": "C", "text": "유창해서"}, {"label": "D", "text": "부정확해서"}], "explanation": "부정확하다 nghĩa là không chính xác. Vì phát âm không chuẩn nên người Hàn không hiểu lời nói — phù hợp với D."}, {"num": 4, "correct": "B", "stem": "공장에서 나오는 더러운 물 때문에 강물이 ( ).", "options": [{"label": "A", "text": "빠졌다"}, {"label": "B", "text": "오염됐다"}, {"label": "C", "text": "말랐다"}, {"label": "D", "text": "위반했다"}], "explanation": "오염되다 nghĩa là bị ô nhiễm. Nước bẩn từ nhà máy làm cho nước sông bị ô nhiễm."}, {"num": 5, "correct": "A", "stem": "가: 잃어버린 가방이 비싼 거예요?\n나: 그렇지는 않은데 가방에 ( ) 물건이 들어 있어서 꼭 찾아야 해요.", "options": [{"label": "A", "text": "소중한"}, {"label": "B", "text": "소중할"}, {"label": "C", "text": "소중하니까"}, {"label": "D", "text": "소중하던"}], "explanation": "소중하다 chuyển thành định ngữ hiện tại 소중한 trước danh từ 물건. 소중한 물건 nghĩa là đồ vật quý giá."}, {"num": 6, "correct": "C", "stem": "가: 내일은 아침에 회의가 있으니까 평소보다 30분 일찍 깨워 주세요.\n나: 네, 일찍 ( ).", "options": [{"label": "A", "text": "깨우기로 해요"}, {"label": "B", "text": "깨웠어요"}, {"label": "C", "text": "깨울게요"}, {"label": "D", "text": "깨운 적이 있어요"}], "explanation": "-ㄹ/을게요 diễn tả lời hứa hoặc ý định của người nói đối với người nghe. 깨울게요 nghĩa là tôi sẽ đánh thức."}, {"num": 7, "correct": "B", "stem": "가: 밍밍 씨는 인기가 많은가 봐요.\n나: 네, 성격이 ( ) 한국말도 잘하거든요.", "options": [{"label": "A", "text": "밝아도"}, {"label": "B", "text": "밝은 데다가"}, {"label": "C", "text": "밝을 정도로"}, {"label": "D", "text": "밝을 테니까"}], "explanation": "-ㄴ/은 데다가 dùng để bổ sung thêm thông tin cùng chiều: tính cách vui vẻ, hơn nữa còn giỏi tiếng Hàn."}, {"num": 8, "correct": "A", "stem": "가: 주말인데 할 일도 없고 심심해요.\n나: 그래요? 이 영화가 정말 재미있다고 하던데 같이 ( )?", "options": [{"label": "A", "text": "볼래요"}, {"label": "B", "text": "봤어요"}, {"label": "C", "text": "보라고 해요"}, {"label": "D", "text": "보는 척해요"}], "explanation": "같이 볼래요? là cách rủ người nghe cùng xem phim rất tự nhiên. Các lựa chọn khác không mang nghĩa lời mời phù hợp."}, {"num": 9, "correct": "B", "stem": "나는 아무리 바쁜 일이 있어도 ( ).", "options": [{"label": "A", "text": "약속을 지키지 못한다"}, {"label": "B", "text": "약속을 꼭 지킨다"}, {"label": "C", "text": "약속을 취소했다"}, {"label": "D", "text": "약속을 지키기 때문이다"}], "explanation": "아무리 -아도/어도 nghĩa là dù thế nào cũng. Dù bận đến đâu vẫn nhất định giữ lời hẹn — B là câu tự nhiên nhất."}, {"num": 10, "correct": "A", "stem": "친구가 찾아왔을 때 나도 막 그 친구에게 ( ).", "options": [{"label": "A", "text": "전화하려던 참이었다"}, {"label": "B", "text": "전화하려야 할 수가 없었다"}, {"label": "C", "text": "전화하곤 했다"}, {"label": "D", "text": "전화할지도 모른다"}], "explanation": "-려던 참이었다 nghĩa là đúng lúc đang định làm việc gì. Khi bạn tới thì tôi cũng vừa định gọi cho bạn."}, {"num": 11, "correct": "B", "stem": "다음 두 문장을 알맞게 연결한 것을 고르시오.\n끝까지 포기하지 않다 / 결국 꿈을 이루다", "options": [{"label": "A", "text": "끝까지 포기하지 않으려면 결국 꿈을 이룰 수 있을 것이다."}, {"label": "B", "text": "끝까지 포기하지 않는다면 결국 꿈을 이룰 수 있을 것이다."}, {"label": "C", "text": "끝까지 포기하지 않은 탓에 결국 꿈을 이룰 수 있을 것이다."}, {"label": "D", "text": "끝까지 포기하지 않을 정도로 결국 꿈을 이룰 수 있을 것이다."}], "explanation": "-ㄴ/는다면 diễn tả điều kiện giả định. Nếu không bỏ cuộc đến cùng thì cuối cùng có thể thực hiện được ước mơ."}, {"num": 12, "correct": "D", "stem": "다음 두 문장을 알맞게 연결한 것을 고르시오.\n오래간만에 고향에 가다 / 기쁘다", "options": [{"label": "A", "text": "오래간만에 고향에 가더니 기뻐졌다."}, {"label": "B", "text": "오래간만에 고향에 가더니 기쁜 적이 있다."}, {"label": "C", "text": "오래간만에 고향에 가게 돼서 기쁠래야 기쁠 수가 없다."}, {"label": "D", "text": "오래간만에 고향에 가게 돼서 얼마나 기쁜지 모르겠다."}], "explanation": "얼마나 -ㄴ/는지 모르겠다 nhấn mạnh mức độ cảm xúc. Vì được về quê sau một thời gian dài nên vui không biết bao nhiêu."}, {"num": 13, "correct": "C", "stem": "다음 안내문의 ( )에 들어갈 말로 알맞은 것을 고르시오.\n다음 주 토요일 오전 10시에 서울숲에서 체육 대회를 엽니다. 오전에는 축구, 배구, 장기 경기가 있고 오후에는 요리 대회가 있습니다. 참가를 원하는 직원은 이번 주 금요일까지 신청해 주십시오. ( )", "options": [{"label": "A", "text": "초대해 주셔서 감사합니다."}, {"label": "B", "text": "참석하지 못해서 죄송합니다."}, {"label": "C", "text": "여러분의 많은 참가를 바랍니다."}, {"label": "D", "text": "토요일까지 신청을 받겠습니다."}], "explanation": "여러분의 많은 참가를 바랍니다 là câu kết phổ biến trong thông báo mời tham gia sự kiện. D sai vì hạn đăng ký là thứ Sáu."}, {"num": 14, "correct": "D", "stem": "다음 글의 ( )에 들어갈 내용으로 알맞은 것을 고르시오.\n한국 사람들이 처음부터 '빨리빨리'를 좋아한 것은 아니다. 조선시대에는 ( ). 그러나 1960~1970년대 산업화 시대를 거치면서 '빨리빨리 하자'라는 말을 하기 시작했다.", "options": [{"label": "A", "text": "무척 부지런했다고 한다"}, {"label": "B", "text": "무슨 일이든지 빨리빨리 했다고 한다"}, {"label": "C", "text": "놀랄 정도로 성격이 적극적이었다고 한다"}, {"label": "D", "text": "여유 있게 행동하는 것을 좋아했다고 한다"}], "explanation": "Bài viết đối lập thời Joseon thong thả với văn hóa 빨리빨리 xuất hiện trong thời kỳ công nghiệp hóa, nên D phù hợp."}, {"num": 15, "correct": "D", "stem": "공공장소에서 휴대전화 소리를 줄이고, 다른 사람에게 피해를 주지 않으며, 반려동물과 함께 있을 때에도 주변 사람을 배려해야 한다는 글의 제목으로 알맞은 것은?", "options": [{"label": "A", "text": "공공장소에서 이것만은 꼭 지킵시다"}, {"label": "B", "text": "내가 가장 싫어하는 행동들"}, {"label": "C", "text": "공공장소에서 금연하기"}, {"label": "D", "text": "우리 모두 질서를 지킵시다"}], "explanation": "Đoạn văn đề cập nhiều phép lịch sự khác nhau ở nơi công cộng, nên tiêu đề bao quát nhất là 우리 모두 질서를 지킵시다."}, {"num": 16, "correct": "D", "stem": "다음 중 공공장소에서 지켜야 할 휴대전화 예절과 관계없는 것은?", "options": [{"label": "A", "text": "휴대전화를 진동으로 하고 시끄럽게 통화하지 않는다."}, {"label": "B", "text": "음악을 들을 때에는 이어폰을 사용한다."}, {"label": "C", "text": "휴대전화로 게임을 하면서 다른 사람에게 피해를 주지 않는다."}, {"label": "D", "text": "반려견을 싫어하는 사람이 있는지 신경 쓴다."}], "explanation": "D là phép lịch sự liên quan đến thú cưng, không phải phép lịch sự khi sử dụng điện thoại. A, B, C đều liên quan trực tiếp đến điện thoại ở nơi công cộng."}, {"num": 17, "correct": "D", "stem": "한국의 국기 ㉠과 국화 ㉡을 바르게 연결한 것은?", "options": [{"label": "A", "text": "㉠ 태극기  ㉡ 들국화"}, {"label": "B", "text": "㉠ 만국기  ㉡ 무궁화"}, {"label": "C", "text": "㉠ 만국기  ㉡ 들국화"}, {"label": "D", "text": "㉠ 태극기  ㉡ 무궁화"}], "explanation": "Quốc kỳ Hàn Quốc là 태극기 và quốc hoa là 무궁화, nên đáp án D đúng."}, {"num": 18, "correct": "A", "stem": "과거 한국의 가족 모습에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "과거에는 자녀를 보통 3~5명 정도씩 낳았다."}, {"label": "B", "text": "첫째 딸은 결혼한 후에도 부모와 같이 사는 경우가 많았다."}, {"label": "C", "text": "부모와 미혼 자녀만 사는 핵가족이 많았다."}, {"label": "D", "text": "고등학교를 졸업하면 부모와 떨어져 사는 것이 일반적이었다."}], "explanation": "Gia đình Hàn Quốc truyền thống thường có nhiều con. Việc sống cùng và phụng dưỡng cha mẹ thường gắn với con trai cả, đồng thời gia đình nhiều thế hệ phổ biến hơn gia đình hạt nhân."}, {"num": 19, "correct": "C", "stem": "한국의 출산 및 자녀 양육 지원 정책에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "중앙 정부에서는 임산부의 출산 비용을 전액 지원해 준다."}, {"label": "B", "text": "지자체에서는 출산 지원금이나 장려금을 지원하지 않는다."}, {"label": "C", "text": "출산 이후 영유아 보육비도 일부 지원받을 수 있다."}, {"label": "D", "text": "집에서 자녀를 양육할 경우에는 아무런 지원을 받을 수 없다."}], "explanation": "Sau khi sinh, gia đình có thể nhận hỗ trợ một phần chi phí chăm sóc trẻ sơ sinh và trẻ nhỏ. Các lựa chọn còn lại dùng từ tuyệt đối như toàn bộ hoặc không có bất kỳ hỗ trợ nào nên sai."}, {"num": 20, "correct": "D", "stem": "입학시험을 앞둔 사람에게 주는 선물로 적절하지 않은 것은?", "options": [{"label": "A", "text": "찹쌀떡"}, {"label": "B", "text": "초콜릿"}, {"label": "C", "text": "엿"}, {"label": "D", "text": "포크"}], "explanation": "찹쌀떡 và 엿 mang ý nghĩa 'dính' vào trường, còn sô-cô-la cũng là quà cổ vũ phổ biến. 포크 không có ý nghĩa liên quan đến thi cử."}, {"num": 21, "correct": "D", "stem": "한국의 식사 예절에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "밥그릇을 손에 들고 먹는다."}, {"label": "B", "text": "큰 소리를 내며 음식을 먹는다."}, {"label": "C", "text": "윗사람과 식사를 할 때 아랫사람이 먼저 수저를 든다."}, {"label": "D", "text": "기침을 할 때 얼굴을 옆으로 돌리고 손으로 입을 가린다."}], "explanation": "Khi ho cần quay mặt sang bên và che miệng. Người Hàn thường để bát trên bàn, ăn không gây tiếng động lớn và chờ người lớn cầm thìa đũa trước."}, {"num": 22, "correct": "C", "stem": "다음 설명에 해당하는 주택의 종류는?\n5층 이상이며 대규모로 건설되고 놀이터와 상가 등 편의 시설을 갖추고 있다.", "options": [{"label": "A", "text": "단독 주택"}, {"label": "B", "text": "연립 주택"}, {"label": "C", "text": "아파트"}, {"label": "D", "text": "다가구 주택"}], "explanation": "아파트 là khu nhà ở cao tầng được xây dựng quy mô lớn và thường có sân chơi, cửa hàng cùng nhiều tiện ích."}, {"num": 23, "correct": "B", "stem": "대한민국 헌법 제1조의 ( )에 들어갈 말로 알맞은 것은?\n대한민국의 주권은 ( )에게 있고, 모든 권력은 ( )으로부터 나온다.", "options": [{"label": "A", "text": "대통령"}, {"label": "B", "text": "국민"}, {"label": "C", "text": "국회의원"}, {"label": "D", "text": "시민혁명"}], "explanation": "Điều 1 Khoản 2 Hiến pháp quy định chủ quyền thuộc về 국민 và mọi quyền lực xuất phát từ 국민."}, {"num": 24, "correct": "B", "stem": "행정부의 각 부처의 책임자로서 대통령과 국무총리의 지휘와 감독을 받는 사람은?", "options": [{"label": "A", "text": "차관"}, {"label": "B", "text": "장관"}, {"label": "C", "text": "국회의원"}, {"label": "D", "text": "국무총리"}], "explanation": "장관 là người đứng đầu mỗi bộ trong nhánh hành pháp và chịu sự chỉ đạo, giám sát của Tổng thống cùng Thủ tướng."}, {"num": 25, "correct": "D", "stem": "1970년대부터 발달한 중화학 공업에 해당하지 않는 것은?", "options": [{"label": "A", "text": "조선"}, {"label": "B", "text": "제철"}, {"label": "C", "text": "석유화학"}, {"label": "D", "text": "옷과 신발"}], "explanation": "Đóng tàu, luyện thép và hóa dầu thuộc công nghiệp nặng và hóa chất phát triển mạnh trong thập niên 1970. Quần áo và giày dép thuộc công nghiệp nhẹ."}, {"num": 26, "correct": "A", "stem": "다음 중 시중은행이 아닌 것은?", "options": [{"label": "A", "text": "한국은행"}, {"label": "B", "text": "신한은행"}, {"label": "C", "text": "하나은행"}, {"label": "D", "text": "우리은행"}], "explanation": "한국은행 là Ngân hàng Trung ương, có chức năng phát hành tiền và thực hiện chính sách tiền tệ; không phải ngân hàng thương mại."}, {"num": 27, "correct": "A", "stem": "주택가와 가깝고 가격이 저렴하며 상인과 흥정할 수 있는 곳은?", "options": [{"label": "A", "text": "재래시장"}, {"label": "B", "text": "슈퍼마켓"}, {"label": "C", "text": "대형마트"}, {"label": "D", "text": "편의점"}], "explanation": "재래시장 là chợ truyền thống, thường gần khu dân cư, giá phải chăng và có thể thương lượng giá với người bán."}, {"num": 28, "correct": "D", "stem": "한국에 체류하는 외국인에 대한 설명으로 옳은 것은?", "options": [{"label": "A", "text": "한국에 30일 이상 체류하려면 외국인 등록을 해야 한다."}, {"label": "B", "text": "한국에 3년 이상 계속 체류하면 누구나 영주권을 신청할 수 있다."}, {"label": "C", "text": "미화 10만 달러 이상을 투자하면 누구나 영주권을 신청할 수 있다."}, {"label": "D", "text": "체류지 변경 신고는 관할 출입국·외국인관서 또는 읍·면·동 행정복지센터에서 할 수 있다."}], "explanation": "Khai báo thay đổi nơi cư trú có thể thực hiện tại cơ quan xuất nhập cảnh có thẩm quyền hoặc trung tâm hành chính cấp 읍·면·동. Người dự định lưu trú quá 90 ngày phải đăng ký người nước ngoài trong vòng 90 ngày; các điều kiện ở B và C cũng bị đơn giản hóa nên không đúng."}, {"num": 29, "correct": "B", "stem": "귀화에 대한 설명으로 옳지 않은 것은?", "options": [{"label": "A", "text": "한국 국민인 배우자와 혼인한 상태로 일정 기간 한국에 거주하면 귀화를 신청할 수 있다."}, {"label": "B", "text": "한국 국민과의 국제결혼을 통한 혼인귀화는 특별귀화에 해당한다."}, {"label": "C", "text": "귀화에는 일반귀화, 간이귀화, 특별귀화의 세 가지 유형이 있다."}, {"label": "D", "text": "일반귀화는 대한민국과 혈연적 관계가 없는 외국인이 국적을 취득하는 절차이다."}], "explanation": "Nhập tịch thông qua hôn nhân với công dân Hàn Quốc thuộc 간이귀화 (nhập tịch giản lược), không phải 특별귀화, nên B là phát biểu sai."}, {"num": 30, "correct": "D", "stem": "다음 중 법을 집행하는 기관으로 바르게 짝지어진 것은?", "options": [{"label": "A", "text": "경찰과 군대"}, {"label": "B", "text": "검찰과 국회"}, {"label": "C", "text": "국회와 경찰"}, {"label": "D", "text": "경찰과 검찰"}], "explanation": "Cảnh sát điều tra và Viện Kiểm sát thực hiện chức năng truy tố, nên 경찰과 검찰 là cặp cơ quan thực thi pháp luật phù hợp."}, {"num": 31, "correct": "C", "stem": "한반도에 세워진 최초의 국가는?", "options": [{"label": "A", "text": "고려"}, {"label": "B", "text": "신라"}, {"label": "C", "text": "고조선"}, {"label": "D", "text": "고구려"}], "explanation": "고조선 được xem là nhà nước đầu tiên trong lịch sử Hàn Quốc và gắn với truyền thuyết Dangun Wanggeom."}, {"num": 32, "correct": "D", "stem": "조선 후기에 나타나 정치 개혁과 상공업 발전 등 실생활에 도움이 되는 학문을 강조한 것은?", "options": [{"label": "A", "text": "과학"}, {"label": "B", "text": "유학"}, {"label": "C", "text": "동학"}, {"label": "D", "text": "실학"}], "explanation": "실학 xuất hiện cuối thời Joseon, nhấn mạnh kiến thức thực tiễn, cải cách chính trị, phát triển thương nghiệp và cải thiện đời sống nhân dân."}, {"num": 33, "correct": "A", "stem": "일본에 불교, 한자, 예술과 건축 등 많은 문화를 전해 준 고대 국가는?", "options": [{"label": "A", "text": "백제"}, {"label": "B", "text": "신라"}, {"label": "C", "text": "발해"}, {"label": "D", "text": "고구려"}], "explanation": "백제 có quan hệ giao lưu văn hóa mật thiết với Nhật Bản và truyền bá Phật giáo, chữ Hán, nghệ thuật cùng kiến trúc sang Nhật."}, {"num": 34, "correct": "A", "stem": "경상 지역을 다르게 부르는 말은?", "options": [{"label": "A", "text": "영남"}, {"label": "B", "text": "경남"}, {"label": "C", "text": "호남"}, {"label": "D", "text": "충남"}], "explanation": "Vùng Gyeongsang được gọi là 영남, nghĩa là khu vực nằm phía nam đèo Joryeong. 호남 là tên gọi của vùng Jeolla."}, {"num": 35, "correct": "C", "stem": "지역 주민들이 필요성은 인정하지만 자기 지역에 설치하는 것을 반대하는 시설은?", "options": [{"label": "A", "text": "지하철역"}, {"label": "B", "text": "고속도로"}, {"label": "C", "text": "하수도 처리 시설"}, {"label": "D", "text": "공공기관"}], "explanation": "Nhà máy xử lý nước thải là ví dụ điển hình của hiện tượng NIMBY: người dân công nhận sự cần thiết nhưng phản đối đặt gần nơi mình sinh sống."}, {"num": 36, "correct": "A", "stem": "정동진, 설악산, 대관령이 있는 지역은?", "options": [{"label": "A", "text": "강원"}, {"label": "B", "text": "경기"}, {"label": "C", "text": "제주"}, {"label": "D", "text": "충청"}], "explanation": "정동진, 설악산 và 대관령 đều nằm ở tỉnh Gangwon (강원도), nên A đúng."}], "tables": []}};
